INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath---toiki-wa-akaneiro-japan', 'NDS', 'Breath - Toiki wa Akaneiro (Japan)', '2007', 'Visual Novel', 'Idea Factory', '1', 'Narrative', 'Narrative-driven visual novel with romantic themes.', 'Navigate complex relationships and make story-altering choices.', 'Emotional school-life visual novel.', 'Breath: Toiki wa Akaneiro is a Japanese adventure game focusing on interpersonal drama. Experience a beautifully illustrated story where your decisions impact the protagonist''s romantic life and future.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brick-em-all-ds-europe', 'NDS', 'Brick ''em All DS (Europe)', '2008', 'Puzzle / Action', '505 Games', '1', 'Arcade', 'Arcade-style brick-breaking action.', 'Clear all blocks in each level using a paddle and ball.', 'Fast-paced classic brick breaking.', 'Brick ''em All DS brings addictive arcade fun to your pocket. Master the physics of the bouncing ball and collect power-ups to clear complex patterns of bricks across dozens of colorful and challenging levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brickdown---block-kuzushi-no-france-kakumei-yaa!-japan-enja', 'NDS', 'Brickdown - Block Kuzushi no France Kakumei Yaa! (Japan) (En,Ja)', '2008', 'Puzzle / Action', 'Irem', '1', 'Arcade', 'Fast-paced brick-breaking with a unique French aesthetic.', 'Destroy blocks to advance through historical-themed stages.', 'Stylized and frantic brick breaking.', 'Brickdown offers a fresh take on the genre with quirky visuals and rapid gameplay. Use the dual screen to track the ball and clear blocks in a variety of unique environments and special challenge modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brico-utile-france', 'NDS', 'Brico Utile (France)', '2008', 'Educational', 'Mindscape', '1', 'Training', 'Practical DIY guide and household repair simulation.', 'Learn various DIY skills and solve virtual home repair tasks.', 'Handy household and DIY simulator.', 'Brico Utile acts as a digital toolkit for your NDS. Learn how to perform common home repairs and DIY projects through interactive lessons and simulations, making it both a game and a useful household reference.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bridge-training-europe-enfrdeesit', 'NDS', 'Bridge Training (Europe) (En,Fr,De,Es,It)', '2009', 'Card / Educational', '505 Games', '1', 'Training', 'Card game strategy and professional training.', 'Master the rules and strategies of the game of Bridge.', 'Comprehensive Bridge card game trainer.', 'Bridge Training for NDS provides a structured way to learn the complex card game of Bridge. Features tutorials for beginners and challenging AI for experts, perfect for practicing your bidding and play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brigitte---ernaehrungscoach-germany', 'NDS', 'Brigitte - ErnaehrungsCoach (Germany)', '2008', 'Educational', 'Koch Media', '1', 'Training', 'Health and nutrition management and diet coach.', 'Track your eating habits and follow a healthy lifestyle plan.', 'Digital nutrition and wellness coach.', 'Brigitte: ErnaehrungsCoach provides professional diet advice. Manage your meals, track calories, and follow customized fitness routines designed to help you reach your health goals with the help of your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('broken-sword---shadow-of-the-templars---the-directors-cut-europe-enfrdeesit', 'NDS', 'Broken Sword - Shadow of the Templars - The Director''s Cut (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Revolution Software', '1', 'Narrative', 'Point-and-click adventure with historical mysteries and puzzles.', 'Help George and Nico solve the ancient Templar conspiracy.', 'Remastered classic mystery adventure.', 'Broken Sword: Shadow of the Templars - The Director''s Cut brings the legendary thriller to NDS. Solve complex puzzles, enjoy new narrative segments, and experience a cinematic story that spans the globe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('broken-sword---shadow-of-the-templars---the-directors-cut-usa-enfrdeesit', 'NDS', 'Broken Sword - Shadow of the Templars - The Director''s Cut (USA) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Revolution Software', '1', 'Narrative', 'Point-and-click adventure with historical mysteries and puzzles.', 'Help George and Nico solve the ancient Templar conspiracy.', 'Remastered classic mystery adventure.', 'Broken Sword: Shadow of the Templars - The Director''s Cut brings the legendary thriller to NDS. Solve complex puzzles, enjoy new narrative segments, and experience a cinematic story that spans the globe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brothers-in-arms-ds-europe-enfrdeesit', 'NDS', 'Brothers in Arms DS (Europe) (En,Fr,De,Es,It)', '2008', 'Shooter / Action', 'Gameloft', '1', 'Player vs Environment', 'Tactical squad-based shooter set in WWII.', 'Lead your squad through intense combat missions in Europe.', 'Authentic WWII tactical action.', 'Brothers in Arms DS offers an immersive 3D war experience. Command your team, use cover, and man various vehicles like tanks and jeeps to complete historical missions across 16 different levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brothers-in-arms-ds-usa-enfres', 'NDS', 'Brothers in Arms DS (USA) (En,Fr,Es)', '2008', 'Shooter / Action', 'Gameloft', '1', 'Player vs Environment', 'Tactical squad-based shooter set in WWII.', 'Lead your squad through intense combat missions in Europe.', 'Authentic WWII tactical action.', 'Brothers in Arms DS offers an immersive 3D war experience. Command your team, use cover, and man various vehicles like tanks and jeeps to complete historical missions across 16 different levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble---double-shot-europe-enfrdeesit', 'NDS', 'Bubble Bobble - Double Shot (Europe) (En,Fr,De,Es,It)', '2006', 'Platform / Puzzle', 'Taito', '1-2', 'Arcade', 'Classic bubble-bursting platform action with a character-switching twist.', 'Clear all enemies in 100 levels by trapping them in bubbles.', 'Traditional platforming with three playable characters.', 'Bubble Bobble: Double Shot brings Bub, Bob, and Babs to the NDS. Switch between characters on the fly to utilize their unique colored bubbles and defeat enemies across 100 floors of classic, addictive platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble---double-shot-usa-enfres', 'NDS', 'Bubble Bobble - Double Shot (USA) (En,Fr,Es)', '2006', 'Platform / Puzzle', 'Taito', '1-2', 'Arcade', 'Classic bubble-bursting platform action with a character-switching twist.', 'Clear all enemies in 100 levels by trapping them in bubbles.', 'Traditional platforming with three playable characters.', 'Bubble Bobble: Double Shot brings Bub, Bob, and Babs to the NDS. Switch between characters on the fly to utilize their unique colored bubbles and defeat enemies across 100 floors of classic, addictive platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble-ds-japan', 'NDS', 'Bubble Bobble DS (Japan)', '2007', 'Platform / Puzzle', 'Taito', '1-2', 'Arcade', 'Classic platformer featuring bubble-blowing dragons.', 'Clear 100 stages of enemies to rescue the dragons'' girlfriends.', 'The authentic arcade classic on your handheld.', 'Bubble Bobble DS offers the pure arcade experience. Trap monsters in bubbles and pop them for points in this timeless platformer, now enhanced for the dual-screen NDS with local wireless multiplayer support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble-revolution-europe-enfrdeesit', 'NDS', 'Bubble Bobble Revolution (Europe) (En,Fr,De,Es,It)', '2005', 'Platform / Puzzle', 'Taito', '1-2', 'Arcade', 'Hybrid of classic gameplay and a new "Revolution" mode.', 'Save the bubble dragons across diverse, boss-filled environments.', 'A modern reimagining of the bubble-popping legend.', 'Bubble Bobble Revolution features two games in one: a faithful "Classic" port and a "New" mode with 3D graphics, scrolling levels, and massive boss fights that take full advantage of the NDS hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble-revolution-usa', 'NDS', 'Bubble Bobble Revolution (USA)', '2005', 'Platform / Puzzle', 'Taito', '1-2', 'Arcade', 'Hybrid of classic gameplay and a new "Revolution" mode.', 'Save the bubble dragons across diverse, boss-filled environments.', 'A modern reimagining of the bubble-popping legend.', 'Bubble Bobble Revolution features two games in one: a faithful "Classic" port and a "New" mode with 3D graphics, scrolling levels, and massive boss fights that take full advantage of the NDS hardware.');
