INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-guppies-usa', 'NDS', 'Bubble Guppies (USA)', '2012', 'Educational / Adventure', 'Black Lantern Studios', '1', 'Casual', 'Educational mini-games and interactive storytelling.', 'Help the Bubble Guppies complete underwater missions.', 'Preschool learning adventure under the sea.', 'Join Molly, Gil, and the gang in Bubble Guppies for NDS. Designed for young children, this title features touch-screen activities that teach counting, colors, and music in a vibrant, safe digital environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buffy-the-vampire-slayer---sacrifice-europe-enfrdeesit', 'NDS', 'Buffy the Vampire Slayer - Sacrifice (Europe) (En,Fr,De,Es,It)', '2009', 'Action / Adventure', 'Redtribe', '1', 'Narrative', 'Third-person action with survival horror elements.', 'Fight vampires and demons to close the Hellmouth.', 'Supernatural combat adventure for Buffy fans.', 'Buffy the Vampire Slayer: Sacrifice offers a dark, atmospheric experience on NDS. Use a variety of weapons and martial arts to battle the forces of darkness in 24 levels written by the show''s actual writers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('build-a-bear-workshop---ou-se-font-les-meilleurs-amis-france', 'NDS', 'Build-A-Bear Workshop - Ou Se Font les Meilleurs Amis (France)', '2007', 'Simulation', 'The Game Factory', '1', 'Casual', 'Creative pet simulation and bear customization.', 'Create a furry friend and play mini-games to build a bond.', 'Official Build-A-Bear interactive experience.', 'Build-A-Bear Workshop lets you bring the famous store home. Customize your bear from head to toe, participate in fun activities, and care for your new best friend in this heartwarming NDS simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('build-a-bear-workshop---welcome-to-hugsville-europe-enfresda', 'NDS', 'Build-A-Bear Workshop - Welcome to Hugsville (Europe) (En,Fr,Es,Da)', '2006', 'Simulation', 'The Game Factory', '1', 'Casual', 'Exploration and town management with custom bears.', 'Expand the town of Hugsville and keep the residents happy.', 'A social adventure in the Build-A-Bear world.', 'Welcome to Hugsville takes the franchise to a larger scale. Explore a vibrant town, complete quests for other bears, and decorate your home in this expanded and colorful NDS life simulator.');
