INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('build-a-lot-europe', 'NDS', 'Build-a-Lot (Europe)', '2008', 'Strategy / Simulation', 'HipSoft', '1', 'Resource Management', 'Strategy and time management in real estate.', 'Buy, flip, and build houses to meet neighborhood goals.', 'Addictive real estate tycoon simulation.', 'Build-a-Lot challenges your inner mogul. Manage resources, hire workers, and upgrade properties to maximize profits across multiple cities in this fast-paced and rewarding NDS strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('build-a-lot-usa', 'NDS', 'Build-a-Lot (USA)', '2008', 'Strategy / Simulation', 'HipSoft', '1', 'Resource Management', 'Strategy and time management in real estate.', 'Buy, flip, and build houses to meet neighborhood goals.', 'Addictive real estate tycoon simulation.', 'Build-a-Lot challenges your inner mogul. Manage resources, hire workers, and upgrade properties to maximize profits across multiple cities in this fast-paced and rewarding NDS strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bunnyz-europe-enfrdeesitnl', 'NDS', 'Bunnyz (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation / Adventure', 'Neopica', '1', 'Casual', 'Virtual pet simulation focused on raising rabbits.', 'Feed, groom, and play with your bunnies to keep them healthy.', 'Adorable rabbit care and training sim.', 'Bunnyz allows you to raise up to five different breeds of rabbits. Use the touch screen to pet them and teach them tricks, watching them grow from babies to adults in this cute NDS animal simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burger-island-usa', 'NDS', 'Burger Island (USA)', '2008', 'Simulation / Time Management', 'Traceyware', '1', 'Time Management', 'Time management and fast-paced cooking simulation.', 'Help Patty turn around a failing burger joint and find recipes.', 'Frantic burger-flipping arcade action.', 'Burger Island puts your multitasking skills to the test. Prepare ingredients and serve hungry customers as fast as possible to earn the "Top Chef" title in this colorful and addictive NDS cooking game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burnout-legends-europe-enfrdeesitnl', 'NDS', 'Burnout Legends (Europe) (En,Fr,De,Es,It,Nl)', '2005', 'Racing', 'Criterion Games', '1-4', 'Arcade Racing', 'High-speed arcade racing and vehicular combat.', 'Win races and cause massive crashes to take down rivals.', 'Intense and explosive handheld racing.', 'Burnout Legends brings the high-octane thrills of the series to the NDS. Featuring the signature "Crash Mode" and aggressive racing mechanics, it''s all about speed, risk, and spectacular collisions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burnout-legends-usa-enfres', 'NDS', 'Burnout Legends (USA) (En,Fr,Es)', '2005', 'Racing', 'Criterion Games', '1-4', 'Arcade Racing', 'High-speed arcade racing and vehicular combat.', 'Win races and cause massive crashes to take down rivals.', 'Intense and explosive handheld racing.', 'Burnout Legends brings the high-octane thrills of the series to the NDS. Featuring the signature "Crash Mode" and aggressive racing mechanics, it''s all about speed, risk, and spectacular collisions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('business-ryoku-kentei-ds-japan', 'NDS', 'Business Ryoku Kentei DS (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Training', 'Educational quizzes focused on professional skills.', 'Test and improve your business acumen and etiquette.', 'Professional business knowledge trainer.', 'Business Ryoku Kentei DS provides interactive tests on corporate manners, logic, and economics. It’s designed as a study aid for Japanese professionals looking to sharpen their office skills on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-ds-europe', 'NDS', 'Bust-A-Move DS (Europe)', '2007', 'Puzzle', 'Taito', '1', 'Arcade', 'Puzzle-solving with bubble-matching mechanics.', 'Match three or more colored bubbles to clear the screen.', 'The classic puzzle-bobble experience.', 'Bust-A-Move DS delivers the legendary addictive gameplay. Use the stylus to aim and shoot bubbles, triggering huge chain reactions in multiple modes including an intense 8-player wireless battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-ds-usa', 'NDS', 'Bust-A-Move DS (USA)', '2007', 'Puzzle', 'Taito', '1', 'Arcade', 'Puzzle-solving with bubble-matching mechanics.', 'Match three or more colored bubbles to clear the screen.', 'The classic puzzle-bobble experience.', 'Bust-A-Move DS delivers the legendary addictive gameplay. Use the stylus to aim and shoot bubbles, triggering huge chain reactions in multiple modes including an intense 8-player wireless battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('busy-scissors-usa-enfres', 'NDS', 'Busy Scissors (USA) (En,Fr,Es)', '2009', 'Educational', 'Creat Studios', '1', 'Casual', 'Hair styling and salon simulation with realistic tools.', 'Wash, cut, and style hair to satisfy your salon clients.', 'Detailed professional hair stylist sim.', 'Busy Scissors uses the NDS touch screen to simulate the life of a hairdresser. Master the art of the perfect cut and color using realistic motions with the stylus in this creative and trendy simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('byeorui-kirby---dopang-ildangui-seupgyeok-korea', 'NDS', 'Byeorui Kirby - Dopang Ildangui Seupgyeok (Korea)', '2008', 'Action / Platform', 'HAL Laboratory', '1', 'Arcade', 'Action-platforming with copy abilities and touchscreen mini-games.', 'Retrieve Kirby''s stolen shortcake from a band of thieves.', 'Kirby Squeak Squad Korean edition.', 'Experience classic Kirby action as you battle the Squeaks. Store copy abilities in Kirby''s stomach using the bottom screen and explore vibrant worlds in this delightful handheld platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cop---the-recruit-europe-enfrdeesit', 'NDS', 'C.O.P. - The Recruit (Europe) (En,Fr,De,Es,It)', '2009', 'Action / Adventure', 'Vivid Games', '1', 'Player vs Environment', 'Open-world action-driving adventure with a crime theme.', 'Work as an undercover agent to stop a criminal organization.', 'Ambitious 3D open-world city action.', 'C.O.P. - The Recruit features a fully 3D New York-style city. Drive cars, engage in shootouts, and use high-tech gadgets to complete missions in one of the most technically impressive titles on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cop---the-recruit-usa-enfrdeesit', 'NDS', 'C.O.P. - The Recruit (USA) (En,Fr,De,Es,It)', '2009', 'Action / Adventure', 'Vivid Games', '1', 'Player vs Environment', 'Open-world action-driving adventure with a crime theme.', 'Work as an undercover agent to stop a criminal organization.', 'Ambitious 3D open-world city action.', 'C.O.P. - The Recruit features a fully 3D New York-style city. Drive cars, engage in shootouts, and use high-tech gadgets to complete missions in one of the most technically impressive titles on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('core-usa-enfrdeesit', 'NDS', 'C.O.R.E. (USA) (En,Fr,De,Es,It)', '2009', 'Shooter / Action', 'Coreplay', '1', 'Player vs Environment', 'First-person shooter (FPS) with a dark sci-fi theme.', 'Survive an infested research facility and uncover the truth.', 'Intense 3D sci-fi horror shooter.', 'C.O.R.E. brings classic fast-paced FPS action to the NDS. Navigate through 15 levels filled with traps and mutants, featuring a robust single-player campaign and 4-player deathmatch over local wireless.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cest-pas-sorcier---les-fabuleux-defis-de-fred-&-jamy-france', 'NDS', 'C''Est Pas Sorcier - Les Fabuleux Defis de Fred & Jamy (France)', '2008', 'Educational', 'Mindscape', '1', 'Educational', 'Educational mini-games based on the popular science show.', 'Solve scientific puzzles and complete interactive experiments.', 'Science-focused educational adventure.', 'C''Est Pas Sorcier brings Fred and Jamy to the NDS. Children can learn about the world through various challenges and quizzes that mirror the educational spirit of the famous French television program.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cabelas-dangerous-hunts-2011-usa', 'NDS', 'Cabela''s Dangerous Hunts 2011 (USA)', '2010', 'Sports / Hunting', 'Fun Labs', '1', 'Simulation', 'First-person hunting simulation with dangerous animals.', 'Track and hunt the world''s most aggressive wildlife.', 'Intense trophy hunting action.', 'Cabela''s Dangerous Hunts 2011 puts you face-to-face with lethal predators. Use your skills to survive encounters with lions, bears, and more in a story-driven hunting adventure across global locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cahier-de-vacances-pour-adultes-france', 'NDS', 'Cahier de Vacances pour Adultes (France)', '2009', 'Educational', 'Mindscape', '1', 'Educational', 'Trivia and mental logic puzzles for adults.', 'Refresh your general knowledge and logic skills.', 'Fun summer-style quiz book for adults.', 'Cahier de Vacances pour Adultes offers a nostalgic but challenging collection of quizzes. From history to math, test your IQ and general culture in this digital version of the popular French vacation workbooks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cahier-de-vacances-pour-adultes-2-france', 'NDS', 'Cahier de Vacances pour Adultes 2 (France)', '2010', 'Educational', 'Mindscape', '1', 'Educational', 'Trivia and mental logic puzzles for adults.', 'Refresh your general knowledge and logic skills.', 'Fun summer-style quiz book for adults.', 'The sequel to the popular French brain trainer. Cahier de Vacances pour Adultes 2 features all-new categories and even more challenging puzzles to keep your mind active during your holiday break.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cake-mania-europe-enfrdeesit', 'NDS', 'Cake Mania (Europe) (En,Fr,De,Es,It)', '2007', 'Simulation / Time Management', 'Sandlot Games', '1', 'Time Management', 'Time management and bakery simulation.', 'Help Jill bake and decorate cakes to save her family''s bakery.', 'Fast-paced culinary management fun.', 'Cake Mania on NDS brings the hit PC title to your handheld. Use the stylus to manage orders, bake various cake shapes, and apply toppings as quickly as possible to upgrade your kitchen and save the day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cake-mania-usa', 'NDS', 'Cake Mania (USA)', '2007', 'Simulation / Time Management', 'Sandlot Games', '1', 'Time Management', 'Time management and bakery simulation.', 'Help Jill bake and decorate cakes to save her family''s bakery.', 'Fast-paced culinary management fun.', 'Cake Mania on NDS brings the hit PC title to your handheld. Use the stylus to manage orders, bake various cake shapes, and apply toppings as quickly as possible to upgrade your kitchen and save the day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cake-mania-2---jills-next-adventure!-europe-enfrdeesitnl', 'NDS', 'Cake Mania 2 - Jill''s Next Adventure! (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation / Time Management', 'Sandlot Games', '1', 'Time Management', 'Time management with branching storylines and upgrades.', 'Choose Jill''s path and manage bakeries in unique locations.', 'An expanded sequel to the baking classic.', 'Cake Mania 2 offers multiple endings and new environments. Manage your time across dozens of levels, unlocking specialized kitchen equipment to serve demanding customers in this addictive NDS simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cake-mania-2---jills-next-adventure!-usa', 'NDS', 'Cake Mania 2 - Jill''s Next Adventure! (USA)', '2008', 'Simulation / Time Management', 'Sandlot Games', '1', 'Time Management', 'Time management with branching storylines and upgrades.', 'Choose Jill''s path and manage bakeries in unique locations.', 'An expanded sequel to the baking classic.', 'Cake Mania 2 offers multiple endings and new environments. Manage your time across dozens of levels, unlocking specialized kitchen equipment to serve demanding customers in this addictive NDS simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cake-mania-3-usa', 'NDS', 'Cake Mania 3 (USA)', '2010', 'Simulation / Time Management', 'Sandlot Games', '1', 'Time Management', 'Time management and bakery simulation with time-travel themes.', 'Bake through different historical eras to return Jill home.', 'A time-traveling bakery adventure.', 'Cake Mania 3 takes Jill on a journey through time. Manage bakeries in the Jurassic era, Ancient China, and more, using the touch screen to master era-specific recipes and unique mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('call-of-atlantis-europe-enfrdeesitnl', 'NDS', 'Call of Atlantis (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Puzzle / Adventure', 'Playrix', '1', 'Match-3', 'Match-3 puzzle and adventure with a mythological theme.', 'Collect seven crystals of power to save the city of Atlantis.', 'Mythological puzzle adventure across lands.', 'Call of Atlantis combines match-3 mechanics with hidden object elements. Journey through the ancient world, from Rome to Egypt, to restore the altar of Poseidon in this visually rich NDS puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('call-of-duty---black-ops-europe', 'NDS', 'Call of Duty - Black Ops (Europe)', '2010', 'Shooter / Action', 'n-Space', '1', 'Player vs Environment', 'First-person shooter (FPS) with touch-screen aiming and missions.', 'Complete covert operations behind enemy lines during the Cold War.', 'Intense portable Cold War action.', 'Call of Duty: Black Ops for NDS features a unique campaign separate from the console versions. Engage in stealth missions, fly helicopters, and utilize the iconic N-Zap style aiming for a precise FPS experience.');
