INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('camp-rock---the-final-jam-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Camp Rock - The Final Jam (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Music / Rhythm', 'Artificial Mind & Movement', '1', 'Rhythm-based', 'Rhythm-action and exploration based on the Disney movie.', 'Prepare for the Final Jam at Camp Rock through music and social games.', 'Musical adventure with Mitchie and Shane.', 'Camp Rock: The Final Jam lets you create your own character and join the Camp Rock family. Practice songs, interact with favorite characters, and master the rhythm of the music in this NDSi enhanced title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('camp-rock---the-final-jam-europe-ensvnoda-ndsi-enhanced', 'NDS', 'Camp Rock - The Final Jam (Europe) (En,Sv,No,Da) (NDSi Enhanced)', '2010', 'Music / Rhythm', 'Artificial Mind & Movement', '1', 'Rhythm-based', 'Rhythm-action and exploration based on the Disney movie.', 'Prepare for the Final Jam at Camp Rock through music and social games.', 'Musical adventure with Mitchie and Shane.', 'Camp Rock: The Final Jam lets you create your own character and join the Camp Rock family. Practice songs, interact with favorite characters, and master the rhythm of the music in this NDSi enhanced title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('camping-mama---outdoor-adventures-usa', 'NDS', 'Camping Mama - Outdoor Adventures (USA)', '2011', 'Simulation / Adventure', 'Office Create', '1', 'Casual', 'Survival-themed mini-games and exploration.', 'Explore the great outdoors and master camping skills with Mama.', 'A nature-filled outdoor adventure sim.', 'Camping Mama: Outdoor Adventures takes the "Mama" franchise to the wilderness. Use the stylus to catch fish, build fires, and navigate forest paths in dozens of nature-themed mini-games designed for family fun on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('candace-kanes-candy-factory-usa', 'NDS', 'Candace Kane''s Candy Factory (USA)', '2008', 'Simulation / Time Management', 'Media Enterprises', '1', 'Time Management', 'Time management and puzzle-based candy production.', 'Manage a candy factory and meet production targets.', 'Sweet and frantic time management fun.', 'Help Candace Kane run a successful confectionery business. Mix ingredients, manage conveyor belts, and package various treats as quickly as possible to upgrade your factory and satisfy the town''s sweet tooth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america---super-soldier-europe-enfrdeesit', 'NDS', 'Captain America - Super Soldier (Europe) (En,Fr,De,Es,It)', '2011', 'Action / Adventure', 'Griptonite Games', '1', 'Player vs Environment', '2D side-scrolling beat ''em up and platforming.', 'Infiltrate Hydra''s castle and stop the Super Soldier project.', 'Classic superhero brawling action.', 'Captain America: Super Soldier on NDS features fast-paced combat. Use Cap''s iconic shield to deflect bullets and solve puzzles while battling Baron Zemo’s forces in this action-packed handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america---super-soldier-usa-enfres', 'NDS', 'Captain America - Super Soldier (USA) (En,Fr,Es)', '2011', 'Action / Adventure', 'Griptonite Games', '1', 'Player vs Environment', '2D side-scrolling beat ''em up and platforming.', 'Infiltrate Hydra''s castle and stop the Super Soldier project.', 'Classic superhero brawling action.', 'Captain America: Super Soldier on NDS features fast-paced combat. Use Cap''s iconic shield to deflect bullets and solve puzzles while battling Baron Zemo’s forces in this action-packed handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa---gekitou-no-kiseki-japan', 'NDS', 'Captain Tsubasa - Gekitou no Kiseki (Japan)', '2010', 'Sports / Soccer', 'Klab', '1-2', 'Arcade Sports', 'Soccer simulation with tactical RPG elements.', 'Lead Tsubasa Ozora to victory in the World Youth tournament.', 'Epic anime-style soccer strategy.', 'Known in Europe as "New Kick Off," this title brings the famous manga to life. Command your team using strategic menus to perform gravity-defying special shots and iconic defensive moves in a deep story mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa---new-kick-off-europe-frdeesit', 'NDS', 'Captain Tsubasa - New Kick Off (Europe) (Fr,De,Es,It)', '2006', 'Sports / Soccer', 'Tamsoft', '1-2', 'Arcade Sports', 'Soccer simulation with tactical RPG elements.', 'Lead Tsubasa Ozora to victory in the World Youth tournament.', 'Epic anime-style soccer strategy.', 'Experience the legend of Captain Tsubasa. Manage your team’s stamina and skills to execute "Drive Shots" and "Tiger Shots" in a tactical sports game that perfectly captures the intensity of the classic anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carcassonne-europe-enfrdeit', 'NDS', 'Carcassonne (Europe) (En,Fr,De,It)', '2009', 'Board Game', 'Exozet Games', '1-4', 'Turn-based', 'Digital board game with tile-placement strategy.', 'Build the landscape of Carcassonne and claim territories.', 'Faithful digital port of the award-winning board game.', 'Carcassonne for NDS allows you to play the tabletop classic anywhere. Strategically place tiles to create cities and roads, using your "meeples" to score points against AI or friends in local wireless play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-game-9-japan', 'NDS', 'Card Game 9 (Japan)', '2007', 'Card / Board Game', 'SUCCESS', '1', 'Turn-based', 'Collection of various traditional card games.', 'Master 9 different card games and win tournaments.', 'Comprehensive portable card game library.', 'Card Game 9 offers a clean and simple interface for classic favorites like Poker, Blackjack, and more. It is a perfect choice for casual players looking for a quick card fix on their handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carl-jiisan-no-soratobu-ie-japan', 'NDS', 'Carl Jiisan no Soratobu Ie (Japan)', '2009', 'Adventure', 'Jupiter', '1', 'Narrative', '3D action-adventure with platforming and puzzles.', 'Help Carl and Russell reach Paradise Falls.', 'High-flying adventure based on Pixar''s Up.', 'Play as Carl, Russell, and Dug in this heartwarming adventure. Navigate the South American wilderness, avoid exotic obstacles, and use teamwork to keep Carl''s house floating toward its destination.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carnival-games-europe-enfrdeesitnl', 'NDS', 'Carnival Games (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Party / Mini-Games', 'Cat Daddy Games', '1-4', 'Party', 'Mini-game collection with a carnival theme.', 'Win tickets and prizes across various midway attractions.', 'Fun-filled virtual carnival experience.', 'Carnival Games brings the fun of the fair to the NDS. Master classic games like Skee-ball, Dunk Tank, and Ring Toss using the stylus to unlock wacky outfits and virtual prizes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carnival-games-usa-enfr', 'NDS', 'Carnival Games (USA) (En,Fr)', '2008', 'Party / Mini-Games', 'Cat Daddy Games', '1-4', 'Party', 'Mini-game collection with a carnival theme.', 'Win tickets and prizes across various midway attractions.', 'Fun-filled virtual carnival experience.', 'Carnival Games brings the fun of the fair to the NDS. Master classic games like Skee-ball, Dunk Tank, and Ring Toss using the stylus to unlock wacky outfits and virtual prizes.');
