INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars---motori-ruggenti-italy', 'NDS', 'Cars - Motori Ruggenti (Italy)', '2006', 'Racing', 'Helixe', '1-4', 'Arcade Racing', 'Arcade racing with open-world exploration elements.', 'Win the Piston Cup and help Radiator Springs thrive.', 'The official game of the hit Pixar movie.', 'Cars for NDS lets you experience the story of Lightning McQueen. Explore Radiator Springs, complete missions for local residents, and participate in high-stakes races to prove you are the fastest car in the world.');
