INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-2-usa-enfres-ndsi-enhanced', 'NDS', 'Cars 2 (USA) (En,Fr,Es) (NDSi Enhanced)', '2011', 'Racing / Action', 'Firebrand Games', '1-4', 'Arcade Racing', 'Global spy adventure and high-speed racing.', 'Complete missions for C.H.R.O.M.E. and win the World Grand Prix.', 'Spy-themed racing sequel.', 'Cars 2 for NDS blends racing with action. Train to become a world-class spy, use high-tech gadgets to take out enemies, and race through iconic locations like London and Tokyo in this NDSi-enhanced title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carte-au-tresor-la---le-jeu-video-officiel-france', 'NDS', 'Carte au Tresor, La - Le Jeu Video Officiel (France)', '2007', 'Adventure / Puzzle', 'Artematica', '1', 'Narrative', 'Adventure and puzzle solving based on the TV show.', 'Solve riddles and complete physical challenges to find the treasure.', 'Official French TV show adventure.', 'La Carte au Trésor brings the excitement of the helicopter-based treasure hunt to NDS. Solve cultural puzzles and navigate diverse French landscapes to be the first to find the hidden chest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cartoon-network-racing-europe-enfrdeesitsvnoda', 'NDS', 'Cartoon Network Racing (Europe) (En,Fr,De,Es,It,Sv,No,Da)', '2006', 'Racing', 'Etranges Libellules', '1-4', 'Arcade Racing', 'Kart racing with power-ups and iconic characters.', 'Win the tournament as your favorite Cartoon Network star.', 'All-star cartoon kart racing.', 'Cartoon Network Racing features characters from Johnny Bravo, Dexter''s Lab, and more. Use character-specific "Toon Powers" and master drifting to defeat your rivals in this colorful and nostalgic NDS racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cartoon-network-racing-usa-enfres', 'NDS', 'Cartoon Network Racing (USA) (En,Fr,Es)', '2006', 'Racing', 'Etranges Libellules', '1-4', 'Arcade Racing', 'Kart racing with power-ups and iconic characters.', 'Win the tournament as your favorite Cartoon Network star.', 'All-star cartoon kart racing.', 'Cartoon Network Racing features characters from Johnny Bravo, Dexter''s Lab, and more. Use character-specific "Toon Powers" and master drifting to defeat your rivals in this colorful and nostalgic NDS racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caspers-scare-school---classroom-capers-europe-enfrdeesitnlptsvnodafi', 'NDS', 'Casper''s Scare School - Classroom Capers (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da,Fi)', '2009', 'Platform / Adventure', 'Artech Studios', '1', 'Cartoon Platformer', 'Educational mini-games and classroom simulation.', 'Complete lessons and help Casper graduate from Scare School.', 'Friendly ghost school activities.', 'Casper''s Scare School: Classroom Capers features 24 different lessons to master. Use the NDS stylus to complete puzzles, rhythm games, and science challenges to help Casper become the scariest (or friendliest) ghost in class.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caspers-scare-school---classroom-capers-usa', 'NDS', 'Casper''s Scare School - Classroom Capers (USA)', '2009', 'Platform / Adventure', 'Artech Studios', '1', 'Cartoon Platformer', 'Educational mini-games and classroom simulation.', 'Complete lessons and help Casper graduate from Scare School.', 'Friendly ghost school activities.', 'Casper''s Scare School: Classroom Capers features 24 different lessons to master. Use the NDS stylus to complete puzzles, rhythm games, and science challenges to help Casper become the scariest (or friendliest) ghost in class.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caspers-scare-school---spooky-sports-day-europe-enfrdeesitnlptsvnoda', 'NDS', 'Casper''s Scare School - Spooky Sports Day (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da)', '2010', 'Sports / Mini-Games', 'Artech Studios', '1-4', 'Family Sports', 'Sports mini-game collection with a spooky theme.', 'Win various athletic events during the Scare School sports day.', 'Supernatural sports competition.', 'Join Casper and his classmates in Spooky Sports Day. Compete in 10 creepy athletic events like the Scare-Athlon and Creepy Relay, utilizing the NDS touch screen and microphone for interactive fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---dawn-of-sorrow-europe-enfrdeesit', 'NDS', 'Castlevania - Dawn of Sorrow (Europe) (En,Fr,De,Es,It)', '2005', 'Action / RPG', 'Konami', '1', 'Metroidvania', 'Action-adventure platformer with the "Tactical Soul" system.', 'Stop a mysterious cult from resurrecting Dracula.', 'Legendary gothic action RPG.', 'Castlevania: Dawn of Sorrow is a masterpiece of the "Metroidvania" genre. Collect souls from fallen enemies to gain over 100 new abilities and explore a massive, beautifully detailed demon castle on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---dawn-of-sorrow-usa', 'NDS', 'Castlevania - Dawn of Sorrow (USA)', '2005', 'Action / RPG', 'Konami', '1', 'Metroidvania', 'Action-adventure platformer with the "Tactical Soul" system.', 'Stop a mysterious cult from resurrecting Dracula.', 'Legendary gothic action RPG.', 'Castlevania: Dawn of Sorrow is a masterpiece of the "Metroidvania" genre. Collect souls from fallen enemies to gain over 100 new abilities and explore a massive, beautifully detailed demon castle on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---order-of-ecclesia-europe-enfrdeesit', 'NDS', 'Castlevania - Order of Ecclesia (Europe) (En,Fr,De,Es,It)', '2008', 'Action / RPG', 'Konami', '1', 'Metroidvania', 'Action-platformer featuring the "Glyph" combat system.', 'Use magical Glyphs to defeat Dracula''s minions as Shanoa.', 'A challenging and beautiful gothic quest.', 'Castlevania: Order of Ecclesia introduces a unique combat system where you absorb symbols to cast spells and conjure weapons. Explore vast outdoor environments and the iconic castle in this visually stunning NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---order-of-ecclesia-korea', 'NDS', 'Castlevania - Order of Ecclesia (Korea)', '2008', 'Action / RPG', 'Konami', '1', 'Metroidvania', 'Action-platformer featuring the "Glyph" combat system.', 'Use magical Glyphs to defeat Dracula''s minions as Shanoa.', 'A challenging and beautiful gothic quest.', 'Castlevania: Order of Ecclesia introduces a unique combat system where you absorb symbols to cast spells and conjure weapons. Explore vast outdoor environments and the iconic castle in this visually stunning NDS title.');
