INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---portrait-of-ruin-europe-enfrdeesit', 'NDS', 'Castlevania - Portrait of Ruin (Europe) (En,Fr,De,Es,It)', '2006', 'Action / RPG', 'Konami', '1', 'Metroidvania', 'Dual-character action platforming with a tag-team system.', 'Switch between Jonathan and Charlotte to explore haunted paintings.', 'Tag-team vampire hunting action.', 'Castlevania: Portrait of Ruin lets you control a vampire hunter and a mage simultaneously. Combine their powers to solve puzzles and defeat massive bosses across diverse worlds inside magical paintings on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---portrait-of-ruin-usa', 'NDS', 'Castlevania - Portrait of Ruin (USA)', '2006', 'Action / RPG', 'Konami', '1', 'Metroidvania', 'Dual-character action platforming with a tag-team system.', 'Switch between Jonathan and Charlotte to explore haunted paintings.', 'Tag-team vampire hunting action.', 'Castlevania: Portrait of Ruin lets you control a vampire hunter and a mage simultaneously. Combine their powers to solve puzzles and defeat massive bosses across diverse worlds inside magical paintings on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casual-classics-europe-enfrdeesitnl', 'NDS', 'Casual Classics (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Puzzle / Board', 'Game Factory', '1-4', 'Casual Collection', 'Collection of traditional board and parlor games.', 'Win matches in classic games like Chess and Solitaire.', 'Essential casual game compilation.', 'Casual Classics provides a suite of timeless favorites. Enjoy high-quality digital versions of Chess, Backgammon, and more with clean graphics and intuitive touch controls, making it the perfect traveling companion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casual-mania-europe-enfrdeesitnl', 'NDS', 'Casual Mania (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Puzzle / Board', 'Game Factory', '1-4', 'Casual Collection', 'Fast-paced puzzle and time-management challenges.', 'Complete a variety of arcade puzzles to reach high scores.', 'Frantic puzzle-mania collection.', 'Casual Mania offers a mix of addictive puzzle genres. From match-3 to hidden objects, this title provides short, engaging gameplay sessions designed for quick fun and mental stimulation on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catan-europe-ende', 'NDS', 'Catan (Europe) (En,De)', '2008', 'Board Game', 'Exozet Games', '1-4', 'Turn-based', 'Digital board game with resource management and trading.', 'Settle the island of Catan and reach 10 victory points.', 'Official handheld port of the board game hit.', 'Catan for NDS brings the strategic depth of the original tabletop game to life. Trade resources, build settlements, and compete against clever AI personalities or friends in this faithful and portable adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catch!-touch!-yoshi!-japan', 'NDS', 'Catch! Touch! Yoshi! (Japan)', '2005', 'Action / Puzzle', 'Artoon', '1', 'Stylus Action', 'Arcade action where you draw paths for Yoshi.', 'Guide Yoshi through the clouds by drawing lines with the stylus.', 'Creative stylus-driven Yoshi adventure.', 'Known in the West as Yoshi Touch & Go, this title uses the dual screens to create a vertical playground. Draw clouds to guide Yoshi, circle enemies to turn them into bubbles, and aim for the highest score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cate-west---the-vanishing-files-europe-enfrdeesit', 'NDS', 'Cate West - The Vanishing Files (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure / Hidden Object', 'Gameshastra', '1', 'Mystery', 'Hidden object mystery with detective puzzles.', 'Help Cate West solve a series of unsolvable crimes.', 'Cinematic supernatural detective mystery.', 'Cate West: The Vanishing Files features atmospheric crime scenes. Find hidden clues, piece together evidence, and solve complex puzzles to catch a mysterious culprit in this engaging NDS investigative adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cate-west---the-vanishing-files-usa', 'NDS', 'Cate West - The Vanishing Files (USA)', '2008', 'Adventure / Hidden Object', 'Gameshastra', '1', 'Mystery', 'Hidden object mystery with detective puzzles.', 'Help Cate West solve a series of unsolvable crimes.', 'Cinematic supernatural detective mystery.', 'Cate West: The Vanishing Files features atmospheric crime scenes. Find hidden clues, piece together evidence, and solve complex puzzles to catch a mysterious culprit in this engaging NDS investigative adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cats-&-dogs---the-revenge-of-kitty-galore---the-videogame-europe-enfrdeesitnl', 'NDS', 'Cats & Dogs - The Revenge of Kitty Galore - The Videogame (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Action / Adventure', 'Amaze Entertainment', '1', 'Family Action', 'Action-adventure with pet-themed gadgets and stealth.', 'Stop the evil cat spy Kitty Galore from taking over the world.', 'Heroic pets in a spy-action quest.', 'Based on the film, Cats & Dogs: The Revenge of Kitty Galore lets you control both canine and feline agents. Use high-tech gadgets and teamwork to complete missions and stop a global "cat-astrophe" on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catz-europe-enfrdeesit', 'NDS', 'Catz (Europe) (En,Fr,De,Es,It)', '2006', 'Simulation / Pet', 'Creatures Inc.', '1', 'Virtual Pet', 'Virtual pet simulation for cat lovers.', 'Adopt and care for your own kittens to keep them happy.', 'Sweet and relaxing kitten care sim.', 'Catz lets you choose from various breeds of adorable kittens. Feed, groom, and play with your pets using the touch screen, and watch them develop unique personalities as they grow in your virtual home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catz-japan', 'NDS', 'Catz (Japan)', '2006', 'Simulation / Pet', 'Creatures Inc.', '1', 'Virtual Pet', 'Virtual pet simulation for cat lovers.', 'Adopt and care for your own kittens to keep them happy.', 'Sweet and relaxing kitten care sim.', 'Catz lets you choose from various breeds of adorable kittens. Feed, groom, and play with your pets using the touch screen, and watch them develop unique personalities as they grow in your virtual home.');
