INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catz-2---daisuki-nyan-nyan-park-japan', 'NDS', 'Catz 2 - Daisuki Nyan Nyan Park (Japan)', '2008', 'Simulation / Pet', 'Creatures Inc.', '1', 'Virtual Pet', 'Enhanced virtual pet simulation with park exploration.', 'Raise your kittens and take them to play in a feline park.', 'Expanded cat care and socialization.', 'Catz 2 improves on the original with more breeds and a dedicated park area. Interact with other cats, unlock new toys, and dress up your kittens in cute outfits in this delightful NDS pet simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catz-2-europe-enfrdeesitnlsvnoda', 'NDS', 'Catz 2 (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2008', 'Simulation / Pet', 'Creatures Inc.', '1', 'Virtual Pet', 'Enhanced virtual pet simulation with park exploration.', 'Raise your kittens and take them to play in a feline park.', 'Expanded cat care and socialization.', 'Catz 2 improves on the original with more breeds and a dedicated park area. Interact with other cats, unlock new toys, and dress up your kittens in cute outfits in this delightful NDS pet simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cavallo-&-pony---la-scuola-di-equitazione-europe-frit', 'NDS', 'Cavallo & Pony - La Scuola di Equitazione (Europe) (Fr,It)', '2009', 'Simulation / Horse', 'Raylight Studios', '1', 'Animal Care', 'Equestrian simulation and riding adventure.', 'Train your pony and learn the art of professional riding.', 'Educational horse care and riding sim.', 'Cavallo & Pony invites you to manage your own stable. Learn the basics of horse grooming, health, and riding techniques while preparing for prestigious show-jumping competitions on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cedric---lanniversaire-de-chen-france', 'NDS', 'Cedric - L''Anniversaire de Chen (France)', '2006', 'Adventure / Puzzle', 'Cinégroupe', '1', 'Narrative', 'Mini-game collection and narrative adventure.', 'Help Cedric organize the perfect birthday party for Chen.', 'Heartwarming adventure for children.', 'Based on the French comic, Cédric: L''Anniversaire de Chen features fun mini-games and a charming story. Help Cedric navigate his daily life and complete tasks to win the heart of his classmate, Chen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cesar-millans-dog-whisperer-usa-enfres', 'NDS', 'Cesar Millan''s Dog Whisperer (USA) (En,Fr,Es)', '2008', 'Simulation / Pet', 'Behaviour Interactive', '1', 'Animal Training', 'Educational dog training and behavioral simulation.', 'Help dog owners solve their pets'' behavioral problems.', 'Professional dog training with the expert.', 'Cesar Millan''s Dog Whisperer teaches you the "Cesar Way." Use the touch screen to correct bad habits, learn about dog psychology, and restore balance to dozens of virtual dog-and-owner pairs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chajara!-gaeguri-jungsa-keroro---teullingeurimchatgi-daejakjeon!-korea', 'NDS', 'Chajara! Gaeguri Jungsa Keroro - Teullingeurimchatgi Daejakjeon! (Korea)', '2009', 'Action / Adventure', 'NX Games', '1', 'Anime Action', '"Spot the difference" puzzles featuring Keroro characters.', 'Find the differences between two images before time runs out.', 'Fun Keroro-themed picture puzzles.', 'Join Sergeant Keroro and his squad in this colorful puzzle game. Test your observation skills across hundreds of "spot the difference" levels featuring iconic scenes from the popular Korean/Japanese anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('challenge-me---brain-puzzles-europe-enfrdeesit', 'NDS', 'Challenge Me - Brain Puzzles (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle / Brain', 'OXO Games', '1', 'Brain Training', 'Logic and math-based brain training puzzles.', 'Solve Sudoku, Kakuro, and other logic games to stay sharp.', 'Diverse mental workout collection.', 'Challenge Me: Brain Puzzles provides hundreds of hours of mental stimulation. With various difficulty levels and a clean interface, it’s a perfect tool for anyone looking to improve their logic and memory on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('challenge-me---brain-puzzles-2-usa-enfres', 'NDS', 'Challenge Me - Brain Puzzles 2 (USA) (En,Fr,Es)', '2010', 'Puzzle / Brain', 'OXO Games', '1', 'Brain Training', 'Logic and math-based brain training puzzles.', 'Solve Sudoku, Kakuro, and other logic games to stay sharp.', 'Diverse mental workout collection.', 'Challenge Me: Brain Puzzles 2 raises the stakes with more complex logic grids and all-new puzzle types. Track your progress and challenge your daily high scores in this comprehensive NDS brain trainer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('challenge-me---maths-workout-europe-enfrdeesit', 'NDS', 'Challenge Me - Maths Workout (Europe) (En,Fr,De,Es,It)', '2009', 'Educational / Maths', 'OXO Games', '1', 'Educational', 'Mathematical drills and calculation puzzles.', 'Improve your mental arithmetic through rapid-fire exercises.', 'Fun and educational math trainer.', 'Challenge Me: Maths Workout makes learning numbers engaging. Practice addition, subtraction, and more through various mini-games designed to boost your calculation speed and numerical accuracy on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon---to-dye-for!-usa', 'NDS', 'Chameleon - To Dye For! (USA)', '2006', 'Puzzle / Action', 'Vicarious Visions', '1', 'Arcade Puzzle', 'Color-matching puzzle game with a chameleon theme.', 'Change the chameleon''s color to match and clear tiles.', 'Vivid and strategic color puzzler.', 'Chameleon: To Dye For! is a fast-paced puzzle game where you must think ahead. Swap colors quickly to match falling blocks and trigger chain reactions in multiple game modes that test your reflexes and logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-pony-usa', 'NDS', 'Championship Pony (USA)', '2008', 'Simulation / Horse', 'Amaze Entertainment', '1', 'Animal Care', 'Horse racing and pony care simulation.', 'Breed and train the ultimate champion pony for racing.', 'Competitive pony racing and grooming.', 'Championship Pony on NDS lets you experience the life of a jockey. Groom your pony to keep it happy, train its stats, and compete in various racing circuits to win prestigious trophies in this equestrian simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaotic---shadow-warriors-usa-enfr', 'NDS', 'Chaotic - Shadow Warriors (USA) (En,Fr)', '2009', 'Action / Card', 'Game Factory', '1', 'Player vs Player', 'Tactical card-based RPG with creature combat.', 'Build a powerful deck and defeat the Shadow Warriors.', 'Strategic creature battling adventure.', 'Based on the hit animated series, Chaotic: Shadow Warriors brings the card game to life. Scan creatures, build your ultimate team, and engage in tactical turn-based battles to save the world of Perim on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charlottes-web-europe-enfrdeesit', 'NDS', 'Charlotte''s Web (Europe) (En,Fr,De,Es,It)', '2006', 'Adventure', 'Stormfront Studios', '1', 'Story-driven', '2D platforming and mini-game collection.', 'Help Wilbur the pig and Charlotte the spider save the farm.', 'Heartwarming farm-themed adventure.', 'Join the beloved characters from Charlotte''s Web in this NDS adventure. Navigate through levels with Wilbur and participate in carnival-style mini-games that capture the magic of the classic children''s story.');
