INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chase-the---felix-meets-felicity-europe-enfrdeesit', 'NDS', 'Chase, The - Felix Meets Felicity (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure / Puzzle', 'Namco', '1', 'Story Adventure', 'High-speed platforming and "chase" mechanics.', 'Navigate obstacles to reach your partner before time runs out.', 'Frantic and romantic arcade platforming.', 'The Chase: Felix Meets Felicity is a unique platformer where love is the goal. Use the stylus to draw paths, avoid hazards, and speed through the city to ensure your date doesn''t leave without you.');
