INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cheer-we-go-usa-ndsi-enhanced', 'NDS', 'Cheer We Go (USA) (NDSi Enhanced)', '2010', 'Sports / Rhythm', 'EA Bright Light', '1', 'Cheerleading Rhythm', 'Rhythm-based dancing and cheerleading simulation.', 'Master cheer routines to lead your team to the championship.', 'High-energy cheer and rhythm action.', 'Cheer We Go puts you in the pom-poms of an aspiring cheerleader. Follow the beat with the stylus, learn complex routines, and experience a story about friendship and competition in this NDSi enhanced title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cheetah-girls-the---passport-to-stardom-usa', 'NDS', 'Cheetah Girls, The - Passport to Stardom (USA)', '2008', 'Music / Adventure', 'Disney Interactive', '1', 'Pop Star Adventure', 'Musical adventure and world-traveling mini-games.', 'Tour the world and perform as The Cheetah Girls.', 'International pop-star adventure.', 'Join Aqua, Chanel, and Dorinda in Passport to Stardom. Travel to India, Spain, and more, mastering dance moves and musical challenges to become a global sensation on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cheetah-girls-the---pop-star-sensations-usa', 'NDS', 'Cheetah Girls, The - Pop Star Sensations (USA)', '2009', 'Music / Rhythm', 'Disney Interactive', '1', 'Pop Music Rhythm', 'Rhythm-action and fashion simulation.', 'Compete in music competitions and master the stage.', 'Pop-star training and performance.', 'The Cheetah Girls: Pop Star Sensations focuses on the path to fame. Practice your singing and dancing, customize your stage outfits, and perform hit songs to win over the crowd and the judges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chess-europe-enfrdeesit', 'NDS', 'Chess (Europe) (En,Fr,De,Es,It)', '2007', 'Board Game', 'Mindscape', '1-2', 'Classic Strategy', 'Strategy-based board game simulation.', 'Defeat the computer or friends in the classic game of Chess.', 'Digital version of the timeless strategy game.', 'Chess for NDS offers a clean, professional interface for players of all levels. Features multiple difficulty modes and local wireless play, making it the perfect way to practice your grandmaster skills on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chess-for-kids-europe-enfrdeesit', 'NDS', 'Chess for Kids (Europe) (En,Fr,De,Es,It)', '2008', 'Educational / Board', 'Game Factory', '1', 'Educational Strategy', 'Educational strategy and board game.', 'Learn the rules of chess through fun tutorials and games.', 'Child-friendly chess learning tool.', 'Chess for Kids makes the complex game of chess accessible. With colorful characters, step-by-step tutorials, and simplified challenges, it''s the ideal way for young players to master the board on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster---the-art-of-learning-europe-enfrdeesitnl', 'NDS', 'Chessmaster - The Art of Learning (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Board Game', 'Ubisoft', '1-2', 'Chess Simulation', 'Chess simulation with deep tutorials and masterclasses.', 'Learn from Josh Waitzkin and improve your chess ELO.', 'The gold standard of portable chess trainers.', 'Chessmaster: The Art of Learning is more than just a game; it''s a teacher. Follow narrated tutorials, solve thousands of chess puzzles, and play against a variety of AI personalities to master the game.');
