INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chis-sweet-home---chi-ga-ouchi-ni-yatte-kita-japan', 'NDS', 'Chi''s Sweet Home - Chi ga Ouchi ni Yatte Kita (Japan)', '2009', 'Adventure', 'Compile Heart', '1', 'Anime Slice of Life', 'Virtual pet simulation and daily life adventure.', 'Care for the kitten Chi and explore her neighborhood.', 'Adorable kitten life simulation.', 'Based on the popular manga, Chi''s Sweet Home brings the tiny kitten to NDS. Feed her, play with her, and see the world through her eyes in this charming and relaxing pet care adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chibi-maruko-chan-ds---maru-chan-no-machi-japan', 'NDS', 'Chibi Maruko-chan DS - Maru-chan no Machi (Japan)', '2007', 'Adventure', 'Bandai Namco', '1', 'Anime Story', 'Town-building and social simulation.', 'Help Maruko-chan build her dream town and meet friends.', 'Charming social sim based on the anime.', 'Chibi Maruko-chan DS lets you interact with the cast of the classic series. Complete tasks for neighbors, play mini-games, and watch your town grow in this nostalgic and cute Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chibi-robo!---park-patrol-usa', 'NDS', 'Chibi-Robo! - Park Patrol (USA)', '2007', 'Adventure / Simulation', 'Nintendo', '1', 'Environmental Adventure', 'Environmental simulation and real-time management.', 'Use Chibi-Robo to revitalize a park and grow flowers.', 'Eco-friendly tiny robot adventure.', 'Chibi-Robo! Park Patrol puts you in control of the 4-inch hero. Use your tools to plant seeds, fight off smog-monsters, and transform a dirty wasteland into a beautiful blooming park on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-attack-ds-europe-enfrde', 'NDS', 'Chicken Attack DS (Europe) (En,Fr,De)', '2009', 'Shooter / Arcade', 'InterActive Vision', '1', 'Arcade Shooter', 'Brick-breaking arcade action with a poultry twist.', 'Save the chicks by breaking blocks and defeating bosses.', 'Farm-themed Arkanoid-style gameplay.', 'Chicken Attack DS combines classic block-breaking with unique power-ups. Guide your mother hen through dozens of levels, using her specialized abilities to rescue her babies from the clutches of evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-blaster-europe-enfrdeesit', 'NDS', 'Chicken Blaster (Europe) (En,Fr,De,Es,It)', '2009', 'Shooter / Arcade', 'InterActive Vision', '1', 'Arcade Shooter', 'Gallery shooter and arcade action.', 'Blast away wacky chickens to reach high scores.', 'Frantic and humorous target shooting.', 'Chicken Blaster is a fast-paced gallery shooter where you must clear the screen of feathered foes. Use different weapons and power-ups to maximize your score across various farmyard environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-hunter-usa-enfrdeesitnl', 'NDS', 'Chicken Hunter (USA) (En,Fr,De,Es,It,Nl)', '2008', 'Shooter / Arcade', 'InterActive Vision', '1', 'Arcade Shooter', 'Gallery shooter and target practice.', 'Hunt the elusive chickens across various locations.', 'Classic "Moorhuhn" style hunting action.', 'Chicken Hunter (Moorhuhn) brings the German phenomenon to NDS. Test your reflexes as you aim for the highest score by shooting various types of chickens in this simple but addictive arcade shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-little---ace-in-action-europe-enfrdeesit', 'NDS', 'Chicken Little - Ace in Action (Europe) (En,Fr,De,Es,It)', '2006', 'Action / Platform', 'Disney Interactive', '1', 'Animated Action', 'Third-person action-adventure with sci-fi combat.', 'Use high-tech vehicles and weapons to stop an alien invasion.', 'Heroic sci-fi action with Chicken Little.', 'Chicken Little: Ace in Action features the "movie-within-a-movie" characters. Control Ace, Runt, and Abby in intense land and air combat missions to save the solar system from robot invaders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-little---ace-in-action-usa', 'NDS', 'Chicken Little - Ace in Action (USA)', '2006', 'Action / Platform', 'Disney Interactive', '1', 'Animated Action', 'Third-person action-adventure with sci-fi combat.', 'Use high-tech vehicles and weapons to stop an alien invasion.', 'Heroic sci-fi action with Chicken Little.', 'Chicken Little: Ace in Action features the "movie-within-a-movie" characters. Control Ace, Runt, and Abby in intense land and air combat missions to save the solar system from robot invaders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-little---uchuu-saikyou-no-team-japan', 'NDS', 'Chicken Little - Uchuu Saikyou no Team (Japan)', '2007', 'Action / Platform', 'Disney Interactive', '1', 'Animated Action', 'Third-person action-adventure with sci-fi combat.', 'Use high-tech vehicles and weapons to stop an alien invasion.', 'Heroic sci-fi action with Chicken Little.', 'Chicken Little: Ace in Action features the "movie-within-a-movie" characters. Control Ace, Runt, and Abby in intense land and air combat missions to save the solar system from robot invaders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-shoot-europe-enfrdeesit', 'NDS', 'Chicken Shoot (Europe) (En,Fr,De,Es,It)', '2007', 'Shooter / Arcade', 'Frontline Studios', '1', 'Gallery Shooter', 'Gallery shooter with various levels and mini-games.', 'Eliminate the chicken infestation across multiple locales.', 'Whimsical arcade shooting gallery.', 'Chicken Shoot offers a lighthearted take on the shooter genre. Aim your stylus to blast crazy chickens in various settings, including the farm and the jungle, in this easy-to-pick-up NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-shoot-usa-enfrdeesit', 'NDS', 'Chicken Shoot (USA) (En,Fr,De,Es,It)', '2007', 'Shooter / Arcade', 'Frontline Studios', '1', 'Gallery Shooter', 'Gallery shooter with various levels and mini-games.', 'Eliminate the chicken infestation across multiple locales.', 'Whimsical arcade shooting gallery.', 'Chicken Shoot offers a lighthearted take on the shooter genre. Aim your stylus to blast crazy chickens in various settings, including the farm and the jungle, in this easy-to-pick-up NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chiffres-et-des-lettres-des---lentrainement-cerebral-maximum!-france', 'NDS', 'Chiffres et des Lettres, Des - L''Entrainement Cerebral Maximum! (France)', '2007', 'Educational / Puzzle', 'France Télévisions', '1', 'Brain Training', 'Mental arithmetic and vocabulary puzzles.', 'Solve math and word challenges based on the famous TV show.', 'Brain training based on the French hit show.', 'Des Chiffres et des Lettres brings the legendary French TV game to your NDS. Test your mental calculation speed and French vocabulary with daily drills and competitive modes designed to keep your brain sharp.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---france-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - France ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Navigate France using maps, phrasebooks, and expert tips.', 'Digital travel guide for exploring France.', 'Part of the famous Japanese travel series, Chikyuu no Arukikata DS - France provides detailed maps of Paris and beyond. It features a phrasebook, currency converter, and a database of top tourist spots for the 2007-2008 season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---hawaii-07-08---oahu-tou-japan', 'NDS', 'Chikyuu no Arukikata DS - Hawaii ''07-''08 - Oahu-tou (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Explore the island of Oahu with local tips and maps.', 'Portable travel companion for Hawaii.', 'Plan your perfect tropical getaway to Hawaii with this interactive guide. Focuses on Oahu, offering restaurant recommendations, shopping guides, and essential travel phrases for Japanese tourists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---hong-kong-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - Hong Kong ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Navigate Hong Kong''s streets, markets, and transit.', 'Comprehensive digital guide for Hong Kong.', 'Discover the vibrant culture of Hong Kong. This NDS guide includes specialized maps, food guides for dim sum lovers, and local transportation tips updated for the 2007-2008 travel season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---igirisu-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - Igirisu ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Tour the United Kingdom with historical and travel info.', 'Essential UK travel guide for NDS.', 'Explore London and the British countryside. This digital guide offers a deep look into UK culture, including subway maps, essential English phrases, and a catalog of must-see historical landmarks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---italia-07-08---roma-milano-firenze-venezia-japan', 'NDS', 'Chikyuu no Arukikata DS - Italia ''07-''08 - Roma, Milano, Firenze, Venezia (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Travel through Rome, Milan, Florence, and Venice.', 'The ultimate Italian city-hopping guide.', 'Navigate the four major cities of Italy with ease. Featuring detailed city maps and dining guides for Rome, Milan, Florence, and Venice, this is an indispensable tool for Japanese travelers visiting Italy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---new-york-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - New York ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Navigate the Big Apple with maps and tourist info.', 'Digital guide for the ultimate NYC trip.', 'Experience New York City on your NDS. This guide covers everything from Manhattan skyscrapers to Brooklyn''s hidden gems, complete with a subway guide and essential "city that never sleeps" survival tips.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---seoul-busan-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - Seoul, Busan ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Explore Seoul and Busan with maps and language aids.', 'Comprehensive travel guide for South Korea.', 'Discover the best of Seoul and Busan. This NDS title provides cultural insights, shopping hotspots, and essential Korean phrases, making it a perfect digital companion for touring South Korea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---shanghai-hangzhou-suzhou-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - Shanghai, Hangzhou, Suzhou ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Tour the historic and modern sites of East China.', 'Digital guide for Shanghai and surrounding cities.', 'Explore the rapid growth of Shanghai and the classical beauty of Hangzhou and Suzhou. Features detailed maps and cultural guides optimized for Japanese business and leisure travelers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---taiwan-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - Taiwan ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Discover the food and culture of Taiwan.', 'Essential digital guide for Taiwan travel.', 'From Taipei''s night markets to the island''s natural beauty, this guide provides interactive maps, a food dictionary, and local transit information for a perfect trip to Taiwan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chikyuu-no-arukikata-ds---thai-07-08-japan', 'NDS', 'Chikyuu no Arukikata DS - Thai ''07-''08 (Japan)', '2007', 'Reference / Travel', 'Diamond Big', '1', 'Travel Guide', 'Interactive travel guide and database.', 'Navigate Thailand''s temples, beaches, and cities.', 'Portable travel assistant for Thailand.', 'Plan your visit to Bangkok and the islands with this detailed guide. Includes cultural etiquette tips, food recommendations, and essential Thai phrases for travelers on the move.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('children-of-mana-europe-enfrdeesit', 'NDS', 'Children of Mana (Europe) (En,Fr,De,Es,It)', '2006', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Action-RPG with dungeon crawling and real-time combat.', 'Defeat the "Mana" threat and restore world balance.', 'A beautiful handheld entry in the Mana series.', 'Children of Mana brings lush 2D visuals and frantic real-time action to the NDS. Choose from four unique heroes and explore randomly generated dungeons while leveling up your skills and collecting powerful weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('children-of-mana-usa', 'NDS', 'Children of Mana (USA)', '2006', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Action-RPG with dungeon crawling and real-time combat.', 'Defeat the "Mana" threat and restore world balance.', 'A beautiful handheld entry in the Mana series.', 'Children of Mana brings lush 2D visuals and frantic real-time action to the NDS. Choose from four unique heroes and explore randomly generated dungeons while leveling up your skills and collecting powerful weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chishiki-ou-series---train-master-japan', 'NDS', 'Chishiki-ou Series - Train Master (Japan)', '2007', 'Educational / Simulation', 'Success', '1', 'Train Management', 'Simulation and trivia based on train operation.', 'Master the knowledge and skills of a professional train conductor.', 'Deep simulation for Japanese train enthusiasts.', 'Train Master is the ultimate quiz and simulation for railway fans. Test your knowledge of train models, schedules, and operations in a comprehensive database of Japanese railway history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cho-geukjangpan-gaeguri-jungsa-keroro-the-movie---cheongongdaemoheom-korea', 'NDS', 'Cho Geukjangpan Gaeguri Jungsa Keroro the Movie - Cheongongdaemoheom (Korea)', '2007', 'Action / Adventure', 'Bandai Namco', '1', 'Anime Adventure', '2D platforming and action based on the Keroro movie.', 'Help the Keroro Platoon survive a sky-high adventure.', 'High-flying anime action platformer.', 'Based on the first Keroro Gunsou movie, this platformer lets you control the alien frogs through challenging levels in the sky. Use unique abilities to defeat bosses and complete the mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cho-geukjangpan-gaeguri-jungsa-keroro-the-movie---dragon-warriors-korea', 'NDS', 'Cho Geukjangpan Gaeguri Jungsa Keroro the Movie - Dragon Warriors (Korea)', '2007', 'Action / Adventure', 'Bandai Namco', '1', 'Anime Adventure', '2D platforming and action with dragon-themed powers.', 'Battle as the Keroro Platoon to stop a dragon invasion.', 'Action-packed dragon warrior adventure.', 'Join Sgt. Frog in this epic movie tie-in. Transform into powerful dragon forms to defeat enemies in a mix of platforming and combat levels designed for fans of the hit anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocobo-to-mahou-no-ehon---majo-to-shoujo-to-5-nin-no-yuusha-japan', 'NDS', 'Chocobo to Mahou no Ehon - Majo to Shoujo to 5-nin no Yuusha (Japan)', '2008', 'Action / Adventure', 'Square Enix', '1', 'Fantasy Adventure', 'Adventure and mini-game collection with Final Fantasy characters.', 'Solve puzzles and win mini-games to restore a magical book.', 'Charming Chocobo storybook adventure.', 'Known as Final Fantasy Fables: Chocobo Tales, this sequel features a deep card-battle system and creative touch-screen mini-games inspired by classic fairy tales within the Final Fantasy universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocobo-to-mahou-no-ehon-japan', 'NDS', 'Chocobo to Mahou no Ehon (Japan)', '2006', 'Action / Adventure', 'Square Enix', '1', 'Fantasy Adventure', 'Adventure and mini-game collection with Final Fantasy characters.', 'Solve puzzles and win mini-games to restore a magical book.', 'Charming Chocobo storybook adventure.', 'The first entry in the Chocobo Tales series. Use the stylus to participate in pop-up book adventures and collect cards to duel against iconic Final Fantasy monsters in a whimsical story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocoken-no-dekitate-sweets-wagon-japan', 'NDS', 'Chocoken no Dekitate Sweets Wagon (Japan)', '2008', 'Simulation / Cooking', 'MTO', '1', 'Cooking Simulation', 'Cooking and management simulation.', 'Manage a mobile sweets wagon and bake delicious treats.', 'Cute puppy-themed bakery simulation.', 'Join the Chocoken (Chocolate Dogs) in their mobile bakery. Use the stylus to mix, bake, and decorate various cakes and cookies to satisfy customers and expand your wagon''s menu.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocoken-no-omise---patissier-&-sweets-shop-game-japan', 'NDS', 'Chocoken no Omise - Patissier & Sweets Shop Game (Japan)', '2007', 'Simulation / Cooking', 'MTO', '1', 'Shop Management', 'Shop management and social simulation.', 'Run a successful patisserie and become a master sweets maker.', 'Adorable sweets shop management game.', 'In Chocoken no Omise, you manage every aspect of a bakery. From choosing ingredients to decorating the shop, work alongside cute pups to create the most popular sweets shop in town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocoken-no-sweets-department---patissier-ikusei-simulation-game-japan', 'NDS', 'Chocoken no Sweets Department - Patissier Ikusei Simulation Game (Japan)', '2008', 'Simulation / Cooking', 'MTO', '1', 'Cooking Simulation', 'Career simulation and educational mini-games.', 'Train as a patisserie apprentice and master complex recipes.', 'Baking career and skill simulation.', 'This title focuses on the "education" of a sweets maker. Practice your baking skills through various touch-screen exercises and learn the science behind creating the perfect dessert with the Chocoken pups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocolatier-usa-enfr', 'NDS', 'Chocolatier (USA) (En,Fr)', '2008', 'Simulation / Strategy', 'Big Splash Games', '1', 'Business Simulation', 'Strategy and business management in the chocolate industry.', 'Build a global chocolate empire by finding exotic ingredients.', 'Deep and addictive chocolate tycoon sim.', 'Chocolatier takes you across the globe. Buy low and sell high, discover secret recipes, and manage factories to become a world-renowned chocolate mogul in this polished NDS strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chokkan-hitofude-japan', 'NDS', 'Chokkan Hitofude (Japan)', '2006', 'Puzzle / Art', 'Nintendo', '1', 'Calligraphy Puzzle', 'Minimalist puzzle game using single-stroke drawing.', 'Clear tiles by drawing a single continuous line.', 'Addictive and stylish brain-teasing puzzle.', 'Known as Polarium, this game challenges your spatial logic. Flip black and white tiles by drawing one line to clear rows in a race against time or in a series of complex puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chokkan!-asonde-rilakkuma-japan', 'NDS', 'Chokkan! Asonde Rilakkuma (Japan)', '2006', 'Puzzle / Casual', 'Interchannel', '1', 'Casual Puzzle', 'Virtual pet simulation and mini-games.', 'Relax and play with Rilakkuma and his lazy friends.', 'Stress-free "healing" game with Rilakkuma.', 'Chokkan! Asonde Rilakkuma is a collection of simple, charming mini-games. Interact with the famous "relax bear" through the touch screen in a game designed to provide a calm and cute experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chotto-aima-no-colpile-ds-japan', 'NDS', 'Chotto Aima no Colpile DS (Japan)', '2006', 'Puzzle / Casual', 'Interchannel', '1', 'Casual Puzzle', 'Daily life simulation and social interaction.', 'Build relationships and manage your daily schedule.', 'Quirky and relaxing lifestyle simulation.', 'Colpile DS offers a unique "pocket life" experience. Spend time with your virtual companions, participate in daily activities, and enjoy the slow-paced charm of this Japanese social simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-gekijouban-keroro-gunsou---enshuu-da-yo!---zenin-shuugou-japan', 'NDS', 'Chou Gekijouban Keroro Gunsou - Enshuu Da yo! - Zenin Shuugou (Japan)', '2007', 'Action / Adventure', 'Bandai Namco', '1', 'Anime Adventure', 'Mini-game collection and action based on the anime.', 'Complete various comedic missions with the Keroro Platoon.', 'Wacky anime-themed mini-game party.', 'This Keroro title features dozens of fast-paced mini-games that capture the humor of the show. Use the stylus and microphone to help the platoon in their (failed) attempts to conquer Earth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-gekijouban-keroro-gunsou---gekishin-dragon-warriors-de-arimasu!-japan', 'NDS', 'Chou Gekijouban Keroro Gunsou - Gekishin Dragon Warriors de Arimasu! (Japan)', '2006', 'Action / Adventure', 'Bandai Namco', '1', 'Anime Adventure', '2D action platformer with transformation mechanics.', 'Use dragon powers to defeat enemies and save the world.', 'The Japanese version of Dragon Warriors.', 'Control the Keroro Platoon as they transform into powerful dragons. This 2D platformer features great animations and boss battles that follow the plot of the Sgt. Frog feature film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-gekijouban-keroro-gunsou-3---tenkuu-daibouken-de-arimasu!-japan', 'NDS', 'Chou Gekijouban Keroro Gunsou 3 - Tenkuu Daibouken de Arimasu! (Japan)', '2008', 'Action / Adventure', 'Bandai Namco', '1', 'Anime Adventure', 'Action-adventure with 3D elements.', 'Explore sky ruins and defeat enemies as Sgt. Frog.', 'Epic sky-high adventure with the Keroro squad.', 'The third movie-based title for NDS. Navigate complex 3D-style platforming levels, utilize new team-based abilities, and enjoy a story filled with the signature humor of the Keroro Gunsou series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-kantan---boki-nyuumon-ds-japan', 'NDS', 'Chou Kantan - Boki Nyuumon DS (Japan)', '2006', 'Educational / Finance', 'Success', '1', 'Accounting Training', 'Educational simulation for bookkeeping.', 'Learn the basics of Boki (bookkeeping) through interactive lessons.', 'Practical accounting and business trainer.', 'Chou Kantan - Boki Nyuumon DS simplifies the complex world of Japanese bookkeeping. It’s an interactive textbook that uses the NDS to teach financial management and accounting skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-kaseki-monster-battle---gekitotsu-galaxy-japan', 'NDS', 'Chou Kaseki Monster Battle - Gekitotsu Galaxy (Japan)', '2008', 'Action / RPG', 'Nintendo', '1', 'Monster Battle RPG', 'Fossil hunting and creature battling RPG.', 'Excavate powerful monsters and battle across the galaxy.', 'Sci-fi fossil-battling adventure.', 'Known as Fossil Fighters: Champions in the West, this title lets you dig up prehistoric monsters, clean them with the stylus, and use them in tactical 3-on-3 battles in a vast space-faring quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-meisaku-suiri-adventure-ds---raymond-chandler-gensaku---saraba-itoshiki-hito-yo-japan', 'NDS', 'Chou Meisaku Suiri Adventure DS - Raymond Chandler Gensaku - Saraba Itoshiki Hito yo (Japan)', '2007', 'Adventure / Mystery', 'Arc System Works', '1', 'Detective Adventure', 'Visual novel mystery with point-and-click investigation.', 'Solve a noir murder mystery as detective Philip Marlowe.', 'A hard-boiled detective mystery based on Chandler.', 'Experience Raymond Chandler''s classic "Farewell, My Lovely" on NDS. As Philip Marlowe, you must navigate a web of lies, search for clues using the touch screen, and solve a gripping noir case in this atmospheric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-nekketsu-koukou-kunio-kun---dodgeball-bu-japan', 'NDS', 'Chou Nekketsu Koukou Kunio-kun - Dodgeball-bu (Japan)', '2008', 'Sports / Action', 'Technos Japan', '4', 'Arcade Sports', 'Arcade sports action with specialized combat moves.', 'Win the Dodgeball championship through intense matches.', 'The high-octane revival of Kunio-kun Dodgeball.', 'Super Hot-Blooded High School Kunio-kun: Dodgeball Club brings the NES classic to the NDS. Execute devastating "Super Shots" and engage in frantic, bone-crunching dodgeball matches with local wireless multiplayer support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-shittou-caduceus-japan', 'NDS', 'Chou Shittou Caduceus (Japan)', '2005', 'Simulation / Medical', 'Atlus', '1', 'Medical Simulation', 'Surgical simulation with high-stakes medical drama.', 'Perform life-saving surgeries using mystical healing powers.', 'Known as Trauma Center: Under the Knife in the West.', 'Use the NDS stylus as a scalpel, laser, and needle. Perform high-precision operations to stop a bio-terrorist virus known as GUILT in this intense and acclaimed medical thriller from Atlus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-shittou-caduceus-japan-rev-1', 'NDS', 'Chou Shittou Caduceus (Japan) (Rev 1)', '2005', 'Simulation / Medical', 'Atlus', '1', 'Medical Simulation', 'Surgical simulation with high-stakes medical drama.', 'Perform life-saving surgeries using mystical healing powers.', 'Known as Trauma Center: Under the Knife in the West.', 'Use the NDS stylus as a scalpel, laser, and needle. Perform high-precision operations to stop a bio-terrorist virus known as GUILT in this intense and acclaimed medical thriller from Atlus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-soujuu-mecha-mg-japan', 'NDS', 'Chou Soujuu Mecha MG (Japan)', '2006', 'Action / Simulation', 'Sandlot', '1', 'Mecha Action', 'Action-combat featuring giant pilotable robots.', 'Battle enemy mechs and complete missions using manual controls.', 'Innovative giant robot action from Sandlot.', 'Chou Soujuu Mecha MG features over 100 unique mechs. The bottom screen acts as a physical cockpit with levers and buttons you must manipulate to move your giant machine and defeat enemies in massive 3D environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou!!-nep-league-ds-japan', 'NDS', 'Chou!! Nep League DS (Japan)', '2008', 'Party / Trivia', 'Konami', '4', 'TV Show Party Game', 'Quiz and trivia based on the popular Japanese TV show.', 'Compete in various language and logic mini-games.', 'Fun and educational Japanese TV quiz game.', 'Based on the hit Fuji TV show, Chou!! Nep League DS challenges your kanji knowledge and quick thinking. Play through signature rounds like "Jet" and "Five League" in this engaging local trivia experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choyeolhyeolgogyo-kunio-gun-pigubu-korea', 'NDS', 'Choyeolhyeolgogyo Kunio-gun Pigubu (Korea)', '2009', 'Sports / Action', 'Technos Japan', '4', 'Arcade Sports', 'Arcade sports action with specialized combat moves.', 'Win the Dodgeball championship through intense matches.', 'The Korean release of Kunio-kun Dodgeball.', 'Experience the intense dodgeball action of the Kunio-kun series. Master unique team formations and powerful signature attacks to dominate the court in this classic arcade sports revival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('christmas-carol-a-europe-enfresnl', 'NDS', 'Christmas Carol, A (Europe) (En,Fr,Es,Nl)', '2009', 'Adventure / Platformer', 'Electronic Arts', '1', 'Story Adventure', 'Point-and-click adventure with classic holiday storytelling.', 'Follow Ebenezer Scrooge''s journey to discover the Christmas spirit.', 'Official game of the Disney movie adaptation.', 'Experience Charles Dickens'' masterpiece like never before. Solve environmental puzzles and play through key scenes from the film to help Scrooge learn the true meaning of Christmas on your NDS.');
