INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chronicles-of-mystery---curse-of-the-ancient-temple-europe-enfrdeesit', 'NDS', 'Chronicles of Mystery - Curse of the Ancient Temple (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure / Puzzle', 'City Interactive', '1', 'Point and Click', 'Hidden object and point-and-click puzzle solving.', 'Uncover a dark secret hidden within an ancient temple.', 'Mystery adventure with Sylvie Leroux.', 'Join young archaeologist Sylvie Leroux in Chronicles of Mystery. Search for hidden objects, solve complex logic puzzles, and follow a trail of clues across the Mediterranean to solve an ancient Curse.');
