INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chronicles-of-narnia-the---prince-caspian-europe', 'NDS', 'Chronicles of Narnia, The - Prince Caspian (Europe)', '2008', 'Action / Adventure', 'Traveller''s Tales', '1', 'Fantasy Action', 'Action-RPG with character switching and team combat.', 'Battle the forces of Miraz to restore Caspian to the throne.', 'Epic fantasy adventure in the world of Narnia.', 'Control over 20 playable characters from the Narnia universe. Switch between heroes to solve puzzles and engage in large-scale battles in this deep, story-driven action-RPG for the NDS.');
