INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chronicles-of-narnia-the---the-lion-the-witch-and-the-wardrobe-europe-endesvda', 'NDS', 'Chronicles of Narnia, The - The Lion, the Witch and the Wardrobe (Europe) (En,De,Sv,Da)', '2006', 'Action / Adventure', 'Traveller''s Tales', '1', 'Fantasy Action', 'Action-adventure with teamwork and special abilities.', 'Defeat the White Witch and bring winter to an end in Narnia.', 'The magical movie adventure on handheld.', 'Play as the four Pevensie siblings. Each child has unique skills needed to navigate the snowy lands of Narnia, battle wolves, and restore the true King, Aslan, in this classic adventure.');
