INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-europe-enfr', 'NDS', 'Chrono Trigger (Europe) (En,Fr)', '2008', 'RPG', 'Square Enix', '1', 'JRPG Classic', 'Turn-based JRPG with time-travel mechanics and dual-techs.', 'Travel through time to save the future from Lavos.', 'The definitive version of the greatest RPG of all time.', 'Chrono Trigger for NDS includes all content from previous versions plus new dungeons and a localized script. Experience the epic story across multiple eras with the dual-screen interface and touch-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-japan-enja', 'NDS', 'Chrono Trigger (Japan) (En,Ja)', '2008', 'RPG', 'Square Enix', '1', 'JRPG Classic', 'Turn-based JRPG with time-travel mechanics and dual-techs.', 'Travel through time to save the future from Lavos.', 'The definitive version of the greatest RPG of all time.', 'Chrono Trigger for NDS includes all content from previous versions plus new dungeons and a localized script. Experience the epic story across multiple eras with the dual-screen interface and touch-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-usa-enfr', 'NDS', 'Chrono Trigger (USA) (En,Fr)', '2008', 'RPG', 'Square Enix', '1', 'JRPG Classic', 'Turn-based JRPG with time-travel mechanics and dual-techs.', 'Travel through time to save the future from Lavos.', 'The definitive version of the greatest RPG of all time.', 'Chrono Trigger for NDS includes all content from previous versions plus new dungeons and a localized script. Experience the epic story across multiple eras with the dual-screen interface and touch-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chronos-twin-europe-enfrdeesit', 'NDS', 'Chronos Twin (Europe) (En,Fr,De,Es,It)', '2007', 'Platformer / Puzzle', 'Amaze Entertainment', '1', 'Time Manipulation', '2D side-scrolling platformer with dual-screen mechanics.', 'Control two characters in different timelines simultaneously.', 'Unique time-splitting action platformer.', 'Chronos Twin challenges you to play on both screens at once. Your character exists in the past on the top screen and the present on the bottom; your actions in one affect the other in this mind-bending adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrysler-classic-racing-europe-enfrdeesit', 'NDS', 'Chrysler Classic Racing (Europe) (En,Fr,De,Es,It)', '2008', 'Racing', 'Destination Software', '4', 'Classic Racing', 'Arcade racing with licensed Chrysler vehicles.', 'Win races and unlock classic Chrysler cars from history.', 'Retro-themed racing with classic style.', 'Chrysler Classic Racing lets you drive iconic vehicles from the 1930s to the present. Race through diverse tracks, upgrade your vintage cars, and compete for the top spot in this nostalgic racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chubaw-desu-yo!---kyoshou-recipe-shuu-japan', 'NDS', 'Chubaw Desu yo! - Kyoshou Recipe Shuu (Japan)', '2009', 'Simulation / Cooking', 'Bandai Namco', '1', 'Cooking Reference', 'Cooking simulation and recipe database.', 'Learn over 100 professional recipes from a famous chef.', 'Professional cooking guide and simulator.', 'Based on the Japanese TV program, this title acts as a digital cookbook. Master professional culinary techniques through interactive lessons and use your NDS in the kitchen to follow master-class recipes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-e-cheeses-gameroom-usa', 'NDS', 'Chuck E. Cheese''s Gameroom (USA)', '2007', 'Party / Minigames', 'Rebellion', '4', 'Family Party', 'Mini-game collection with a family-friendly arcade theme.', 'Win tickets and play classic arcade games with Chuck E. Cheese.', 'Virtual arcade fun for younger players.', 'Chuck E. Cheese''s Gameroom brings the fun of the pizza parlor to NDS. Play dozens of ticket-based mini-games like Skee-ball and basketball to win virtual prizes in a safe, fun environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-e-cheeses-party-games-usa', 'NDS', 'Chuck E. Cheese''s Party Games (USA)', '2007', 'Party / Minigames', 'Rebellion', '4', 'Family Party', 'Mini-game collection with a family-friendly arcade theme.', 'Win tickets and play classic arcade games with Chuck E. Cheese.', 'Virtual arcade fun for younger players.', 'Chuck E. Cheese''s Party Games features a variety of quick-fire challenges. Compete against friends or AI in a celebration of classic carnival and arcade games designed specifically for children.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-e-cheeses-playhouse-usa', 'NDS', 'Chuck E. Cheese''s Playhouse (USA)', '2008', 'Party / Minigames', 'Rebellion', '4', 'Kids Party', 'Educational and creative mini-games for toddlers.', 'Complete simple tasks and learn through play with Chuck E.', 'Fun learning activities for preschoolers.', 'Chuck E. Cheese''s Playhouse offers a collection of basic educational games. From coloring to simple counting, it provides an interactive playground for the youngest NDS fans to enjoy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuldong!-rescue-force-ds-korea', 'NDS', 'Chuldong! Rescue Force DS (Korea)', '2009', 'Action / Adventure', 'Natsume', '1', 'Hero Rescue', 'Action-adventure based on the Japanese Rescue Force series.', 'Complete high-stakes rescue missions and stop disasters.', 'Heroic emergency rescue action.', 'Join the Rescue Force squad to save civilians from natural disasters and mechanical threats. Use specialized vehicles and tools to clear paths and protect the city in this high-energy mission-based title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chungjeon!-hanguginui-sangsingnyeok-ds-korea', 'NDS', 'Chungjeon! Hanguginui Sangsingnyeok DS (Korea)', '2009', 'Education / Creativity', 'NHN', '1', 'Brain Training', 'Educational trivia and general knowledge.', 'Test and improve your knowledge of Korean culture and facts.', 'Korean general knowledge trainer.', 'Chungjeon! Hanguginui Sangsingnyeok DS is an interactive quiz game designed to boost your "common sense" and cultural literacy in Korea, covering history, language, and social etiquette.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuugaku-eitango-target-1800-ds-japan', 'NDS', 'Chuugaku Eitango Target 1800 DS (Japan)', '2006', 'Education / Language', 'Bandai Namco', '1', 'English Vocabulary', 'Language learning and vocabulary drills.', 'Master 1,800 essential English words for academic success.', 'Comprehensive English vocabulary trainer.', 'Based on the popular Japanese study book, this title offers structured English vocabulary lessons. It features spelling tests, pronunciation guides, and progress tracking for students preparing for exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuukana-janshi-tenho-painyan-remix-japan', 'NDS', 'Chuukana Janshi Tenho Painyan Remix (Japan)', '2007', 'Tabletop / Mahjong', 'Arc System Works', '1', 'Japanese Mahjong', 'Mahjong with anime-style characters and story.', 'Defeat opponents in Mahjong to progress through the narrative.', 'Quirky anime Mahjong remix.', 'Chuukana Janshi Tenho Painyan Remix blends traditional Mahjong gameplay with lighthearted anime storytelling and character-driven matches, making the classic game more accessible and fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ciao-dream-touch!---happy-anniversary-japan', 'NDS', 'Ciao Dream Touch! - Happy Anniversary (Japan)', '2009', 'Adventure / Simulation', 'Bandai Namco', '1', 'Life Simulation', 'Social simulation and mini-games.', 'Manage your daily life and celebrate a special anniversary.', 'Charming girl-focused social sim.', 'Based on the Ciao manga magazine, this game lets players live out a school life fantasy. Decorate your room, interact with friends, and participate in mini-games to prepare for a big celebration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cid-to-chocobo-no-fushigi-na-dungeon---toki-wasure-no-meikyuu-ds+-japan', 'NDS', 'Cid to Chocobo no Fushigi na Dungeon - Toki Wasure no Meikyuu DS+ (Japan)', '2008', 'RPG / Dungeon Crawler', 'Square Enix', '1', 'Mystery Dungeon', 'Roguelike dungeon crawler with turn-based combat.', 'Explore randomly generated floors to restore lost memories.', 'Final Fantasy Fables: Chocobo''s Dungeon.', 'Join Cid and Chocobo in an expanded version of the classic dungeon crawler. Featuring a deep job system and tactical combat, players must navigate dangerous mazes to save the town of Lostime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cinnamoroll---cinnamon-ball---kurukuru-sweets-paradise-japan', 'NDS', 'Cinnamoroll - Cinnamon Ball - Kurukuru Sweets Paradise (Japan)', '2008', 'Simulation / Kids', 'Bandai Namco', '1', 'Cute Mini Games', 'Puzzle and sweets management.', 'Match ingredients and manage a paradise of sweets.', 'Cute Cinnamoroll-themed puzzle game.', 'Help Sanrio''s Cinnamoroll create the perfect bakery. Use the touch screen to solve puzzles and prepare colorful desserts in this relaxing and adorable sweets simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cinnamoroll---ohanashi-shiyo!---kira-kira-de-kore-cafe-japan', 'NDS', 'Cinnamoroll - Ohanashi Shiyo! - Kira Kira de Kore Cafe (Japan)', '2007', 'Adventure / Kids', 'Bandai Namco', '1', 'Storybook Adventure', 'Communication and social interaction.', 'Interact with Cinnamoroll and manage a cute cafe.', 'Relaxing cafe life with Cinnamoroll.', 'Spend time with the lovable Sanrio puppy. Talk to Cinnamoroll, decorate your cafe, and serve guests in a stress-free environment designed for fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('city-life-ds-europe-enfrdeesit', 'NDS', 'City Life DS (Europe) (En,Fr,De,Es,It)', '2006', 'Simulation / City Building', 'Monte Cristo', '1', 'City Management', 'City-building and management simulation.', 'Design, build, and manage a thriving modern metropolis.', 'Deep urban planning simulation.', 'City Life DS allows you to be the mayor. Manage residential areas, business districts, and public services while balancing the needs of six different social classes in this complex handheld tycoon game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clash-king-v201-japan', 'NDS', 'Clash King V201 (Japan)', '2008', 'Action / Arcade', 'Unknown', '2', 'Arcade Action', 'Action-strategy and car-battling.', 'Win high-stakes car battles and become the Clash King.', 'Explosive vehicle-based combat.', 'Clash King V201 features customizable vehicles and fast-paced arena combat. Strategically equip your car with weapons and armor to defeat rivals and dominate the urban racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-action---devilish-usa', 'NDS', 'Classic Action - Devilish (USA)', '1991', 'Action / Platformer', 'Game Arts', '1', 'Classic Platformer', 'Fast-paced "Breakout" style action with a dark twist.', 'Bounce balls to destroy enemies and navigate gothic stages.', 'Modern revival of the classic Devilish.', 'Classic Action: Devilish transforms traditional brick-breaking into a high-speed adventure. Control two paddles across vertical levels filled with monsters, bosses, and environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-sonic-over-toad', 'NDS', 'Classic Sonic over toad', '2010', 'Platformer / Fan Game', 'Independent', '1', 'Retro Crossover', '2D side-scrolling platformer.', 'Guide Sonic through modified stages to reach the goal.', 'Fan-made mod for classic Sonic fans.', 'A unique community-driven modification that brings Sonic the Hedgehog into new environments. Experience familiar high-speed platforming with creative level designs and unexpected cameos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-word-games-europe-ndsi-enhanced', 'NDS', 'Classic Word Games (Europe) (NDSi Enhanced)', '2010', 'Word / Puzzle', 'Maximum Family Games', '4', 'Word Puzzle', 'Word-based puzzle and logic collection.', 'Solve various crosswords, word searches, and anagrams.', 'Ultimate portable word game library.', 'Classic Word Games offers a wide variety of linguistic challenges. With NDSi camera features for personalization, it’s the perfect title for fans of Scrabble, Boggle, and traditional word puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-word-games-usa-ndsi-enhanced', 'NDS', 'Classic Word Games (USA) (NDSi Enhanced)', '2010', 'Word / Puzzle', 'Maximum Family Games', '4', 'Word Puzzle', 'Word-based puzzle and logic collection.', 'Solve various crosswords, word searches, and anagrams.', 'Ultimate portable word game library.', 'Classic Word Games offers a wide variety of linguistic challenges. With NDSi camera features for personalization, it’s the perfect title for fans of Scrabble, Boggle, and traditional word puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('claymore---gingan-no-majo-japan', 'NDS', 'Claymore - Gingan no Majo (Japan)', '2008', 'Action / RPG', 'Digital Works', '1', 'Anime Action RPG', '2D side-scrolling action and hack-and-slash.', 'Fight through hordes of Yoma as the warrior Clare.', 'Dark fantasy action based on the anime.', 'Experience the brutal world of Claymore on NDS. Master Clare’s sword techniques and manage her "Yoki" energy to defeat powerful Awakened Beings in this faithful manga adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clever-kids---creepy-crawlies-europe-enfrdeesit', 'NDS', 'Clever Kids - Creepy Crawlies (Europe) (En,Fr,De,Es,It)', '2009', 'Education / Kids', 'Maximum Family Games', '1', 'Educational Mini Games', 'Educational mini-games and nature facts.', 'Learn about insects and bugs through interactive puzzles.', 'Bug-themed learning for kids.', 'Part of the Clever Kids series, Creepy Crawlies teaches children about the world of insects using memory games, puzzles, and a digital encyclopedia filled with fascinating bug facts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clever-kids---dino-land-europe-enfrdeesitpt', 'NDS', 'Clever Kids - Dino Land (Europe) (En,Fr,De,Es,It,Pt)', '2009', 'Education / Kids', 'Maximum Family Games', '1', 'Educational Mini Games', 'Educational mini-games and prehistoric facts.', 'Discover the world of dinosaurs through fun activities.', 'Dinosaur-themed educational fun.', 'Clever Kids: Dino Land invites young explorers to solve puzzles and learn about the Jurassic era. Features trivia, matching games, and detailed information about dozens of different dinosaurs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clever-kids---farmyard-fun-europe', 'NDS', 'Clever Kids - Farmyard Fun (Europe)', '2009', 'Education / Kids', 'Maximum Family Games', '1', 'Educational Mini Games', 'Educational mini-games and animal care facts.', 'Manage a virtual farm and learn about farm animals.', 'Farm-themed learning for children.', 'Clever Kids: Farmyard Fun combines educational logic puzzles with a charming farm setting. Kids learn about agriculture and animal husbandry while playing engaging touch-screen games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clever-kids---pirates-europe', 'NDS', 'Clever Kids - Pirates (Europe)', '2009', 'Education / Kids', 'Maximum Family Games', '1', 'Educational Mini Games', 'Educational mini-games and pirate-themed logic.', 'Solve puzzles to find treasure and learn about the high seas.', 'Nautical adventure and learning.', 'Join the Clever Kids on a pirate ship. This title uses a seafaring theme to teach logic, math, and history through interactive mini-games and treasure hunting missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clever-kids---pony-world-europe-enfrdeesitpt', 'NDS', 'Clever Kids - Pony World (Europe) (En,Fr,De,Es,It,Pt)', '2009', 'Education / Kids', 'Maximum Family Games', '1', 'Educational Mini Games', 'Educational mini-games and equestrian facts.', 'Learn about horses and ponies through puzzles and care.', 'Pony-themed educational simulation.', 'Perfect for young horse lovers, Clever Kids: Pony World offers a mix of stable management and educational puzzles that teach kids about different breeds and horse care.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clever!---das-spiel-das-wissen-schafft-germany', 'NDS', 'Clever! - Das Spiel, das Wissen Schafft (Germany)', '2009', 'Quiz / Education', 'Schmidt Spiele', '4', 'Knowledge Game', 'General knowledge trivia and science quizzes.', 'Test your knowledge across multiple categories to win.', 'Scientific trivia based on the German show.', 'Based on the popular German TV program "Clever!", this game challenges players with scientific experiments and general knowledge questions in a fun, competitive format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clique-the---diss-and-make-up-usa-enfres', 'NDS', 'Clique, The - Diss and Make Up (USA) (En,Fr,Es)', '2009', 'Adventure / Drama', 'Konami', '1', 'Teen Story', 'Social simulation and narrative adventure.', 'Navigate social circles and become the ultimate "Queen Bee".', 'Social drama based on the hit book series.', 'Join the "Pretty Committee" in The Clique. Navigate the social halls of OCD, manage friendships, and use your fashion sense and wit to rise to the top of the social ladder.');
