INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clubhouse-games-usa-enfrdeesit', 'NDS', 'Clubhouse Games (USA) (En,Fr,De,Es,It)', '2006', 'Board / Party', 'Nintendo', '1–8', 'Tabletop Collection', 'Collection of classic board, card, and parlor games.', 'Master 42 different games and defeat AI or human opponents.', 'The ultimate portable parlor game collection.', 'Known as 42 All-Time Classics in Europe, Clubhouse Games features everything from Chess and Poker to Bowling and Darts. With intuitive touch controls and local/online multiplayer, it''s the perfect essential for any NDS owner.');
