INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cnae-aprende-con-nosotros---drivers-ed-spain', 'NDS', 'CNAE Aprende con Nosotros - Driver''s Ed (Spain)', '2008', 'Education / Driving', 'CNAE', '1', 'Driving Education', 'Driving theory and educational simulation.', 'Study and pass the Spanish driving license exams.', 'Official Spanish driver''s education tool.', 'Developed with CNAE, this title provides interactive lessons, mock exams, and traffic sign guides for the Spanish driving test. Use your NDS to study on the go and track your progress toward getting your license.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cocina-conmigo!---que-preparamos-hoy-spain', 'NDS', 'Cocina Conmigo! - Que Preparamos Hoy (Spain)', '2008', 'Simulation / Cooking', 'Mindscape', '1', 'Cooking Simulation', 'Interactive cooking guide and recipe database.', 'Follow step-by-step instructions to cook international dishes.', 'Digital chef and kitchen assistant.', 'Known as Cooking Guide: Can''t Decide What to Eat?, this title features over 250 recipes. Use voice commands to turn pages while cooking and learn professional techniques with easy-to-follow video tutorials.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cocoto---kart-racer-europe-enfrdeesit', 'NDS', 'Cocoto - Kart Racer (Europe) (En,Fr,De,Es,It)', '2005', 'Racing / Kart', 'Neko Entertainment', '1–4', 'Cartoon Kart Racing', 'Go-kart racing with power-ups and fantasy characters.', 'Win the championship across 12 unique tracks.', 'Frantic kart racing with Cocoto and friends.', 'Cocoto Kart Racer offers fast-paced arcade racing. Choose from a variety of whimsical characters, use crazy power-ups to sabotaging rivals, and master drifting to take first place in this colorful handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cocoto---kart-racer-usa-enfres', 'NDS', 'Cocoto - Kart Racer (USA) (En,Fr,Es)', '2005', 'Racing / Kart', 'Neko Entertainment', '1–4', 'Cartoon Kart Racing', 'Go-kart racing with power-ups and fantasy characters.', 'Win the championship across 12 unique tracks.', 'Frantic kart racing with Cocoto and friends.', 'Cocoto Kart Racer offers fast-paced arcade racing. Choose from a variety of whimsical characters, use crazy power-ups to sabotaging rivals, and master drifting to take first place in this colorful handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cocoto-racers-europe-enfrdeesit', 'NDS', 'Cocoto Racers (Europe) (En,Fr,De,Es,It)', '2006', 'Racing / Kart', 'Neko Entertainment', '1–4', 'Cartoon Kart Racing', 'Racing and combat with specialized vehicles.', 'Defeat rivals in high-speed races and arena battles.', 'Multi-mode racing adventure.', 'Cocoto Racers expands the universe with various game modes. Experience traditional races or "Battle" mode where survival is the priority, all while utilizing the NDS touch screen for precise control.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-de-la-route---edition-2008-france', 'NDS', 'Code de la Route - Edition 2008 (France)', '2008', 'Education / Driving', 'Mindscape', '1', 'Driving Test Training', 'Educational driving theory and quizzes.', 'Prepare for the French driving exam with official questions.', 'Comprehensive French highway code trainer.', 'Code de la Route 2008 offers a structured way to learn French traffic laws. Practice with official-style tests, analyze your errors, and gain the confidence needed to pass the real exam.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-de-la-route---edition-deluxe-france', 'NDS', 'Code de la Route - Edition Deluxe (France)', '2009', 'Education / Driving', 'Mindscape', '1', 'Driving Test Training', 'Educational driving theory and quizzes.', 'Prepare for the French driving exam with official questions.', 'Comprehensive French highway code trainer.', 'The Deluxe Edition includes more questions and enhanced tracking features. Study French road rules through interactive scenarios and simulated test environments designed for maximum retention.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-de-la-route-france', 'NDS', 'Code de la Route (France)', '2007', 'Education / Driving', 'Mindscape', '1', 'Driving Test Training', 'Educational driving theory and quizzes.', 'Prepare for the French driving exam with official questions.', 'Comprehensive French highway code trainer.', 'A portable study guide for the French driving license. This version includes essential quizzes and information on road safety, priority rules, and traffic signs in an easy-to-navigate NDS format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-de-la-route-ds-france', 'NDS', 'Code de la Route DS (France)', '2007', 'Education / Driving', 'Mindscape', '1', 'Driving Test Training', 'Educational driving theory and quizzes.', 'Prepare for the French driving exam with official questions.', 'Comprehensive French highway code trainer.', 'Code de la Route DS provides a modern interface for learning the French highway code. With hundreds of questions and detailed explanations, it''s a valuable tool for any aspiring driver in France.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-de-la-route-le---moto-et-bsr-france', 'NDS', 'Code de la Route, Le - Moto et BSR (France)', '2009', 'Education / Driving', 'Mindscape', '1', 'Motorcycle License Training', 'Educational driving theory for motorcycles and mopeds.', 'Pass the specific exams for motorcycle (A) and BSR licenses.', 'Specialized French motorcycle theory trainer.', 'This edition focuses on the specific rules of the road for two-wheeled vehicles in France. Learn safety maneuvers and regulations through dedicated quizzes and interactive lessons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-de-la-route-le-france', 'NDS', 'Code de la Route, Le (France)', '2007', 'Education / Driving', 'Mindscape', '1', 'Driving Test Training', 'Educational driving theory and quizzes.', 'Prepare for the French driving exam with official questions.', 'Comprehensive French highway code trainer.', 'A general study aid for the French highway code, offering multiple test modes and progress tracking to help users prepare for their theoretical driving test on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-geass---hangyaku-no-lelouch-japan', 'NDS', 'Code Geass - Hangyaku no Lelouch (Japan)', '2006', 'Adventure / Visual Novel', 'Bandai Namco', '1', 'Anime Story', 'Tactical RPG and visual novel.', 'Lead the rebellion as Lelouch to overthrow the Empire.', 'Strategic anime RPG based on the hit series.', 'Experience the story of Code Geass. Command Knightmare Frames in tactical turn-based battles and make critical decisions in a narrative-driven campaign that mirrors the events of the first season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-geass---hangyaku-no-lelouch-r2---banjou-no-geass-gekijou-japan', 'NDS', 'Code Geass - Hangyaku no Lelouch R2 - Banjou no Geass Gekijou (Japan)', '2008', 'Adventure / Visual Novel', 'Bandai Namco', '1', 'Anime Story', 'Mini-game collection and board game adventure.', 'Compete in various challenges with the Code Geass cast.', 'Whimsical board game with Geass powers.', 'This sequel features a lighter tone with a digital board game format. Play dozens of mini-games as your favorite characters and use "Geass" abilities to gain an advantage over your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-lyoko---fall-of-xana-europe-enfr', 'NDS', 'Code Lyoko - Fall of X.A.N.A. (Europe) (En,Fr)', '2008', 'Action / Adventure', 'Neko Entertainment', '1', 'Cartoon Action', 'Action-RPG with exploration and real-time combat.', 'Infiltrate the digital world of Lyoko to defeat X.A.N.A.', 'Deep RPG adventure for Code Lyoko fans.', 'Fall of X.A.N.A. features a turn-based combat system in the 3D digital realm. Customize your heroes'' powers, explore complex sectors, and stop the virus from infecting the real world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-lyoko---fall-of-xana-usa-enfr', 'NDS', 'Code Lyoko - Fall of X.A.N.A. (USA) (En,Fr)', '2008', 'Action / Adventure', 'Neko Entertainment', '1', 'Cartoon Action', 'Action-RPG with exploration and real-time combat.', 'Infiltrate the digital world of Lyoko to defeat X.A.N.A.', 'Deep RPG adventure for Code Lyoko fans.', 'Fall of X.A.N.A. features a turn-based combat system in the 3D digital realm. Customize your heroes'' powers, explore complex sectors, and stop the virus from infecting the real world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-lyoko-europe-enfresit', 'NDS', 'Code Lyoko (Europe) (En,Fr,Es,It)', '2005', 'Action / Adventure', 'Neko Entertainment', '1', 'Cartoon Platformer', 'Action-adventure with 2D and 3D gameplay.', 'Save the world by jumping between Earth and Lyoko.', 'Dual-world action based on the TV show.', 'Experience the first Code Lyoko game on NDS. Explore the boarding school in 2D and transition to the 3D world of Lyoko to battle monsters and deactivate towers in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-lyoko-usa-enfres', 'NDS', 'Code Lyoko (USA) (En,Fr,Es)', '2005', 'Action / Adventure', 'Neko Entertainment', '1', 'Cartoon Platformer', 'Action-adventure with 2D and 3D gameplay.', 'Save the world by jumping between Earth and Lyoko.', 'Dual-world action based on the TV show.', 'Experience the first Code Lyoko game on NDS. Explore the boarding school in 2D and transition to the 3D world of Lyoko to battle monsters and deactivate towers in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colin-mcrae---dirt-2-europe-enfrdeesit', 'NDS', 'Colin McRae - Dirt 2 (Europe) (En,Fr,De,Es,It)', '2009', 'Racing / Rally', 'Codemasters', '1–4', 'Rally Racing', 'High-speed rally racing across global tracks.', 'Win the world rally championship through diverse events.', 'Intense and realistic portable rally racing.', 'DiRT 2 brings off-road racing to the NDS with impressive 3D graphics. Race across varied terrain, from deserts to city streets, and customize your vehicles to handle the toughest conditions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('color-cross-usa-enfres', 'NDS', 'Color Cross (USA) (En,Fr,Es)', '2008', 'Puzzle / Logic', 'Little Worlds Studio', '1', 'Nonogram Puzzle', 'Logic-based color puzzle game (Nonogram style).', 'Reveal hidden images by filling in squares with the correct colors.', 'Relaxing and colorful logic puzzles.', 'Color Cross puts a spin on the classic Picross formula by adding colors. Solve hundreds of puzzles by logically determining which color goes where to uncover vibrant pixel art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colour-cross-europe-enfrdeesit', 'NDS', 'Colour Cross (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle / Logic', 'Little Worlds Studio', '1', 'Nonogram Puzzle', 'Logic-based color puzzle game (Nonogram style).', 'Reveal hidden images by filling in squares with the correct colors.', 'Relaxing and colorful logic puzzles.', 'Color Cross puts a spin on the classic Picross formula by adding colors. Solve hundreds of puzzles by logically determining which color goes where to uncover vibrant pixel art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('combat-of-giants---dinosaurs-europe-enfrdeesitnlsvnoda', 'NDS', 'Combat of Giants - Dinosaurs (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2008', 'Action / Simulation', 'Glacier', '1', 'Monster Combat', 'Creature combat and customization.', 'Customize your dinosaur and fight for dominance.', 'Epic prehistoric brawling action.', 'Battle as a giant dinosaur! Customize your beast with different skins and attributes, then engage in real-time combat against other prehistoric giants in a quest to save your territory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('combat-of-giants---dragons-europe-enfrdeesitnlsvnoda', 'NDS', 'Combat of Giants - Dragons (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2009', 'Action / Simulation', 'Glacier', '1', 'Monster Combat', 'Creature combat and customization.', 'Train your dragon and defeat the dark forces of the Void.', 'Mythical dragon-battling adventure.', 'Choose your dragon''s element and customize its appearance. Explore vast lands and engage in strategic combat to protect the dragon realm from corruption in this engaging action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('combat-of-giants---mutant-insects-europe-enfrdeesitnlsvnoda', 'NDS', 'Combat of Giants - Mutant Insects (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2009', 'Action / Simulation', 'Glacier', '1', 'Monster Combat', 'Creature combat and customization.', 'Command a swarm of insects to defeat mutant threats.', 'Unique insect-themed battle simulation.', 'Control massive mutant insects! Customize your warrior with different stingers and armor, then battle through infested environments in a quest to become the strongest bug in the hive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('command-and-destroy-europe-enfrdeesit', 'NDS', 'Command and Destroy (Europe) (En,Fr,De,Es,It)', '2009', 'Strategy / Action', 'Zed Two', '1–4', 'Real-Time Strategy', 'Real-time strategy (RTS) with military units.', 'Defeat enemy forces using tactical unit management.', 'Classic 2D real-time strategy action.', 'Command and Destroy brings old-school RTS to the NDS. Manage resources, build bases, and lead tanks and infantry in an epic war between the humans and an alien threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('command-and-destroy-usa', 'NDS', 'Command and Destroy (USA)', '2009', 'Strategy / Action', 'Zed Two', '1–4', 'Real-Time Strategy', 'Real-time strategy (RTS) with military units.', 'Defeat enemy forces using tactical unit management.', 'Classic 2D real-time strategy action.', 'Command and Destroy brings old-school RTS to the NDS. Manage resources, build bases, and lead tanks and infantry in an epic war between the humans and an alien threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('commando---steel-disaster-usa-enfres', 'NDS', 'Commando - Steel Disaster (USA) (En,Fr,Es)', '2008', 'Action / Shooter', 'Nazca / SNK', '1', 'Run and Gun', '2D run-and-gun action.', 'Battle through waves of enemies as a lone commando.', 'Explosive side-scrolling shooter action.', 'Inspired by classics like Metal Slug, Commando: Steel Disaster features intense firefights, massive bosses, and a variety of heavy weaponry. Master the challenge across five different missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contact-europe-enfrdeesit', 'NDS', 'Contact (Europe) (En,Fr,De,Es,It)', '2006', 'RPG / Adventure', 'Grasshopper Manufacture', '1', 'Experimental RPG', 'Action-RPG with dual-screen interaction.', 'Help a stranded scientist return home by guiding a virtual hero.', 'Fourth-wall breaking cult-classic RPG.', 'Contact is a unique RPG where the "Professor" communicates directly with the player. Guide Terry through diverse islands, master different "costumes" for skills, and enjoy a meta-narrative full of charm.');
