INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra---dual-spirits-japan', 'NDS', 'Contra - Dual Spirits (Japan)', '2007', 'Action / Shooter', 'Konami', '1–4', 'Run and Gun', '2D run-and-gun action.', 'Defeat the alien invasion across multiple intense levels.', 'Hardcore side-scrolling shooter action.', 'Contra: Dual Spirits (known as Contra 4 in the USA) celebrates 20 years of the franchise. Battle through dual-screen environments using classic weapons and massive boss fights in this challenging handheld action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-4-usa', 'NDS', 'Contra 4 (USA)', '2007', 'Action / Shooter', 'Konami', '1–4', 'Run and Gun', '2D run-and-gun action.', 'Defeat the alien invasion across multiple intense levels.', 'Hardcore side-scrolling shooter action.', 'Contra 4 brings the legendary arcade difficulty to NDS. Experience 2D side-scrolling combat utilizing both screens, a grappling hook mechanic, and unlockable classic Contra games in this high-octane shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conveni-ds-the---otona-no-keieiryoku-training-japan', 'NDS', 'Conveni DS, The - Otona no Keieiryoku Training (Japan)', '2006', 'Simulation / Business', 'Nintendo', '1', 'Management Training', 'Business management simulation.', 'Manage a successful convenience store and maximize profits.', 'Deep retail tycoon and strategy sim.', 'The Conveni DS challenges you to build a retail empire. Choose your location, stock products, manage staff, and design the layout of your 24/7 shop to attract customers and outsmart competitors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cookie-&-cream-europe-enfrdeesit', 'NDS', 'Cookie & Cream (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle / Action', 'FromSoftware', '1–4', 'Physics Puzzle', 'Cooperative puzzle-platformer.', 'Guide Cookie and Cream to find the moon before the festival.', 'Creative duo-based platforming adventure.', 'From Software brings Cookie & Cream to NDS. Control both characters simultaneously or play with a friend to solve environment-based puzzles and navigate colorful worlds in this charming cooperative quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cookie-&-cream-usa', 'NDS', 'Cookie & Cream (USA)', '2007', 'Puzzle / Action', 'FromSoftware', '1–4', 'Physics Puzzle', 'Cooperative puzzle-platformer.', 'Guide Cookie and Cream to find the moon before the festival.', 'Creative duo-based platforming adventure.', 'From Software brings Cookie & Cream to NDS. Control both characters simultaneously or play with a friend to solve environment-based puzzles and navigate colorful worlds in this charming cooperative quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cookie-shop---create-your-dream-shop-europe-enfr', 'NDS', 'Cookie Shop - Create Your Dream Shop (Europe) (En,Fr)', '2008', 'Simulation / Management', '505 Games', '1', 'Casual Business', 'Shop management and creative baking.', 'Design your dream shop and bake delicious cookies for clients.', 'Sweet bakery management simulation.', 'Cookie Shop lets you unleash your inner pastry chef. Mix ingredients using the touch screen, decorate your cookies with unique toppings, and manage your business to become the most famous baker in town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cookin-idol-i!-my!-mine!---game-de-hirameki!-kirameki!-cooking-japan', 'NDS', 'Cookin'' Idol I! My! Mine! - Game de Hirameki! Kirameki! Cooking (Japan)', '2008', 'Simulation / Cooking', 'Kids Station', '1', 'Cooking Mini-games', 'Rhythm-action and cooking simulation.', 'Master recipes and perform songs based on the anime show.', 'Musical cooking adventure with Main.', 'Based on the NHK show, Cookin'' Idol I! My! Mine! combines rhythm games with culinary tasks. Follow Main''s journey, prepare tasty dishes, and perform on stage in this vibrant Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cooking-guide---cant-decide-what-to-eat-europe', 'NDS', 'Cooking Guide - Can''t Decide What to Eat (Europe)', '2008', 'Simulation / Cooking', 'Nintendo', '1', 'Cooking Guide', 'Interactive digital cookbook and guide.', 'Browse 250+ recipes and follow step-by-step cooking lessons.', 'The ultimate digital kitchen assistant.', 'Cooking Guide transforms your NDS into a chef. Featuring recipes from around the world, voice-command navigation, and instructional videos, it''s a practical tool for anyone looking to master the art of cooking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cooking-mama-europe-deesit', 'NDS', 'Cooking Mama (Europe) (De,Es,It)', '2006', 'Simulation / Cooking', 'Office Create', '1', 'Cooking Mini-games', 'Cooking simulation and mini-games.', 'Complete culinary tasks to create the perfect meal.', 'The game that defined NDS cooking.', 'Cooking Mama lets you chop, fry, and sauté using the stylus. Master dozens of recipes under Mama''s watchful eye in this addictive and accessible simulation that started a global phenomenon.');
