INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('coraline-europe-enfrdeesit', 'NDS', 'Coraline (Europe) (En,Fr,De,Es,It)', '2009', 'Action / Adventure', 'Papaya Studio', '1', 'Dark Fantasy', '2D/3D adventure with puzzles and exploration.', 'Help Coraline navigate the Other World and save her parents.', 'Atmospheric dark fantasy adventure.', 'Based on the Henry Selick film, Coraline for NDS features a unique visual style. Solve environmental puzzles, play mini-games, and avoid the Beldam''s traps in this eerie and faithful movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('coraline-usa-enfres', 'NDS', 'Coraline (USA) (En,Fr,Es)', '2009', 'Action / Adventure', 'Papaya Studio', '1', 'Dark Fantasy', '2D/3D adventure with puzzles and exploration.', 'Help Coraline navigate the Other World and save her parents.', 'Atmospheric dark fantasy adventure.', 'Based on the Henry Selick film, Coraline for NDS features a unique visual style. Solve environmental puzzles, play mini-games, and avoid the Beldam''s traps in this eerie and faithful movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cornelsen-trainer---mathe---klasse-5-europe-ende', 'NDS', 'Cornelsen Trainer - Mathe - Klasse 5 (Europe) (En,De)', '2007', 'Education / Math', 'Cornelsen', '1', 'Math Training', 'Educational mathematics trainer.', 'Practice 5th-grade math skills through interactive drills.', 'Grade-school math learning tool.', 'Cornelsen Trainer provides a structured way to master arithmetic, geometry, and logic. Designed for students, it offers progress tracking and fun exercises to make learning math on the NDS engaging.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cornelsen-trainer---mathe---klasse-6-europe-ende', 'NDS', 'Cornelsen Trainer - Mathe - Klasse 6 (Europe) (En,De)', '2008', 'Education / Math', 'Cornelsen', '1', 'Math Training', 'Educational mathematics trainer.', 'Practice 6th-grade math skills through interactive drills.', 'Grade-school math learning tool.', 'Cornelsen Trainer for 6th Grade advances to more complex equations and mathematical concepts. Use the stylus to solve problems and improve your school grades through regular digital practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('coropata-japan', 'NDS', 'Coropata (Japan)', '2006', 'Puzzle / Action', 'Jupiter', '1', 'Physics Puzzle', 'Physics-based puzzle and "Rube Goldberg" simulator.', 'Arrange objects to trigger a chain reaction and reach goals.', 'Charming physics puzzle and anime sim.', 'Coropata is a rare cult classic. Help a girl named Himawari solve daily tasks by placing items on the screen to create complex mechanical chain reactions in this beautifully animated Japanese puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('corvette-evolution-gt-usa', 'NDS', 'Corvette Evolution GT (USA)', '2009', 'Racing', 'TDK Mediactive', '1–4', 'Arcade Racing', 'Arcade racing with licensed Corvette cars.', 'Race through history and unlock classic Corvette models.', 'Authentic Corvette racing experience.', 'Corvette Evolution GT takes you from the 1950s to the modern era. Customize your ride, master the racing lines on realistic tracks, and prove you are the ultimate Corvette driver on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cory-in-the-house-europe', 'NDS', 'Cory in the House (Europe)', '2007', 'Action / Adventure', 'Human Soft', '1', 'Sitcom Adventure', 'Stealth-action and mini-game collection.', 'Help Cory navigate the White House without getting caught.', 'Stealthy adventure based on the Disney show.', 'In Cory in the House, you must use stealth and gadgets to sneak around the White House. Complete various mini-games and follow a humorous story inspired by the hit Disney Channel series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cory-in-the-house-usa', 'NDS', 'Cory in the House (USA)', '2007', 'Action / Adventure', 'Human Soft', '1', 'Sitcom Adventure', 'Stealth-action and mini-game collection.', 'Help Cory navigate the White House without getting caught.', 'Stealthy adventure based on the Disney show.', 'In Cory in the House, you must use stealth and gadgets to sneak around the White House. Complete various mini-games and follow a humorous story inspired by the hit Disney Channel series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmetic-paradise-europe-enfrit', 'NDS', 'Cosmetic Paradise (Europe) (En,Fr,It)', '2008', 'Simulation / Beauty', 'Micro Application', '1', 'Cosmetic Simulation', 'Beauty and makeup simulation.', 'Style clients and become a master of cosmetics.', 'Trendy makeup and fashion simulator.', 'Cosmetic Paradise lets you run a beauty salon. Apply makeup, style hair, and choose the best accessories for your clients to increase your shop''s reputation and unlock new beauty products.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmetick-paradise---kirei-no-mahou-japan-ndsi-enhanced', 'NDS', 'Cosmetick Paradise - Kirei no Mahou (Japan) (NDSi Enhanced)', '2008', 'Simulation / Beauty', 'Micro Application', '1', 'Cosmetic Simulation', 'Beauty and makeup simulation.', 'Style clients and become a master of cosmetics.', 'Trendy makeup and fashion simulator.', 'This NDSi enhanced title allows you to use the camera for personalized styling. Master the "magic of beauty" by creating perfect looks for various social events and competing in beauty contests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmetick-paradise---make-no-kiseki-japan', 'NDS', 'Cosmetick Paradise - Make no Kiseki (Japan)', '2008', 'Simulation / Beauty', 'Micro Application', '1', 'Cosmetic Simulation', 'Beauty and makeup simulation.', 'Style clients and become a master of cosmetics.', 'Trendy makeup and fashion simulator.', 'The "Make-no Kiseki" edition focuses on the transformation of your clients. Learn professional makeup application techniques and manage your own boutique in this detailed Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmetick-paradise-japan', 'NDS', 'Cosmetick Paradise (Japan)', '2008', 'Simulation / Beauty', 'Micro Application', '1', 'Cosmetic Simulation', 'Beauty and makeup simulation.', 'Style clients and become a master of cosmetics.', 'Trendy makeup and fashion simulator.', 'The original entry in the series. Experience the fun of a virtual beauty salon, where you use the stylus to apply eyeliner, blush, and lipstick to create the most fashionable looks in the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmopolitan---total-relooking-france', 'NDS', 'Cosmopolitan - Total Relooking (France)', '2008', 'Simulation / Beauty', 'Micro Application', '1', 'Fashion Makeover', 'Fashion and beauty simulation.', 'Master the art of makeup and fashion to become a top stylist.', 'French-style virtual makeover and fashion sim.', 'Inspired by the famous magazine, Cosmopolitan: Total Relooking lets you create stunning looks. Manage a beauty salon, apply professional makeup, and style outfits to transform your clients on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('countdown---the-game-europe', 'NDS', 'Countdown - The Game (Europe)', '2009', 'Quiz / Party', 'DTF Games', '1–4', 'TV Quiz', 'Word and number puzzle games based on the TV show.', 'Solve linguistic and mathematical challenges to win the game.', 'Official digital version of the hit TV quiz.', 'Countdown: The Game brings the classic TV show to your handheld. Compete in the Letters and Numbers rounds, aiming to reach the target score before the famous clock runs out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cradle-of-rome-usa-enfrdeesitnl', 'NDS', 'Cradle of Rome (USA) (En,Fr,De,Es,It,Nl)', '2011', 'Puzzle / Match-3', 'Fugazo', '1', 'Casual Puzzle', 'Match-3 puzzle and city-building strategy.', 'Match tiles to gather resources and rebuild the city of Rome.', 'Addictive puzzle and ancient history sim.', 'Cradle of Rome combines classic match-3 mechanics with the strategy of building an empire. Collect gold and materials to construct legendary monuments like the Coliseum across 100 levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crafting-mama-usa', 'NDS', 'Crafting Mama (USA)', '2012', 'Simulation / Cooking', 'Office Create', '1', 'Crafting Mini-games', 'Crafting simulation and creative mini-games.', 'Complete various DIY projects and crafts under Mama''s guidance.', 'Creative hobby-focused "Mama" adventure.', 'Step away from the stove in Crafting Mama. Use the stylus to sew, glue, and assemble over 40 different projects, from birdhouses to jewelry, in this charming creative simulation for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash---mind-over-mutant-europe-enfrdeesitnl', 'NDS', 'Crash - Mind over Mutant (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Action / Platformer', 'Radical Entertainment', '1–2', 'Action Adventure', '3D platforming with "Mutant Hijacking" mechanics.', 'Defeat Cortex and take control of giant mutant creatures.', 'Action-packed platforming with monster combat.', 'In Crash: Mind over Mutant, Crash can now upgrade his favorite mutants. Explore a persistent world, use the mutants'' unique powers to solve puzzles, and stop the evil plot to control everyone''s minds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash---mind-over-mutant-usa-enfrdeesitnl', 'NDS', 'Crash - Mind over Mutant (USA) (En,Fr,De,Es,It,Nl)', '2008', 'Action / Platformer', 'Radical Entertainment', '1–2', 'Action Adventure', '3D platforming with "Mutant Hijacking" mechanics.', 'Defeat Cortex and take control of giant mutant creatures.', 'Action-packed platforming with monster combat.', 'In Crash: Mind over Mutant, Crash can now upgrade his favorite mutants. Explore a persistent world, use the mutants'' unique powers to solve puzzles, and stop the evil plot to control everyone''s minds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-festival-japan', 'NDS', 'Crash Bandicoot Festival (Japan)', '2008', 'Party / Mini-games', 'Dimps', '1–4', 'Multiplayer Party', 'Party game collection with board game elements.', 'Compete in wacky mini-games and earn the most points.', 'Crash Bandicoot''s wild party game debut.', 'Known in the West as Crash Boom Bang!, this title features 40 crazy mini-games. Play as your favorite characters, use items to sabotage rivals, and enjoy local multiplayer fun on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-boom-bang!-europe-enfrdeesit', 'NDS', 'Crash Boom Bang! (Europe) (En,Fr,De,Es,It)', '2006', 'Party / Mini-games', 'Dimps', '1–4', 'Touch Mini-games', 'Party game collection with board game elements.', 'Compete in wacky mini-games and earn the most points.', 'Crash Bandicoot''s wild party game debut.', 'Known in the West as Crash Boom Bang!, this title features 40 crazy mini-games. Play as your favorite characters, use items to sabotage rivals, and enjoy local multiplayer fun on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-boom-bang!-usa', 'NDS', 'Crash Boom Bang! (USA)', '2006', 'Party / Mini-games', 'Dimps', '1–4', 'Touch Mini-games', 'Party game collection with board game elements.', 'Compete in wacky mini-games and earn the most points.', 'Crash Bandicoot''s wild party game debut.', 'Known in the West as Crash Boom Bang!, this title features 40 crazy mini-games. Play as your favorite characters, use items to sabotage rivals, and enjoy local multiplayer fun on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-of-the-titans-europe-enfrdeesitnl', 'NDS', 'Crash of the Titans (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Action / Platformer', 'Radical Entertainment', '1–2', 'Action Adventure', '3D action-platformer with creature-jacking.', 'Use the "Jacking" ability to control powerful titans.', 'Intense brawling and platforming adventure.', 'Crash of the Titans introduces the ability to take over enemies. Use 15 different titans to smash through obstacles and defeat Neo Cortex in this visually impressive 3D NDS adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-of-the-titans-usa', 'NDS', 'Crash of the Titans (USA)', '2007', 'Action / Platformer', 'Radical Entertainment', '1–2', 'Action Adventure', '3D action-platformer with creature-jacking.', 'Use the "Jacking" ability to control powerful titans.', 'Intense brawling and platforming adventure.', 'Crash of the Titans introduces the ability to take over enemies. Use 15 different titans to smash through obstacles and defeat Neo Cortex in this visually impressive 3D NDS adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayola-treasure-adventures-europe-enfrdeesit', 'NDS', 'Crayola Treasure Adventures (Europe) (En,Fr,De,Es,It)', '2007', 'Action / Adventure', 'Behaviour Interactive', '1', 'Cartoon Adventure', 'Coloring and puzzle-solving adventure.', 'Find the hidden treasure by coloring and solving puzzles.', 'Artistic exploration game for children.', 'Crayola Treasure Adventures lets kids use a virtual box of crayons. Explore exotic islands, color in the scenery to solve environmental puzzles, and collect missing colors to restore the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayola-treasure-adventures-usa', 'NDS', 'Crayola Treasure Adventures (USA)', '2007', 'Action / Adventure', 'Behaviour Interactive', '1', 'Cartoon Adventure', 'Coloring and puzzle-solving adventure.', 'Find the hidden treasure by coloring and solving puzzles.', 'Artistic exploration game for children.', 'Crayola Treasure Adventures lets kids use a virtual box of crayons. Explore exotic islands, color in the scenery to solve environmental puzzles, and collect missing colors to restore the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---arashi-o-yobu-cinemaland-kachinko-gachinko-daikatsugeki!-japan', 'NDS', 'Crayon Shin-chan - Arashi o Yobu Cinemaland Kachinko Gachinko Daikatsugeki! (Japan)', '2006', 'Action / Adventure', 'Banpresto', '1', 'Anime Adventure', '2D side-scrolling platformer based on the movies.', 'Complete levels inspired by various Shin-chan films.', 'Cinematic platforming with Shinnosuke.', 'Play through the most iconic moments of Crayon Shin-chan''s film career. Use costumes and transformations to defeat bosses and enjoy the signature humor of the series on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---arashi-o-yobu-nendororoon-daihenshin!-japan', 'NDS', 'Crayon Shin-chan - Arashi o Yobu Nendororoon Daihenshin! (Japan)', '2006', 'Action / Adventure', 'Banpresto', '1', 'Anime Adventure', '2D platforming with clay-themed transformations.', 'Use clay powers to transform and save the world.', 'Unique clay-styled anime platformer.', 'Shin-chan gains the power of clay! Transform into various shapes to solve puzzles and defeat enemies in this creative and colorful Japanese platformer based on the hit anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---obaka-dainin-den---susume!-kasukabe-ninja-tai!-japan', 'NDS', 'Crayon Shin-chan - Obaka Dainin Den - Susume! Kasukabe Ninja Tai! (Japan)', '2007', 'Action / Adventure', 'Banpresto', '1', 'Anime Adventure', '2D action and ninja-themed mini-games.', 'Complete ninja training and stop the Kasukabe threats.', 'Stealthy and hilarious ninja action.', 'Join the Kasukabe Ninja Team in this quirky Shin-chan adventure. Use ninja tools and the touch screen to master stealth techniques and navigate comical challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---shock-gahn!---densetsu-o-yobu-omake-daiketsusen!!-japan', 'NDS', 'Crayon Shin-chan - Shock Gahn! - Densetsu o Yobu Omake Daiketsusen!! (Japan)', '2008', 'Action / Adventure', 'Banpresto', '1', 'Anime Adventure', 'Mini-game collection and action platforming.', 'Collect toys and win challenges in the world of Shin-chan.', 'Wacky anime-themed arcade collection.', 'Experience the "omake" (bonus) side of Shin-chan. Play through a series of fast-paced mini-games and platforming stages filled with collectable figures and classic series references.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan-ds---arashi-o-yobu-nutte-crayoon-daisakusen!-japan', 'NDS', 'Crayon Shin-chan DS - Arashi o Yobu Nutte Crayoon Daisakusen! (Japan)', '2006', 'Action / Puzzle', 'Banpresto', '1', 'Drawing Action', '2D platforming with coloring mechanics.', 'Restore color to the world using magical crayons.', 'Art-based platforming adventure.', 'Shin-chan must use his drawing skills to save the day. Use the NDS stylus to paint objects back into existence, solving puzzles and helping friends in this vibrant handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-chicken---star-karts-usa-enfrdeesit', 'NDS', 'Crazy Chicken - Star Karts (USA) (En,Fr,De,Es,It)', '2008', 'Racing / Arcade', 'Phenomic', '1–4', 'Cartoon Racing', 'Go-kart racing with poultry-themed power-ups.', 'Win the space-themed championship as a crazy chicken.', 'Intergalactic kart racing with Moorhuhn.', 'Crazy Chicken: Star Karts takes the race to outer space. Compete on wild tracks across the galaxy, using unique weapons and boosts to outpace your feathered rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-chicken-adventure---the-pharaohs-treasure-usa-enfrdeesit', 'NDS', 'Crazy Chicken Adventure - The Pharaoh''s Treasure (USA) (En,Fr,De,Es,It)', '2007', 'Action / Adventure', 'Phenomic', '1', 'Cartoon Platformer', '2D side-scrolling platformer with an Egyptian theme.', 'Explore pyramids and find the Pharaoh''s lost treasure.', 'Classic platforming with Moorhuhn.', 'Guide the Crazy Chicken through ancient Egypt. Avoid traps, battle mummies, and collect jewels in this traditional side-scrolling adventure for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-chicken-carnival-europe-enfrdeesit', 'NDS', 'Crazy Chicken Carnival (Europe) (En,Fr,De,Es,It)', '2007', 'Party / Mini-games', 'Phenomic', '1–4', 'Casual Party', 'Carnival-themed mini-game collection.', 'Win prizes and high scores across various midway games.', 'Fun-filled poultry carnival experience.', 'Join the Crazy Chicken at the fair. Play over a dozen carnival-style mini-games, from shooting galleries to tests of strength, all featuring the humor of the Moorhuhn series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-chicken-jumpn-run---atlantis-quest-usa-enfrdeesit', 'NDS', 'Crazy Chicken Jump''n Run - Atlantis Quest (USA) (En,Fr,De,Es,It)', '2006', 'Action / Platformer', 'Phenomic', '1', 'Cartoon Platformer', 'Side-scrolling platformer with underwater levels.', 'Explore the lost city of Atlantis and find artifacts.', 'Nautical platforming with Crazy Chicken.', 'Dive into the deep with Crazy Chicken. Navigate treacherous underwater caves and ancient ruins, avoiding sea creatures while hunting for the treasures of Atlantis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-circus-europe-enfrdeesit', 'NDS', 'Crazy Circus (Europe) (En,Fr,De,Es,It)', '2008', 'Party / Mini-games', 'Easy Interactive', '1–4', 'Circus Mini-games', 'Circus-themed mini-game collection.', 'Perform circus acts and manage the show to entertain the crowd.', 'Big-top spectacle on your handheld.', 'Crazy Circus lets you experience the magic of the ring. Master acrobatics, animal training, and clowning through a variety of touch-screen mini-games to make your circus a hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-frog-collectables---art-school-europe-enfrdeesit', 'NDS', 'Crazy Frog Collectables - Art School (Europe) (En,Fr,De,Es,It)', '2008', 'Education / Art', 'Neko Entertainment', '1', 'Drawing Game', 'Creative art and drawing tutorials.', 'Learn to draw and design with Crazy Frog characters.', 'Digital art school and coloring book.', 'Crazy Frog Collectables: Art School provides step-by-step guides for young artists. Use the stylus to color, trace, and create your own artwork featuring the annoying but iconic frog.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-frog-racer-europe-enfrdeesit', 'NDS', 'Crazy Frog Racer (Europe) (En,Fr,De,Es,It)', '2006', 'Racing / Arcade', 'Neko Entertainment', '1–4', 'Arcade Racing', 'High-speed arcade racing and combat.', 'Win the championship and sabotage rivals as Crazy Frog.', 'Frantic and loud arcade racing.', 'Race through various environments as the Crazy Frog. Use musical weapons and high-speed boosts to dominate the competition in this fast-paced and eccentric handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-machines-europe-enfrdeesit', 'NDS', 'Crazy Machines (Europe) (En,Fr,De,Es,It)', '2005', 'Puzzle / Physics', 'FAKT Software', '1', 'Logic Puzzle', 'Physics-based puzzle "Rube Goldberg" simulator.', 'Build complex machines to solve simple tasks.', 'Brain-teasing engineering puzzles.', 'Crazy Machines challenges your logic. Use gears, ramps, and electricity to build intricate chain reactions and solve over 100 physics-based puzzles on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-machines-germany-ende', 'NDS', 'Crazy Machines (Germany) (En,De)', '2005', 'Puzzle / Physics', 'FAKT Software', '1', 'Logic Puzzle', 'Physics-based puzzle "Rube Goldberg" simulator.', 'Build complex machines to solve simple tasks.', 'Brain-teasing engineering puzzles.', 'Crazy Machines challenges your logic. Use gears, ramps, and electricity to build intricate chain reactions and solve over 100 physics-based puzzles on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-machines-2-europe-enfrdeesit', 'NDS', 'Crazy Machines 2 (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle / Physics', 'FAKT Software', '1', 'Logic Puzzle', 'Advanced physics-based puzzle solving.', 'Create even more complex contraptions to solve challenges.', 'The deeper sequel to the hit puzzle game.', 'Crazy Machines 2 raises the difficulty with new components and realistic physics. Master gravity and mechanics across dozens of levels that will test the mind of any aspiring inventor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-pig-europe-enfrdeesitnl', 'NDS', 'Crazy Pig (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Action / Arcade', 'Interplay', '1', 'Cartoon Arcade', 'Virtual pet simulation and farm life activities.', 'Raise a "crazy pig" and participate in farm mini-games.', 'Quirky and cute pig-raising sim.', 'Crazy Pig offers a fun take on the pet simulator. Care for your pig, play sports, and compete in wacky events to become the most popular animal on the farm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-school-games-europe-enfrdeesit', 'NDS', 'Crazy School Games (Europe) (En,Fr,De,Es,It)', '2008', 'Education / Mini-games', 'Creat Studios', '1', 'Casual School Games', 'Mini-game collection based on school pranks and fun.', 'Complete various school-themed challenges and games.', 'Humorous arcade fun in a school setting.', 'Crazy School Games is a collection of quick-fire challenges. From avoiding the teacher to lunchtime antics, these mini-games capture the lighter side of school life for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crime-lab---body-of-evidence-europe-enesitnl-ndsi-enhanced', 'NDS', 'Crime Lab - Body of Evidence (Europe) (En,Es,It,Nl) (NDSi Enhanced)', '2010', 'Adventure / Investigation', 'City Interactive', '1', 'Crime Investigation', 'Forensic investigation and hidden object.', 'Solve grisly murders using advanced forensic tools.', 'Gritty forensic detective simulation.', 'Crime Lab: Body of Evidence puts you in the shoes of an investigator. Use the NDSi camera and touch screen to analyze DNA, examine fingerprints, and piece together clues to catch dangerous killers in this enhanced thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crime-scene-europe-enfrdeesit', 'NDS', 'Crime Scene (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure / Puzzle', 'City Interactive', '1', 'Detective Puzzle', 'Point-and-click crime investigation.', 'Process crime scenes and solve complex murder cases.', 'Authentic crime scene investigation.', 'In Crime Scene, you play as Matt Simmons. Use realistic tools like luminol and swabs to gather evidence, interrogate suspects, and build a solid case to bring criminals to justice on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crime-scene-usa-enfres', 'NDS', 'Crime Scene (USA) (En,Fr,Es)', '2009', 'Adventure / Puzzle', 'City Interactive', '1', 'Detective Puzzle', 'Point-and-click crime investigation.', 'Process crime scenes and solve complex murder cases.', 'Authentic crime scene investigation.', 'In Crime Scene, you play as Matt Simmons. Use realistic tools like luminol and swabs to gather evidence, interrogate suspects, and build a solid case to bring criminals to justice on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crimson-room-japan', 'NDS', 'Crimson Room (Japan)', '2005', 'Puzzle / Escape', 'Takumi Soft', '1', 'Room Escape', 'Escape-the-room puzzle adventure.', 'Find clues and solve puzzles to escape a locked crimson room.', 'The original escape-room classic.', 'Crimson Room brings the viral web sensation to the NDS. Search every corner, collect items, and use your logic to find the way out of a mysterious locked room in this atmospheric puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('croket!-ds---tenkuu-no-yuusha-tachi-japan', 'NDS', 'Croket! DS - Tenkuu no Yuusha-tachi (Japan)', '2006', 'Action / RPG', 'Konami', '1', 'Anime RPG', 'Action-RPG with brawling elements.', 'Battle through the sky kingdom to save the world.', 'High-energy anime brawling RPG.', 'Based on the popular manga, Croket! DS features intense real-time combat. Customize your character''s abilities and join the heroes in a quest filled with humor and epic boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cross-treasures-japan', 'NDS', 'Cross Treasures (Japan)', '2008', 'Action / RPG', 'Success', '1', 'Fantasy Adventure', 'Dungeon-crawling RPG with customization.', 'Explore deep dungeons and customize your hero''s gear.', 'Classic Japanese dungeon adventure.', 'Cross Treasures, a collaboration with Shonen Jump, offers deep character customization. Team up with friends via local wireless to conquer dangerous labyrinths and collect rare loot in this vibrant RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crossword-de-manabou!-chiri---rekishi-japan', 'NDS', 'Crossword de Manabou! Chiri - Rekishi (Japan)', '2007', 'Education / Crossword', 'Success', '1', 'Educational Puzzle', 'Educational crossword puzzles.', 'Learn world geography and history through crosswords.', 'Fun educational trivia puzzles.', 'This Japanese title uses the crossword format to teach essential history and geography facts. It''s an engaging way for students or lifelong learners to sharpen their knowledge using the NDS stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crossword-ds-+-sekai-1-shuu-cross-japan', 'NDS', 'Crossword DS + Sekai 1-shuu Cross (Japan)', '2008', 'Education / Crossword', 'Success', '1', 'Crossword Collection', 'Word puzzle collection with a world tour theme.', 'Solve crosswords to "travel" around the world.', 'Global-themed crossword puzzle challenge.', 'Crossword DS + Sekai 1-shuu features hundreds of puzzles across various difficulty levels. Travel virtually to different countries by completing word grids, perfect for keeping your mind sharp on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crosswords---cruciverba-italiani-italy', 'NDS', 'Crosswords - Cruciverba Italiani (Italy)', '2009', 'Puzzle / Crossword', 'Leader S.p.A.', '1', 'Word Puzzle', 'Word-based puzzle games.', 'Complete crossword grids in the Italian language.', 'Classic Italian crosswords for NDS.', 'Cruciverba Italiani offers a huge library of puzzles for Italian speakers. Use the touch screen to write letters directly into the grid, featuring hints and various levels of challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crosswords-europe-enfrdeesit', 'NDS', 'CrossworDS (Europe) (En,Fr,De,Es,It)', '2006', 'Puzzle / Crossword', 'Magic Pockets', '1', 'Word Puzzle', 'Word-based puzzle and logic games.', 'Solve crosswords, word searches, and anagrams.', 'Massive portable word game collection.', 'CrossworDS features over 1,000 puzzles. Whether you enjoy traditional crosswords or fast-paced anagrams, this title provides endless linguistic entertainment with a simple, clean interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crosswords-usa', 'NDS', 'CrossworDS (USA)', '2006', 'Puzzle / Crossword', 'Magic Pockets', '1', 'Word Puzzle', 'Word-based puzzle and logic games.', 'Solve crosswords, word searches, and anagrams.', 'Massive portable word game collection.', 'CrossworDS features over 1,000 puzzles. Whether you enjoy traditional crosswords or fast-paced anagrams, this title provides endless linguistic entertainment with a simple, clean interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruciverba-per-ds-italy', 'NDS', 'Cruciverba per DS (Italy)', '2008', 'Puzzle / Crossword', 'Leader S.p.A.', '1', 'Word Puzzle', 'Word-based puzzle games.', 'Solve a variety of Italian crossword puzzles.', 'Essential Italian crossword library.', 'Cruciverba per DS is designed for casual play. It features a wide range of topics and difficulty settings, making it the ideal companion for fans of traditional word puzzles in Italian.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruise-line-tycoon-europe-enfrdeesitnl', 'NDS', 'Cruise Line Tycoon (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Simulation / Tycoon', 'Icon Games', '1', 'Business Management', 'Business management and tycoon simulation.', 'Build and manage a luxury cruise line empire.', 'Nautical business tycoon simulation.', 'Cruise Line Tycoon lets you design your ship, hire staff, and keep passengers happy. Balance your budget and expand your fleet to become the king of the high seas in this detailed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crystal-mines-europe-enfrdeesit', 'NDS', 'Crystal Mines (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle / Action', 'Magic Pockets', '1', 'Arcade Puzzle', 'Action-puzzler with mining and explosives.', 'Clear the mines of crystals while avoiding hazards.', 'Classic arcade-style mining puzzles.', 'Crystal Mines on NDS revives the classic 8-bit gameplay. Use explosives strategically to clear paths, collect rare crystals, and avoid traps in over 300 levels of addictive logic and action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('csi---crime-scene-investigation---dark-motives-europe-enfrdeesit', 'NDS', 'CSI - Crime Scene Investigation - Dark Motives (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure / Investigation', 'Telltale Games', '1', 'Crime Investigation', 'Forensic investigation and puzzle solving.', 'Solve five mysterious cases with the Las Vegas CSI team.', 'Intense forensic crime drama.', 'CSI: Dark Motives brings the hit TV show to NDS. Use high-tech tools to analyze ballistics and toxicology, interrogate suspects, and uncover the truth behind complex crimes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('csi---crime-scene-investigation---dark-motives-usa-enfrdeesit', 'NDS', 'CSI - Crime Scene Investigation - Dark Motives (USA) (En,Fr,De,Es,It)', '2008', 'Adventure / Investigation', 'Telltale Games', '1', 'Crime Investigation', 'Forensic investigation and puzzle solving.', 'Solve five mysterious cases with the Las Vegas CSI team.', 'Intense forensic crime drama.', 'CSI: Dark Motives brings the hit TV show to NDS. Use high-tech tools to analyze ballistics and toxicology, interrogate suspects, and uncover the truth behind complex crimes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('csi---crime-scene-investigation---deadly-intent---the-hidden-cases-europe-enfrdeesit', 'NDS', 'CSI - Crime Scene Investigation - Deadly Intent - The Hidden Cases (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure / Investigation', 'Telltale Games', '1', 'Crime Investigation', 'Forensic investigation and detective work.', 'Solve a series of hidden cases with the CSI: Vegas crew.', 'Authentic CSI investigative gameplay.', 'Deadly Intent features new characters and more complex puzzles. Work alongside the show''s cast to process crime scenes and link evidence using the NDS''s unique touch capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('csi---crime-scene-investigation---deadly-intent---the-hidden-cases-usa-enfres', 'NDS', 'CSI - Crime Scene Investigation - Deadly Intent - The Hidden Cases (USA) (En,Fr,Es)', '2009', 'Adventure / Investigation', 'Telltale Games', '1', 'Crime Investigation', 'Forensic investigation and detective work.', 'Solve a series of hidden cases with the CSI: Vegas crew.', 'Authentic CSI investigative gameplay.', 'Deadly Intent features new cases for the NDS. Analyze crime scenes with modern technology, perform autopsies, and follow the evidence to its final conclusion in this gripping adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('csi---crime-scene-investigation---unsolved!-europe-enfrdeesit-ndsi-enhanced', 'NDS', 'CSI - Crime Scene Investigation - Unsolved! (Europe) (En,Fr,De,Es,It) (NDSi Enhanced)', '2010', 'Adventure / Investigation', 'Telltale Games', '1', 'Crime Investigation', 'Forensic investigation and mini-games.', 'Solve unsolved cases using NDSi-specific features.', 'Enhanced forensic detective mystery.', 'CSI: Unsolved! utilizes the NDSi camera and microphone for a more immersive experience. Solve a variety of mini-games and investigations to close the most difficult "cold cases" in Vegas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cuisine-party-france', 'NDS', 'Cuisine Party (France)', '2009', 'Party / Cooking', 'Micro Application', '1–4', 'Casual Party', 'Mini-game collection and social simulation.', 'Participate in fun social activities and parties.', 'French casual social game.', 'Cuisine Party is a lighthearted collection of mini-games centered around social gatherings and fun tasks. Perfect for quick gameplay sessions and younger players looking for casual NDS fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('culdcept-ds-japan', 'NDS', 'Culdcept DS (Japan)', '2003', 'Strategy / Card', 'Omiya Soft', '1', 'Board Strategy', 'Strategy board game with card-battling elements.', 'Use cards to summon creatures and control territory.', 'Deep strategic card-battling classic.', 'Culdcept DS combines the strategy of Monopoly with the depth of a trading card game. Build your deck, manage your mana, and outmaneuver your rivals in this legendary Japanese strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('culture-generale-pour-les-nuls-la---2e-edition-europe-enfrde', 'NDS', 'Culture Generale pour les Nuls, La - 2e Edition (Europe) (En,Fr,De)', '2009', 'Education / Quiz', 'Micro Application', '1', 'General Knowledge', 'General knowledge trivia and quiz games.', 'Improve your trivia knowledge across multiple topics.', '"For Dummies" style general culture quiz.', 'Based on the famous book series, this second edition offers thousands of questions in French. Test your knowledge of history, science, and the arts in a fun, educational format on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('culture-generale-pour-les-nuls-la-france', 'NDS', 'Culture Generale pour les Nuls, La (France)', '2008', 'Education / Quiz', 'Micro Application', '1', 'General Knowledge', 'General knowledge trivia and quiz games.', 'Improve your trivia knowledge across multiple topics.', '"For Dummies" style general culture quiz.', 'The original "Culture Generale pour les Nuls" on NDS. Practice with hundreds of quizzes and track your progress as you become a trivia expert in various fields of general knowledge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('curling-ds-usa-enfr', 'NDS', 'Curling DS (USA) (En,Fr)', '2007', 'Sports / Simulation', 'Agetec', '1–4', 'Curling Simulation', 'Sports simulation focusing on curling.', 'Master the sport of curling and win the gold medal.', 'Realistic portable curling simulation.', 'Curling DS brings the unique Olympic sport to your handheld. Use the stylus to control the stone''s power and direction, and "sweep" the ice to lead your team to international victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-battler-bomber-man-japan', 'NDS', 'Custom Battler Bomber Man (Japan)', '2006', 'Action / Shooter', 'Hudson Soft', '1', 'Arcade Shooter', 'Action-maze game with character customization.', 'Customize your Bomberman and defeat enemies in mazes.', 'Deep customization and classic bombing.', 'Known as Bomberman Custom in some regions, this title allows you to equip your character with different parts to change stats and abilities while maintaining the classic explosive gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-beat-battle---draglade-japan', 'NDS', 'Custom Beat Battle - Draglade (Japan)', '2006', 'Action / Rhythm', 'Noise Factory', '1', 'Music Combat', 'Fighting game with musical rhythm elements.', 'Battle rivals using a mix of combat and rhythmic beats.', 'Innovative music-driven fighting game.', 'Draglade combines traditional 2D fighting with a rhythm system. Customize your "G-Code" to create unique musical attacks and defeat opponents in this high-energy NDS action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-beat-battle---draglade-2-japan', 'NDS', 'Custom Beat Battle - Draglade 2 (Japan)', '2007', 'Action / Rhythm', 'Noise Factory', '1', 'Music Combat', 'Fighting game with musical rhythm elements.', 'Battle rivals using a mix of combat and rhythmic beats.', 'Rhythmic combat sequel with more gear.', 'Draglade 2 expands on the original with more characters, refined rhythm mechanics, and deeper customization. Create your own beat-combos and rise to the top of the rhythmic fighting world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-mahjong-japan', 'NDS', 'Custom Mahjong (Japan)', '2007', 'Board / Mahjong', 'Success', '1', 'Mahjong Simulation', 'Traditional Mahjong with customization options.', 'Play Mahjong with customizable rules and aesthetics.', 'Personalized Japanese Mahjong experience.', 'Custom Mahjong lets you tailor the classic game to your liking. Change the tiles, backgrounds, and AI difficulty to create your perfect Mahjong session on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-robo-arena-europe-enfrdeesit', 'NDS', 'Custom Robo Arena (Europe) (En,Fr,De,Es,It)', '2006', 'Action / RPG', 'Noise Factory', '1', 'Sci-Fi Action', 'Real-time action-RPG with customizable robots.', 'Build your robot and battle in futuristic 3D arenas.', 'High-speed customizable robot combat.', 'Custom Robo Arena features thousands of part combinations. Build your "Robo," fight through a deep story mode, and compete in intense 3D battles that test your reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-robo-arena-usa', 'NDS', 'Custom Robo Arena (USA)', '2006', 'Action / RPG', 'Noise Factory', '1', 'Sci-Fi Action', 'Real-time action-RPG with customizable robots.', 'Build your robot and battle in futuristic 3D arenas.', 'High-speed customizable robot combat.', 'Custom Robo Arena features thousands of part combinations. Build your "Robo," fight through a deep story mode, and compete in intense 3D battles that test your reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dgray-man---innocence-no-shito-tachi-japan', 'NDS', 'D.Gray-Man - Innocence no Shito-tachi (Japan)', '2007', 'Action / RPG', 'Konami', '1', 'Anime Action RPG', 'Action-RPG with exploration and combat.', 'Fight Akuma and collect Innocence to save humanity.', 'Supernatural anime action adventure.', 'Based on the hit manga, D.Gray-man: Innocence no Shito-tachi features a 3D world where you control Allen Walker and his comrades. Use the touch screen to activate powerful Innocence abilities and defeat the Earl''s minions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('d&co---ta-maison-de-reve-en-7-jours-europe-frit', 'NDS', 'D&CO - Ta Maison de Reve en 7 Jours (Europe) (Fr,It)', '2009', 'Simulation / Design', 'Focus Home Interactive', '1', 'Home Design', 'Home renovation and interior design sim.', 'Redesign and renovate dream houses in seven virtual days.', 'Official French home makeover simulation.', 'Inspired by the popular French TV show, D&CO lets you become an interior designer. Use the stylus to paint, furniture-shop, and renovate rooms to satisfy demanding clients and create the ultimate dream home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daigassou!-band-brothers-japan', 'NDS', 'Daigassou! Band-Brothers (Japan)', '2004', 'Music / Rhythm', 'Nintendo', '1–8', 'Music Creation', 'Rhythm and music creation with various instruments.', 'Play along with the beat or compose your own musical tracks.', 'Innovative music creation and rhythm game.', 'Known in some regions as the predecessor to Jam with the Band, this title turns your NDS into a musical instrument. Play solo, join a local band with friends, or use the professional editor to compose your own songs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daigassou!-band-brothers-dx-japan', 'NDS', 'Daigassou! Band-Brothers DX (Japan)', '2008', 'Music / Rhythm', 'Nintendo', '1–8', 'Music Creation', 'Advanced rhythm game with singer/vocal features.', 'Perform hit songs and manage your virtual band.', 'The definitive NDS music and rhythm experience.', 'This DX version adds "Barbara the Bat" as your guide. It features a massive tracklist, enhanced sound quality, and the ability to download more songs, making it one of the most robust rhythm titles on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daigassou!-band-brothers-dx-japan-rev-1', 'NDS', 'Daigassou! Band-Brothers DX (Japan) (Rev 1)', '2008', 'Music / Rhythm', 'Nintendo', '1–8', 'Music Creation', 'Advanced rhythm game with singer/vocal features.', 'Perform hit songs and manage your virtual band.', 'The definitive NDS music and rhythm experience.', 'This DX version adds "Barbara the Bat" as your guide. It features a massive tracklist, enhanced sound quality, and the ability to download more songs, making it one of the most robust rhythm titles on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daikoukai-jidai-iv---rota-nova-japan', 'NDS', 'Daikoukai Jidai IV - Rota Nova (Japan)', '2006', 'Strategy / Simulation', 'Koei', '1', 'Historical Strategy', 'Strategic naval simulation and trading.', 'Explore the world, trade goods, and dominate the seas.', 'Classic maritime strategy and exploration.', 'Daikoukai Jidai IV (Uncharted Waters) brings deep naval management to NDS. Manage your crew, engage in ship combat, and build a trading empire across the globe in this historically-inspired simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daisenryaku-ds---great-strategy-japan', 'NDS', 'Daisenryaku DS - Great Strategy (Japan)', '2007', 'Strategy / War', 'Success', '1', 'Turn-Based Strategy', 'Turn-based military strategy and tactics.', 'Command an army to capture enemy bases and win wars.', 'Hardcore military strategy simulation.', 'Daisenryaku DS offers deep tactical gameplay. Manage fuel, ammunition, and diverse military units across grid-based maps to outmaneuver the AI in this sophisticated war simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daito-giken-koushiki-pachi-slot-simulator-hihouden---ossu!-banchou---yoshimune-ds-japan', 'NDS', 'Daito Giken Koushiki Pachi-Slot Simulator Hihouden - Ossu! Banchou - Yoshimune DS (Japan)', '2008', 'Simulation / Gambling', 'Daito Giken', '1', 'Pachislot Simulator', 'Pachi-slot (gambling) simulation.', 'Master three famous Daito Giken slot machines to win big.', 'Authentic Japanese pachi-slot simulation.', 'Experience the thrill of the parlor with high-fidelity recreations of "Hihouden," "Ossu! Banchou," and "Yoshimune." Practice your timing and manage your virtual bankroll on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-floor-europe-enfrdeesitnlpt', 'NDS', 'Dance Floor (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2009', 'Music / Dance', 'Mindscape', '1–4', 'Dance Rhythm', 'Rhythm-based dancing and club management.', 'Dance to the rhythm to become the star of the club.', 'High-energy club dancing rhythm game.', 'Dance Floor challenges your timing. Follow the arrows and beat to unlock new tracks and outfits, transforming your character from a beginner into the ultimate dance floor sensation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance!---its-your-stage-europe-ende-ndsi-enhanced', 'NDS', 'Dance! - It''s Your Stage (Europe) (En,De) (NDSi Enhanced)', '2010', 'Music / Dance', 'Mindscape', '1–4', 'Dance Performance', 'Rhythm-based dancing and stage performance.', 'Perform complex dance routines to win a talent competition.', 'Career-based professional dance simulator.', 'In Dance! It''s Your Stage, you follow a story of a rising star. Use the NDSi camera to personalize your experience and master professional choreography across multiple genres and stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dancing-on-ice-europe', 'NDS', 'Dancing on Ice (Europe)', '2010', 'Sports / Rhythm', '505 Games', '1', 'Figure Skating', 'Figure skating rhythm and sports simulation.', 'Master the ice with routines based on the reality show.', 'Official ice skating rhythm adventure.', 'Based on the popular TV show, Dancing on Ice lets you perform spins and jumps using the stylus. Train with professional partners and aim for a perfect score from the judges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dancing-with-the-stars---we-dance!-usa', 'NDS', 'Dancing with the Stars - We Dance! (USA)', '2010', 'Music / Dance', 'Activision', '1–4', 'TV Show Dance', 'Rhythm-based ballroom dancing competition.', 'Win the ballroom trophy through rhythm and coordination.', 'Official reality show ballroom dance game.', 'Step onto the dance floor with professional dancers. Match the rhythm and master different styles like the Waltz and Cha-cha in this official "Dancing with the Stars" handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daniel-x---the-ultimate-power-usa-enfrdeesit-ndsi-enhanced', 'NDS', 'Daniel X - The Ultimate Power (USA) (En,Fr,De,Es,It) (NDSi Enhanced)', '2010', 'Action / Adventure', 'Activision', '1', 'Sci-Fi Action', 'Action-adventure with elemental powers.', 'Use alien abilities to defeat a secret global conspiracy.', 'Sci-fi action based on James Patterson''s hero.', 'Daniel X: The Ultimate Power allows you to transform into various shapes and control the elements. Solve puzzles and fight intergalactic outlaws in this high-energy NDSi enhanced adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danny-phantom---urban-jungle-europe-enfrdees', 'NDS', 'Danny Phantom - Urban Jungle (Europe) (En,Fr,De,Es)', '2007', 'Action / Platform', 'Altron', '1', 'Cartoon Action', 'Side-scrolling shooter and action.', 'Save Amity Park from ghosts and the villain Undergrowth.', 'Ghost-hunting action based on the Nicktoon.', 'Control Danny Phantom in 2D flight levels and 3D boss battles. Use ghost powers to freeze or blast enemies as you navigate the "Urban Jungle" in this fast-paced action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danny-phantom---urban-jungle-usa', 'NDS', 'Danny Phantom - Urban Jungle (USA)', '2007', 'Action / Platform', 'Altron', '1', 'Cartoon Action', 'Side-scrolling shooter and action.', 'Save Amity Park from ghosts and the villain Undergrowth.', 'Ghost-hunting action based on the Nicktoon.', 'Control Danny Phantom in 2D flight levels and 3D boss battles. Use ghost powers to freeze or blast enemies as you navigate the "Urban Jungle" in this fast-paced action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danshaku-japan', 'NDS', 'Danshaku (Japan)', '2009', 'Adventure / Visual Novel', 'Arc System Works', '1', 'Japanese Adventure', '2D side-scrolling shooter (shmup).', 'Blast through enemy waves as a pilot in a surreal world.', 'Classic arcade-style bullet-hell shooter.', 'Danshaku (The Baron) offers intense shoot-em-up action. Dodge complex bullet patterns and utilize powerful weapon upgrades to survive through challenging levels and massive mechanical bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daredemo-asobi-taizen-japan', 'NDS', 'Daredemo Asobi Taizen (Japan)', '2008', 'Party / Mini-Games', 'Success', '1', 'Casual Party', 'Collection of classic board and card games.', 'Master 42 different games and defeat AI or human opponents.', 'The Japanese version of Clubhouse Games.', 'Daredemo Asobi Taizen is an essential suite of timeless favorites. From Mahjong and Shogi to Poker and Darts, it offers endless replayability with local and online multiplayer options.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daredemo-kantan!---jo-chihun-no-tsumego-japan', 'NDS', 'Daredemo Kantan! - Jo Chihun no Tsumego (Japan)', '2009', 'Board / Puzzle', 'Success', '1', 'Go Puzzle', 'Educational Go (Tsumego) puzzle trainer.', 'Solve complex Go problems under the guidance of a master.', 'Specialized Go strategy and puzzle trainer.', 'Master the ancient game of Go. Jo Chihun leads you through hundreds of Tsumego (life and death) puzzles designed to improve your tactical reading and overall game strength.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daredemo-kantan!---watanabe-akira-no-tsumeshougi-japan', 'NDS', 'Daredemo Kantan! - Watanabe Akira no Tsumeshougi (Japan)', '2009', 'Board / Puzzle', 'Success', '1', 'Shogi Puzzle', 'Educational Shogi (Tsume) puzzle trainer.', 'Solve Shogi checkmate problems to improve your endgame.', 'Specialized Shogi strategy and logic trainer.', 'Perfect for Shogi fans, this title features Tsumeshogi problems curated by pro Akira Watanabe. Learn winning patterns and sharpen your mind with hundreds of tactical puzzles on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daring-game-for-girls-the-usa', 'NDS', 'Daring Game for Girls, The (USA)', '2009', 'Adventure / Casual', 'Handheld Games', '1', 'Girls Adventure', 'Mini-game collection and adventure for young girls.', 'Complete various outdoor and social challenges for girls.', 'Empowering adventure and mini-game suite.', 'Based on the book series, The Daring Game for Girls features activities like camping, building a brand, and learning about historical women, all wrapped in a fun social adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-spire-the-usa', 'NDS', 'Dark Spire, The (USA)', '2008', 'RPG / Dungeon Crawler', 'SuperSweep', '1', 'Classic Dungeon RPG', 'First-person dungeon crawler (DRPG) with retro style.', 'Reach the top of a mysterious tower to find a lost mage.', 'Hardcore old-school dungeon crawling RPG.', 'The Dark Spire features a unique aesthetic inspired by classic pen-and-paper RPGs. Choose between modern or "classic" wireframe graphics as you battle through a brutal and rewarding labyrinth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('das-weiss-doch-jedes-kind!-germany', 'NDS', 'Das Weiss Doch Jedes Kind! (Germany)', '2007', 'Party / Quiz', 'Ravensburger', '1', 'Kids Quiz', 'Trivia and quiz based on the TV show.', 'Answer school-level questions to prove you''re smart.', 'German version of "Are You Smarter Than a 5th Grader?".', 'Test your basic knowledge across multiple subjects. Can you answer questions that every child should know? Compete in a simulated TV studio environment to win the top prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('date-ni-gametsui-wake-ja-nee!---dungeon-maker-girls-type-japan', 'NDS', 'Date ni Gametsui Wake ja Nee! - Dungeon Maker Girls Type (Japan)', '2008', 'RPG / Simulation', 'Global A Entertainment', '1', 'Dungeon Management', 'Dungeon management and social simulation.', 'Build a dungeon to attract monsters and woo the girls.', 'Unique dungeon-building and romance hybrid.', 'A spin-off of the Dungeon Maker series focused on female characters. Design your dungeon to lure specific monsters, gather materials, and interact with the town''s residents to build relationships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('datenshi-no-amai-yuuwaku-x-kaikan-phrase-japan', 'NDS', 'Datenshi no Amai Yuuwaku x Kaikan Phrase (Japan)', '2008', 'Adventure / Visual Novel', 'Furyu', '1', 'Romance Visual Novel', 'Visual novel and rhythm hybrid.', 'Navigate a romantic story through music and dialogue.', 'Romantic musical adventure based on the manga.', 'Join the band and experience the world of Sensual Phrase. Balance your romantic life with your musical career, featuring rhythm segments and multiple story paths for fans of the Shojo series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dawn-of-discovery-usa-enfrdeesit', 'NDS', 'Dawn of Discovery (USA) (En,Fr,De,Es,It)', '2009', 'Strategy / Simulation', 'Blue Byte', '1', 'City Building', 'Strategy and city-building simulation.', 'Build a successful colony in a new world through trade.', 'Deep colonial-era strategy and management.', 'Known as Anno 1404 in Europe, Dawn of Discovery offers complex resource management. Establish trade routes, satisfy your citizens'' needs, and explore the seas in this acclaimed handheld strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dawn-of-heroes-usa', 'NDS', 'Dawn of Heroes (USA)', '2008', 'Action / RPG', 'Wicked Studios', '1', 'Fantasy Action', 'Tactical turn-based RPG with 3D graphics.', 'Lead a party of heroes to defeat an ancient evil.', 'Epic tactical fantasy brawler for NDS.', 'Dawn of Heroes features a large cast of playable characters and deep customization. Engage in strategic grid-based combat and explore a vast fantasy world in this ambitious 3D RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('days-of-memories-japan', 'NDS', 'Days of Memories (Japan)', '2006', 'Adventure / Visual Novel', 'SNK Playmore', '1', 'Romance Adventure', 'Visual novel and dating simulation.', 'Build relationships with SNK characters during summer break.', 'SNK crossover dating simulation.', 'Interact with famous SNK personalities like Terry Bogard or Mai Shiranui in a school setting. Make the right choices to build bonds and unlock various romantic endings in this fan-favorite series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('days-of-memories-2-japan', 'NDS', 'Days of Memories 2 (Japan)', '2007', 'Adventure / Visual Novel', 'SNK Playmore', '1', 'Romance Adventure', 'Visual novel and dating simulation.', 'Build relationships with SNK characters during summer break.', 'SNK crossover dating simulation.', 'The second entry in the SNK dating series features even more characters and expanded scenarios. Balance your daily activities and social interactions to find your perfect match.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('days-of-memories-3-japan', 'NDS', 'Days of Memories 3 (Japan)', '2008', 'Adventure / Visual Novel', 'SNK Playmore', '1', 'Romance Adventure', 'Visual novel and dating simulation.', 'Build relationships with SNK characters during summer break.', 'SNK crossover dating simulation.', 'The third installment concludes the trilogy with refined graphics and a massive roster of SNK icons to meet and date. A must-play for fans of SNK lore and visual novels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('de-blob-2-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'de Blob 2 (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2011', 'Platform / Action', 'Blue Tongue', '1', 'Colorful Platformer', '3D action-platformer with painting mechanics.', 'Restore color to the city and defeat the INKT Corporation.', 'Vibrant and creative platforming adventure.', 'de Blob 2 brings the color-revolution to NDS. Use the stylus to paint buildings, solve puzzles, and liberate the citizens of Prisma City from a monochromatic tyranny.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('de-blob-2-usa', 'NDS', 'de Blob 2 (USA)', '2011', 'Platform / Action', 'Blue Tongue', '1', 'Colorful Platformer', '3D action-platformer with painting mechanics.', 'Restore color to the city and defeat the INKT Corporation.', 'Vibrant and creative platforming adventure.', 'de Blob 2 brings the color-revolution to NDS. Use the stylus to paint buildings, solve puzzles, and liberate the citizens of Prisma City from a monochromatic tyranny.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deadnfurious-europe-enfrdeesit', 'NDS', 'Dead''n''Furious (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Firebrand Games', '1', 'Arcade Racing', 'First-person rail shooter with zombies.', 'Survive the prison breakout and eliminate the undead.', 'Gritty arcade-style zombie rail shooter.', 'Known as "Touch the Dead" in the USA, Dead''n''Furious uses the NDS stylus as your weapon. Reload and blast your way through a zombie-infested prison in this intense, horror-themed arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal---der-banker-schlaegt-zurueck-germany', 'NDS', 'Deal or No Deal - Der Banker Schlaegt Zurueck (Germany)', '2007', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'Experience the tension of Deal or No Deal on your NDS. Answer the Banker''s phone calls, evaluate offers, and decide whether to play it safe or risk it all for the million-dollar briefcase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal---special-edition-usa-enfres', 'NDS', 'Deal or No Deal - Special Edition (USA) (En,Fr,Es)', '2008', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'The Special Edition of Deal or No Deal features updated graphics and new ways to play the hit TV show. Test your luck and your nerves against the Banker in this portable high-stakes simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal---the-banker-is-back!-europe', 'NDS', 'Deal or No Deal - The Banker Is Back! (Europe)', '2008', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'This European edition captures the specific atmosphere of the "Banker Is Back" TV format. Choose your box and manage the pressure as you try to outsmart the Banker in a series of tense rounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal---the-official-nintendo-ds-game-europe', 'NDS', 'Deal or No Deal - The Official Nintendo DS Game (Europe)', '2007', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'The official NDS version of the global phenomenon. Featuring the classic gameplay of choosing cases and eliminating prizes, it’s a perfect handheld recreation for fans of the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal-australia', 'NDS', 'Deal or No Deal (Australia)', '2006', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'The Australian version of the hit game show. Features localized currency and the same high-pressure decision-making that made the television program a worldwide success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal-germany', 'NDS', 'Deal or No Deal (Germany)', '2006', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'Play the German edition of the world-famous briefcase game. Will you take the Banker''s offer or push your luck to the very last case? Portable fun for fans of strategy and luck.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal-netherlands', 'NDS', 'Deal or No Deal (Netherlands)', '2006', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'Known as "Miljoenenjacht" in the Netherlands, this version brings the iconic Dutch game show format to the NDS, complete with the Banker''s enticing and risky offers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal-usa', 'NDS', 'Deal or No Deal (USA)', '2006', 'Game Show', 'Mindscape', '1', 'Quiz', 'Game show simulation with risk management.', 'Pick the right suitcase to win the grand prize.', 'Official TV game show simulation.', 'The American edition of Deal or No Deal. Navigate the 26 briefcases, listen to the Banker, and see if you have what it takes to win the virtual million-dollar prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dear-girl---stories---hibiki---hibiki-tokkun-daisakusen!-japan', 'NDS', 'Dear Girl - Stories - Hibiki - Hibiki Tokkun Daisakusen! (Japan)', '2009', 'Adventure', 'Bandai Namco', '1', 'Visual Novel', 'Visual novel and mini-game collection.', 'Help the protagonists train and complete various missions.', 'Fan-service adventure based on the radio show.', 'Based on the "Dear Girl: Stories" radio program, this title features Hiroshi Kamiya and Daisuke Ono. Engage in "Hibiki" training missions and enjoy a story-driven experience designed for the show''s fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-jr-and-the-science-fair-of-doom-europe-enfrdeesit', 'NDS', 'Death Jr. and the Science Fair of Doom (Europe) (En,Fr,De,Es,It)', '2006', 'Action Platformer', 'Atomic Planet', '1', 'Cartoon', '3D action-platformer with puzzles.', 'Stop the science fair chaos and rescue your friends.', 'Quirky supernatural platforming adventure.', 'Play as Death Jr., the son of Death, and his friend Pandora. Use your scythe and unique twin-screen puzzles to navigate a school invaded by supernatural forces in this stylish 3D platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-jr-and-the-science-fair-of-doom-usa', 'NDS', 'Death Jr. and the Science Fair of Doom (USA)', '2006', 'Action Platformer', 'Atomic Planet', '1', 'Cartoon', '3D action-platformer with puzzles.', 'Stop the science fair chaos and rescue your friends.', 'Quirky supernatural platforming adventure.', 'Play as Death Jr., the son of Death, and his friend Pandora. Use your scythe and unique twin-screen puzzles to navigate a school invaded by supernatural forces in this stylish 3D platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-note---kira-game-english-translation', 'NDS', 'Death Note - Kira Game (English translation)', '2007', 'Adventure', 'Konami', '1', 'Visual Novel', 'Strategic social deduction and logic.', 'Identify and eliminate Kira or defeat L in a battle of wits.', 'Intense psychological strategy game.', 'Based on the iconic anime, this game pits Kira against L. Use logic, influence, and hidden roles to deduce your opponent''s identity in a high-stakes board game style experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-note---kira-game-japan', 'NDS', 'Death Note - Kira Game (Japan)', '2007', 'Adventure', 'Konami', '1', 'Visual Novel', 'Strategic social deduction and logic.', 'Identify and eliminate Kira or defeat L in a battle of wits.', 'Intense psychological strategy game.', 'Based on the iconic anime, this game pits Kira against L. Use logic, influence, and hidden roles to deduce your opponent''s identity in a high-stakes board game style experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-note---l-o-tsugu-mono-japan', 'NDS', 'Death Note - L o Tsugu Mono (Japan)', '2008', 'Adventure', 'Konami', '1', 'Visual Novel', 'Strategic logic and investigation.', 'Solve the mystery of the Kira case as the successor to L.', 'Detective-style strategy and deduction.', 'The second Death Note title for NDS focuses on the investigation. Manage your resources, search for clues, and use L''s tactical genius to track down Kira in this deep psychological thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deca-sporta---ds-de-sports-10-shumoku!-japan', 'NDS', 'Deca Sporta - DS de Sports ''10'' Shumoku! (Japan)', '2008', 'Sports', 'Hudson Soft', '1', 'Sports Collection', 'Multi-sport mini-game collection.', 'Compete in 10 different sports to win the championship.', 'High-energy arcade sports compilation.', 'Deca Sports brings 10 events like Archery, Cheerleading, and Badminton to the NDS. Designed for quick pick-up-and-play action, it supports local multiplayer for competitive family fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deca-sports-ds-usa-enfres', 'NDS', 'Deca Sports DS (USA) (En,Fr,Es)', '2007', 'Sports', 'Hudson Soft', '1', 'Sports Collection', 'Multi-sport mini-game collection.', 'Compete in 10 different sports to win the championship.', 'High-energy arcade sports compilation.', 'Deca Sports brings 10 events like Archery, Cheerleading, and Badminton to the NDS. Designed for quick pick-up-and-play action, it supports local multiplayer for competitive family fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deco-tendances-france', 'NDS', 'Deco Tendances (France)', '2008', 'Lifestyle', 'Mindscape', '1', 'Casual', 'Home decor and interior design simulation.', 'Redesign rooms according to the latest French trends.', 'Chic interior design and lifestyle guide.', 'Deco Tendances allows you to act as a virtual decorator. Choose wallpapers, furniture, and layouts to transform drab rooms into stylish spaces following specific French design themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deep-aquarium---kiseki-no-shinkai-japan', 'NDS', 'Deep Aquarium - Kiseki no Shinkai (Japan)', '2006', 'Simulation', 'Arika', '1', 'Aquarium Simulation', 'Aquarium simulation and deep-sea exploration.', 'Collect and care for rare deep-sea marine life.', 'Relaxing deep-sea aquarium simulator.', 'Discover the mysteries of the ocean''s depths. Explore the "Kiseki no Shinkai" (Miracle Deep Sea), collect exotic fish species, and maintain your own virtual aquarium on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deep-labyrinth-europe', 'NDS', 'Deep Labyrinth (Europe)', '2007', 'RPG', 'Digital Bros', '1', 'Dungeon Crawler', 'First-person dungeon-crawling RPG.', 'Navigate a 3D labyrinth to recover your lost memories.', 'Atmospheric 3D fantasy RPG.', 'Originally a mobile game, Deep Labyrinth features real-time sword fighting and spellcasting via the touch screen. Explore a vast magical world with a story written by the creators of Chrono Trigger.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deep-labyrinth-japan', 'NDS', 'Deep Labyrinth (Japan)', '2007', 'RPG', 'Digital Bros', '1', 'Dungeon Crawler', 'First-person dungeon-crawling RPG.', 'Navigate a 3D labyrinth to recover your lost memories.', 'Atmospheric 3D fantasy RPG.', 'Originally a mobile game, Deep Labyrinth features real-time sword fighting and spellcasting via the touch screen. Explore a vast magical world with a story written by the creators of Chrono Trigger.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deep-labyrinth-usa', 'NDS', 'Deep Labyrinth (USA)', '2007', 'RPG', 'Digital Bros', '1', 'Dungeon Crawler', 'First-person dungeon-crawling RPG.', 'Navigate a 3D labyrinth to recover your lost memories.', 'Atmospheric 3D fantasy RPG.', 'Originally a mobile game, Deep Labyrinth features real-time sword fighting and spellcasting via the touch screen. Explore a vast magical world with a story written by the creators of Chrono Trigger.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deep-sea-aquarium-by-ds-europe-enfrit', 'NDS', 'Deep Sea Aquarium by DS (Europe) (En,Fr,It)', '2008', 'Simulation', '505 Games', '1', 'Aquarium Simulation', 'Aquarium simulation and deep-sea exploration.', 'Collect and care for rare deep-sea marine life.', 'Relaxing deep-sea aquarium simulator.', 'Discover the mysteries of the ocean''s depths. Explore the "Kiseki no Shinkai" (Miracle Deep Sea), collect exotic fish species, and maintain your own virtual aquarium on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defendin-depenguin-usa-enes', 'NDS', 'Defendin'' DePenguin (USA) (En,Es)', '2008', 'Action Platformer', 'Big Blue Bubble', '1', 'Arcade', 'Tower defense and action strategy.', 'Protect the penguin colony from hungry invaders.', 'Quirky Arctic tower defense action.', 'Help the penguins defend their home! Strategically place units and use the touch screen to repel waves of hungry polar bears and other predators in this colorful strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deine-reitschule-europe-frde', 'NDS', 'Deine Reitschule (Europe) (Fr,De)', '2007', 'Simulation', 'Tivola', '1', 'Educational', 'Equestrian simulation and riding school.', 'Learn the art of horse riding and stable management.', 'Educational horse care and riding sim.', 'Enroll in a virtual riding school. Groom your horses, learn various riding techniques, and compete in equestrian events to prove your skills as a professional rider on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dekiru-otoko-no-mote-life---hiru-no-mote-kouza-hen-japan', 'NDS', 'Dekiru Otoko no Mote Life - Hiru no Mote Kouza Hen (Japan)', '2008', 'Simulation', 'Konami', '1', 'Lifestyle', 'Social simulation and dating guide.', 'Learn how to be a "popular man" during daytime socializing.', 'Humorous dating and social etiquette trainer.', 'This "Daytime" edition focuses on workplace and social interaction. Use various mini-games and quizzes to learn the secrets of being a "Mote" (popular/attractive) man in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dekiru-otoko-no-mote-life---yoru-no-mote-jissen-hen-japan', 'NDS', 'Dekiru Otoko no Mote Life - Yoru no Mote Jissen Hen (Japan)', '2008', 'Simulation', 'Konami', '1', 'Lifestyle', 'Social simulation and dating guide.', 'Practice "popular man" skills for nightlife and dates.', 'Humorous dating and social etiquette trainer.', 'The "Nighttime" edition focuses on the art of conversation and dating. Learn how to impress on a night out through interactive scenarios and social simulations for the modern man.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dekita-yo!-mama---mitsugo-no-kuma-san---onnanoko-japan', 'NDS', 'Dekita yo! Mama. - Mitsugo no Kuma-san - Onnanoko (Japan)', '2007', 'Educational', 'Benesse', '1', 'Childcare', 'Educational mini-games for young children.', 'Complete basic learning tasks with a cute bear family.', 'Early childhood education for girls.', 'Designed for preschoolers, this title features the "Triple Bears." Use the stylus for coloring, counting, and basic logic puzzles in a bright, girl-themed educational environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dekita-yo!-mama---mitsugo-no-kuma-san---otokonoko-japan', 'NDS', 'Dekita yo! Mama. - Mitsugo no Kuma-san - Otokonoko (Japan)', '2007', 'Educational', 'Benesse', '1', 'Childcare', 'Educational mini-games for young children.', 'Complete basic learning tasks with a cute bear family.', 'Early childhood education for boys.', 'The "Otokonoko" (Boy) version of the Triple Bears series. Features the same educational mini-games but with themes and colors tailored specifically for young boys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dekita-yo!-mama---wannyan-club---onnanoko-japan', 'NDS', 'Dekita yo! Mama. - Wannyan Club - Onnanoko (Japan)', '2008', 'Educational', 'Benesse', '1', 'Pet Care', 'Educational mini-games and pet care for kids.', 'Learn daily tasks and animal care with cute puppies.', 'Child-friendly pet care and education.', 'Part of the "Dekita yo! Mama" (I did it, Mama!) series. This girl-themed version teaches young children about responsibility and basic logic through puppy and kitten interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dekita-yo!-mama---wannyan-club---otokonoko-japan', 'NDS', 'Dekita yo! Mama. - Wannyan Club - Otokonoko (Japan)', '2008', 'Educational', 'Benesse', '1', 'Pet Care', 'Educational mini-games and pet care for kids.', 'Learn daily tasks and animal care with cute puppies.', 'Child-friendly pet care and education.', 'The boy-themed version of the Wannyan (Woof-Meow) Club. Provides engaging, simple educational activities for toddlers focused on pet care and early learning development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deltora-quest---nanatsu-no-houseki-japan', 'NDS', 'Deltora Quest - Nanatsu no Houseki (Japan)', '2008', 'Action RPG', 'Level-5', '1', 'Fantasy Adventure', 'Action-RPG with exploration and combat.', 'Collect the seven lost gems of the Belt of Deltora.', 'Fantasy quest based on the popular novels.', 'Based on the anime and book series, Deltora Quest: Nanatsu no Houseki lets you control Lief, Barda, and Jasmine. Use the NDS touch screen to unleash powerful attacks and solve puzzles in a lush fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dementium---the-ward-europe-enfrdeesit', 'NDS', 'Dementium - The Ward (Europe) (En,Fr,De,Es,It)', '2007', 'Survival Horror', 'Renegade Kid', '1', 'First-Person Horror', 'First-person survival horror.', 'Escape a nightmare-filled hospital and uncover the truth.', 'Intense 3D horror with a dark atmosphere.', 'Dementium: The Ward pushes the NDS hardware with a smooth 60fps 3D engine. Use your flashlight and a variety of weapons to survive terrifying creatures in this gritty, mature horror experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dementium---the-ward-usa', 'NDS', 'Dementium - The Ward (USA)', '2007', 'Survival Horror', 'Renegade Kid', '1', 'First-Person Horror', 'First-person survival horror.', 'Escape a nightmare-filled hospital and uncover the truth.', 'Intense 3D horror with a dark atmosphere.', 'Dementium: The Ward pushes the NDS hardware with a smooth 60fps 3D engine. Use your flashlight and a variety of weapons to survive terrifying creatures in this gritty, mature horror experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dementium-ii-europe-enfrdeesit', 'NDS', 'Dementium II (Europe) (En,Fr,De,Es,It)', '2010', 'Survival Horror', 'Renegade Kid', '1', 'First-Person Horror', 'First-person survival horror with combat and puzzles.', 'Survive the Bright Dawn Treatment Center and defeat the Doctor.', 'A terrifying sequel to the cult classic horror.', 'Dementium II improves on its predecessor with a map system, more weapon variety, and even more disturbing enemies. Experience one of the most technically impressive and scary games on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dementium-ii-usa-enfrdeesit', 'NDS', 'Dementium II (USA) (En,Fr,De,Es,It)', '2010', 'Survival Horror', 'Renegade Kid', '1', 'First-Person Horror', 'First-person survival horror with combat and puzzles.', 'Survive the Bright Dawn Treatment Center and defeat the Doctor.', 'A terrifying sequel to the cult classic horror.', 'Dementium II improves on its predecessor with a map system, more weapon variety, and even more disturbing enemies. Experience one of the most technically impressive and scary games on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dengeki-gakuen-rpg---cross-of-venus-japan', 'NDS', 'Dengeki Gakuen RPG - Cross of Venus (Japan)', '2009', 'RPG', 'Ascii Media Works', '1', 'Anime RPG', 'Action-RPG crossover with anime characters.', 'Fight alongside Dengeki Bunko heroes to save reality.', 'Epic anime crossover action RPG.', 'Dengeki Gakuen RPG: Cross of Venus features characters from Shakugan no Shana, Toaru Majutsu no Index, and more. Battle through 2D side-scrolling combat and explore 3D worlds in this fan-favorite crossover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dengeki-gakuen-rpg---cross-of-venus-special-japan', 'NDS', 'Dengeki Gakuen RPG - Cross of Venus Special (Japan)', '2010', 'RPG', 'Ascii Media Works', '1', 'Anime RPG', 'Action-RPG crossover with anime characters.', 'Fight alongside Dengeki Bunko heroes to save reality.', 'Enhanced anime crossover RPG.', 'The Special version of Cross of Venus adds new scenarios, improved character balances, and additional voice acting, providing the definitive experience for fans of the Dengeki Bunko light novel universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('denjirou-sensei-no-fushigi-na-jikkenshitsu-japan', 'NDS', 'Denjirou Sensei no Fushigi na Jikkenshitsu (Japan)', '2007', 'Educational', 'Gakken', '1', 'Science Experiments', 'Science simulation and educational mini-games.', 'Perform virtual science experiments with Denjirou Sensei.', 'Fun and interactive science lab simulator.', 'Learn the wonders of physics and chemistry! Denjirou Sensei no Fushigi na Jikkenshitsu uses the NDS microphone and touch screen to let you conduct safe, explosive, and educational science experiments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('denksport-varia-netherlands', 'NDS', 'Denksport Varia (Netherlands)', '2008', 'Puzzle', 'Mindscape', '1', 'Brain Training', 'Logic puzzle and word game collection.', 'Solve various brain teasers and linguistic puzzles.', 'Diverse Dutch puzzle compilation.', 'Denksport Varia offers a wide array of puzzles including Sudoku, Crosswords, and logic grids. Designed for Dutch speakers, it’s the perfect title for mental stimulation and casual puzzle solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-stafy---taiketsu!-dile-kaizoku-dan-japan', 'NDS', 'Densetsu no Stafy - Taiketsu! Dile Kaizoku Dan (Japan)', '2008', 'Platformer', 'Tose', '1', 'Anime Platformer', '2D side-scrolling platformer.', 'Help Stafy defeat the space pirates and protect the ocean.', 'Charming and fluid underwater platforming.', 'Densetsu no Stafy (The Legendary Starfy) makes its DS debut. Utilize Stafy’s signature spin attack and team up with his sister Stapy in this colorful, high-speed aquatic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-stafy-4-japan', 'NDS', 'Densetsu no Stafy 4 (Japan)', '2006', 'Platformer', 'Tose', '1', 'Anime Platformer', '2D side-scrolling platformer.', 'Guide the star-prince Stafy through magical worlds.', 'Vibrant 2D platforming excellence.', 'The fourth entry in the beloved series features beautiful sprite work and creative level design. Solve puzzles, find hidden treasures, and enjoy the heartwarming story of the legendary star-shaped hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-ds-japan', 'NDS', 'Derby Stallion DS (Japan)', '2008', 'Simulation', 'ParityBit', '1', 'Horse Racing Management', 'Horse racing and breeding simulation.', 'Manage a stable and breed a championship winning horse.', 'Deep equestrian management strategy.', 'Derby Stallion DS brings the hit Japanese simulation to the handheld. Manage every aspect of your horse''s training, diet, and racing schedule to dominate the prestigious G1 racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desktop-tower-defense-usa', 'NDS', 'Desktop Tower Defense (USA)', '2009', 'Tower Defense', 'HandCircus', '1', 'Strategy Arcade', 'Strategic tower defense.', 'Protect your base by building and upgrading turrets.', 'Addictive grid-based strategy classic.', 'Based on the popular web game, Desktop Tower Defense for NDS features multiple game modes and challenges. Strategically place your towers to create mazes and stop waves of "creeps" from crossing the screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('despicable-me---minion-mayhem-europe-enfrdeesitsvnodafi', 'NDS', 'Despicable Me - Minion Mayhem (Europe) (En,Fr,De,Es,It,Sv,No,Da,Fi)', '2010', 'Action Platformer', 'Gameloft', '1', 'Movie Licensed', 'Puzzle-platformer with Minion management.', 'Guide the Minions through Gru''s lab using various gadgets.', 'Wacky puzzle fun with the Minions.', 'In Minion Mayhem, you must lead Gru''s yellow henchmen to safety. Use the touch screen to place bridges, operate machinery, and solve complex environmental puzzles in this charming movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('despicable-me---the-game---minion-mayhem-usa-enfrdeesit', 'NDS', 'Despicable Me - The Game - Minion Mayhem (USA) (En,Fr,De,Es,It)', '2010', 'Action Platformer', 'Gameloft', '1', 'Movie Licensed', 'Puzzle-platformer with Minion management.', 'Guide the Minions through Gru''s lab using various gadgets.', 'Wacky puzzle fun with the Minions.', 'In Minion Mayhem, you must lead Gru''s yellow henchmen to safety. Use the touch screen to place bridges, operate machinery, and solve complex environmental puzzles in this charming movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destiny-links-japan', 'NDS', 'Destiny Links (Japan)', '2009', 'RPG', 'Hudson Soft', '1', 'Fantasy RPG', 'Action-RPG with team-based combat.', 'Build bonds with allies to explore islands and defeat monsters.', 'Nautical themed action RPG adventure.', 'Destiny Links features real-time combat and a unique "link" system that rewards teamwork. Explore a beautiful 2D world, complete quests for villagers, and uncover the mystery of the legendary white whale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deutgo-sseugo-chinhaejineun---ds-yeongeo-sammaegyeong-korea', 'NDS', 'Deutgo Sseugo Chinhaejineun - DS Yeongeo Sammaegyeong (Korea)', '2008', 'Educational', 'Dalnim', '1', 'Language Learning', 'Educational English language trainer.', 'Improve English listening and writing through dictation.', 'Specialized English learning tool for Koreans.', 'This educational title focuses on "Listening and Writing" (Yeongeo Sammaegyeong). Use the stylus to practice English spelling and the microphone to perfect your pronunciation in a structured learning environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deutsch-1-4-klasse---fit-fuers-gymnasium-germany', 'NDS', 'Deutsch 1.-4. Klasse - Fit fuers Gymnasium (Germany)', '2007', 'Educational', 'Independent Arts', '1', 'School Learning', 'Educational primary school trainer.', 'Master German, Math, and English subjects for school.', 'Comprehensive German school curriculum trainer.', 'Fit fuers Gymnasium is designed for students in grades 1-4. It offers interactive lessons and exercises aligned with the German educational system to help children prepare for secondary school entrance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deviens-miss-france-france', 'NDS', 'Deviens Miss France (France)', '2006', 'Simulation', 'Mindscape', '1', 'Lifestyle', 'Fashion and social simulation.', 'Compete in various challenges to win the Miss France title.', 'Official pageant and beauty simulation.', 'Experience the life of a pageant contestant! Manage your schedule, choose the perfect outfits, and master various mini-games to impress the judges and become the next Miss France on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devil-survivor-2-japan', 'NDS', 'Devil Survivor 2 (Japan)', '2011', 'Tactical RPG', 'Atlus', '1', 'Anime Strategy', 'Tactical turn-based RPG with demon summoning.', 'Survive a 7-day demon invasion in modern-day Tokyo.', 'Gripping supernatural strategy RPG.', 'Part of the Shin Megami Tensei universe, Devil Survivor 2 combines deep tactical combat with a branching narrative. Your choices determine who lives and who dies in a world on the brink of apocalypse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devilish---ball-bounder-japan', 'NDS', 'Devilish - Ball Bounder (Japan)', '2007', 'Action Puzzle', 'Starfish', '1', 'Arcade', 'Fast-paced "Breakout" style action.', 'Use two paddles to destroy blocks and enemies in gothic levels.', 'Modern revival of the classic Devilish.', 'Known in the West as Devilish: Ball Bounder, this game features intense arcade action. Navigate vertical levels filled with bosses and hazards using the dual paddles to control the ball''s trajectory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devilish-europe', 'NDS', 'Devilish (Europe)', '1995', 'Action Puzzle', 'Starfish', '1', 'Classic Arcade', 'Fast-paced "Breakout" style action.', 'Use two paddles to destroy blocks and enemies in gothic levels.', 'Modern revival of the classic Devilish.', 'Known in the West as Devilish: Ball Bounder, this game features intense arcade action. Navigate vertical levels filled with bosses and hazards using the dual paddles to control the ball''s trajectory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('di-gata-defenders-europe-enfrdeesit', 'NDS', 'Di-Gata Defenders (Europe) (En,Fr,De,Es,It)', '2006', 'Action', '7 Studios', '1', 'Cartoon Action', 'Tactical action with stone-based combat.', 'Battle as the Di-Gata Defenders to protect the realm of RaDos.', 'Strategic brawler based on the animated series.', 'Control Seth, Mel, Erik, and Kara in this strategic action game. Use powerful "stones" to cast spells and summon creatures, following the plot of the popular fantasy show on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('di-gata-defenders-usa-enfres', 'NDS', 'Di-Gata Defenders (USA) (En,Fr,Es)', '2006', 'Action', '7 Studios', '1', 'Cartoon Action', 'Tactical action with stone-based combat.', 'Battle as the Di-Gata Defenders to protect the realm of RaDos.', 'Strategic brawler based on the animated series.', 'Control Seth, Mel, Erik, and Kara in this strategic action game. Use powerful "stones" to cast spells and summon creatures, following the plot of the popular fantasy show on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diabolik---the-original-sin-europe-enfrdeesitnl', 'NDS', 'Diabolik - The Original Sin (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Adventure', 'Artematica', '1', 'Comic Noir', 'Point-and-click adventure and stealth.', 'Help the master thief Diabolik recover a mysterious artifact.', 'Noir-style interactive comic book adventure.', 'Step into the shadows as Diabolik. Solve environmental puzzles, use high-tech gadgets, and enjoy a cinematic story filled with intrigue, romance, and stealth in this beautifully illustrated adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diary-girl-usa', 'NDS', 'Diary Girl (USA)', '2007', 'Simulation', 'TEC', '1', 'Casual Life', 'Social simulation and personal organizer.', 'Manage your virtual life, diary, and fashion style.', 'Personal assistant and social sim for girls.', 'Diary Girl is more than a game; it''s a digital organizer. Keep track of your real-life appointments, play fashion mini-games, and interact with virtual friends in a pink and stylish interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diddl-puzzle---echter-puzzlespass-fuer-unterwegs-europe-enfrdeesit', 'NDS', 'Diddl Puzzle - Echter Puzzlespass fuer Unterwegs (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Ravensburger', '1', 'Casual Puzzle', 'Jigsaw puzzle collection.', 'Complete various digital puzzles featuring Diddl the mouse.', 'Relaxing puzzle fun with a classic character.', 'Diddl Puzzle features dozens of adorable illustrations of the famous German cartoon mouse. Choose your difficulty level and use the stylus to piece together high-quality digital jigsaw puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diddy-kong-racing-ds-europe-enfrdeesit', 'NDS', 'Diddy Kong Racing DS (Europe) (En,Fr,De,Es,It)', '2007', 'Racing', 'Nintendo', '1', 'Arcade Racing', 'Kart racing and adventure mode.', 'Defeat the space pig Wizpig in high-speed races.', 'Classic Rare racer with land, air, and water vehicles.', 'Diddy Kong Racing DS is an enhanced remake of the N64 classic. Choose between cars, hovercrafts, and planes, use the touch screen for boosts, and enjoy an extensive single-player adventure mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diddy-kong-racing-ds-usa', 'NDS', 'Diddy Kong Racing DS (USA)', '2007', 'Racing', 'Nintendo', '1', 'Arcade Racing', 'Kart racing and adventure mode.', 'Defeat the space pig Wizpig in high-speed races.', 'Classic Rare racer with land, air, and water vehicles.', 'Diddy Kong Racing DS is an enhanced remake of the N64 classic. Choose between cars, hovercrafts, and planes, use the touch screen for boosts, and enjoy an extensive single-player adventure mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diegos-build-and-rescue-europe-enfrnl', 'NDS', 'Diego''s Build and Rescue (Europe) (En,Fr,Nl)', '2007', 'Educational', 'Climax', '1', 'Kids Adventure', 'Educational adventure and construction.', 'Help Diego build vehicles and rescue animals in need.', 'Rescue-themed learning for young children.', 'Join Go, Diego, Go! in this interactive adventure. Use the NDS stylus to "build" specialized rescue vehicles and solve simple environmental puzzles to help animals in the rainforest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diegos-build-and-rescue-usa', 'NDS', 'Diego''s Build and Rescue (USA)', '2007', 'Educational', 'Climax', '1', 'Kids Adventure', 'Educational adventure and construction.', 'Help Diego build vehicles and rescue animals in need.', 'Rescue-themed learning for young children.', 'Join Go, Diego, Go! in this interactive adventure. Use the NDS stylus to "build" specialized rescue vehicles and solve simple environmental puzzles to help animals in the rainforest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diercke---das-geographie-quiz-germany', 'NDS', 'Diercke - Das Geographie-Quiz (Germany)', '2007', 'Educational', 'Westermann', '1', 'Geography Quiz', 'Educational geography trivia.', 'Test your knowledge of world geography and maps.', 'Geography-themed quiz game for students.', 'Based on the famous German Diercke atlas, this quiz game challenges players with questions about topography, climate, and culture. It’s an interactive way for students and trivia fans to master world geography on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dig-dug---digging-strike-europe', 'NDS', 'Dig Dug - Digging Strike (Europe)', '2007', 'Action', 'Namco', '1', 'Arcade Action', 'Arcade action and puzzle hybrid.', 'Dig tunnels and defeat underground monsters in 3D/2D.', 'Classic Dig Dug gameplay with a dual-screen twist.', 'Digging Strike combines elements from the original Dig Dug and Dig Dug II. Use the bottom screen for underground action and the top screen for surface strategy, creating an innovative and nostalgic arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dig-dug---digging-strike-japan', 'NDS', 'Dig Dug - Digging Strike (Japan)', '2007', 'Action', 'Namco', '1', 'Arcade Action', 'Arcade action and puzzle hybrid.', 'Dig tunnels and defeat underground monsters in 3D/2D.', 'Classic Dig Dug gameplay with a dual-screen twist.', 'Digging Strike combines elements from the original Dig Dug and Dig Dug II. Use the bottom screen for underground action and the top screen for surface strategy, creating an innovative and nostalgic arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dig-dug---digging-strike-usa', 'NDS', 'Dig Dug - Digging Strike (USA)', '2007', 'Action', 'Namco', '1', 'Arcade Action', 'Arcade action and puzzle hybrid.', 'Dig tunnels and defeat underground monsters in 3D/2D.', 'Classic Dig Dug gameplay with a dual-screen twist.', 'Digging Strike combines elements from the original Dig Dug and Dig Dug II. Use the bottom screen for underground action and the top screen for surface strategy, creating an innovative and nostalgic arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-championship-japan', 'NDS', 'Digimon Championship (Japan)', '2008', 'Simulation', 'Bandai Namco', '1', 'Monster Training', 'Management and monster battling simulation.', 'Train Digimon and win the Championship tournament.', 'Strategic Digimon training and combat sim.', 'Digimon Championship focuses on the "tamer" experience. Capture wild Digimon, manage their diet and training schedules in a simulation environment, and pit them against rivals in automated tournament battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-championship-korea', 'NDS', 'Digimon Championship (Korea)', '2008', 'Simulation', 'Bandai Namco', '1', 'Monster Training', 'Management and monster battling simulation.', 'Train Digimon and win the Championship tournament.', 'Strategic Digimon training and combat sim.', 'Digimon Championship focuses on the "tamer" experience. Capture wild Digimon, manage their diet and training schedules in a simulation environment, and pit them against rivals in automated tournament battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-story---lost-evolution-japan', 'NDS', 'Digimon Story - Lost Evolution (Japan)', '2010', 'RPG', 'Bandai Namco', '1', 'Monster RPG', 'Turn-based JRPG and monster collection.', 'Restore the lost evolution chains of the Digimon world.', 'Epic Digimon adventure with deep evolution trees.', 'As the third entry in the Story series, Lost Evolution introduces a "Repair" system for Digimon plates. Explore deep digital worlds and solve the mystery behind the disappearing evolutions in this massive Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-story---moonlight-japan', 'NDS', 'Digimon Story - Moonlight (Japan)', '2009', 'RPG', 'Bandai Namco', '1', 'Monster RPG', 'Turn-based JRPG and monster collection.', 'Join the Night Crow team and defeat the virus threat.', 'Darker-themed Digimon JRPG experience.', 'Known as Digimon World: Dusk in the West, Moonlight follows the story of the Night Crow tamer group. Collect over 400 Digimon and engage in strategic 3v3 turn-based battles in a futuristic digital setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-story---sunburst-japan', 'NDS', 'Digimon Story - Sunburst (Japan)', '2009', 'RPG', 'Bandai Namco', '1', 'Monster RPG', 'Turn-based JRPG and monster collection.', 'Join the Light Fang team and protect the Sunshine City.', 'Bright and classic Digimon JRPG adventure.', 'Known as Digimon World: Dawn in the West, Sunburst features exclusive Digimon and locations. Experience a deep story about friendship and digital evolution as you battle to become the ultimate tamer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-story-japan', 'NDS', 'Digimon Story (Japan)', '2006', 'RPG', 'Bandai Namco', '1', 'Monster RPG', 'Turn-based JRPG and monster collection.', 'Explore the Digital World and become a Legendary Tamer.', 'The first Digimon Story title for NDS.', 'Digimon Story (Digimon World DS) lets you raise, evolve, and battle with your favorite Digimon. Build "Digi-Farms" to train your monsters while you are away and explore a vast, story-driven digital landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-story-japan-rev-1', 'NDS', 'Digimon Story (Japan) (Rev 1)', '2006', 'RPG', 'Bandai Namco', '1', 'Monster RPG', 'Turn-based JRPG and monster collection.', 'Explore the Digital World and become a Legendary Tamer.', 'The first Digimon Story title for NDS.', 'Digimon Story (Digimon World DS) lets you raise, evolve, and battle with your favorite Digimon. Build "Digi-Farms" to train your monsters while you are away and explore a vast, story-driven digital landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-world---dawn-usa', 'NDS', 'Digimon World - Dawn (USA)', '2007', 'RPG', 'Bandai Namco', '1', 'Monster RPG', 'Turn-based JRPG and monster collection.', 'Lead the Light Fang team to restore order in the digital world.', 'Comprehensive monster-catching JRPG.', 'Digimon World: Dawn features a huge roster of creatures to collect and evolve. Manage your farm, complete quests for the tamer union, and use local wireless to trade or battle with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-world---dusk-usa', 'NDS', 'Digimon World - Dusk (USA)', '2007', 'RPG', 'Bandai Namco', '1', 'Monster RPG', 'Turn-based JRPG and monster collection.', 'Lead the Night Crow team and uncover the digital conspiracy.', 'Strategic RPG with dark-element Digimon.', 'Digimon World: Dusk offers a unique perspective on the Sunburst/Moonlight story. With distinct Digimon and a plot focused on a mysterious virus, it’s an essential title for fans of deep monster-taming RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-world-championship-usa', 'NDS', 'Digimon World Championship (USA)', '2008', 'Simulation', 'Bandai Namco', '1', 'Monster Management', 'Management and monster battling simulation.', 'Train Digimon and win the Championship tournament.', 'Strategic Digimon training and combat sim.', 'Digimon World Championship focuses on the "tamer" experience. Capture wild Digimon, manage their diet and training schedules in a simulation environment, and pit them against rivals in automated tournament battles.');
