INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diner-dash---flo-on-the-go-usa-enfr', 'NDS', 'Diner Dash - Flo on the Go (USA) (En,Fr)', '2007', 'Time Management', 'PlayFirst', '1', 'Casual Management', 'Time management and strategy.', 'Help Flo manage customers and serve food on a vacation cruise.', 'Fast-paced service simulation on the go.', 'Diner Dash: Flo on the Go takes the hit PC game to the NDS. Manage seating, orders, and clean-up in various tropical locations. Use the stylus to keep your customers happy and maximize your tips.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diner-dash---sizzle-&-serve-usa-enfrdeesit', 'NDS', 'Diner Dash - Sizzle & Serve (USA) (En,Fr,De,Es,It)', '2009', 'Time Management', 'PlayFirst', '1', 'Casual Management', 'Time management and strategy.', 'Serve customers and manage a variety of busy restaurants.', 'Ultimate restaurant service challenge.', 'Sizzle & Serve brings the classic Diner Dash experience to your handheld. Master the rhythm of the kitchen and the dining room across dozens of levels, unlocking new restaurants and upgrades for Flo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diner-dash-europe-enfrdeesit', 'NDS', 'Diner Dash (Europe) (En,Fr,De,Es,It)', '2007', 'Time Management', 'PlayFirst', '1', 'Casual Management', 'Time management and strategy.', 'Serve customers and manage a variety of busy restaurants.', 'Ultimate restaurant service challenge.', 'Sizzle & Serve brings the classic Diner Dash experience to your handheld. Master the rhythm of the kitchen and the dining room across dozens of levels, unlocking new restaurants and upgrades for Flo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-king-battle---taiko-kara-no-hyouryuusha-japan', 'NDS', 'Dino King Battle - Taiko kara no Hyouryuusha (Japan)', '2007', 'Action Adventure', 'Climax', '1', 'Anime Adventure', 'Strategy and creature battling.', 'Use cards and dinosaurs to win tactical matches.', 'Epic prehistoric dinosaur brawling.', 'Based on the arcade hit, Dino King Battle lets you summon powerful dinosaurs to fight. Customize your deck of move cards and master the rock-paper-scissors combat system to become the Dino King.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-master---dig-discover-duel-europe-enfrdeesit', 'NDS', 'Dino Master - Dig, Discover, Duel (Europe) (En,Fr,De,Es,It)', '2008', 'Action Adventure', 'Studio Archcraft', '1', 'Dinosaur Adventure', 'Arcade strategy and fossil excavation.', 'Dig up dinosaur fossils and use them in battle arenas.', 'Fossil-hunting and dinosaur combat hybrid.', 'Dino Master mixes exploration with action. Use the stylus to carefully excavate fossils while avoiding enemies, then revive your discoveries to battle against rival masters in prehistoric combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-master---dig-discover-duel-usa', 'NDS', 'Dino Master - Dig, Discover, Duel (USA)', '2008', 'Action Adventure', 'Studio Archcraft', '1', 'Dinosaur Adventure', 'Arcade strategy and fossil excavation.', 'Dig up dinosaur fossils and use them in battle arenas.', 'Fossil-hunting and dinosaur combat hybrid.', 'Dino Master mixes exploration with action. Use the stylus to carefully excavate fossils while avoiding enemies, then revive your discoveries to battle against rival masters in prehistoric combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-pets---the-virtual-pet-game-usa', 'NDS', 'Dino Pets - The Virtual Pet Game (USA)', '2008', 'Simulation', 'Powerhead Games', '1', 'Virtual Pet', 'Virtual pet simulation.', 'Hatch, care for, and play with adorable prehistoric pets.', 'Cute dinosaur-themed pet simulation.', 'Dino Pets lets you raise your very own baby dinosaurs. Feed them, groom them, and play mini-games to keep them happy. A charming and accessible pet sim for younger NDS players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinosaur-king-europe-enfrdeesit', 'NDS', 'Dinosaur King (Europe) (En,Fr,De,Es,It)', '2007', 'Action Adventure', 'Climax', '1', 'Anime Adventure', 'Tactical RPG with dinosaur combat.', 'Travel through time to stop the Alpha Gang from capturing dinosaurs.', 'SEGA''s hit prehistoric battle adventure.', 'Based on the popular anime, Dinosaur King features a deep turn-based combat system. Collect over 70 dinosaurs, upgrade their skills, and engage in epic 3D battles across various eras of history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinosaur-king-usa', 'NDS', 'Dinosaur King (USA)', '2007', 'Action Adventure', 'Climax', '1', 'Anime Adventure', 'Tactical RPG with dinosaur combat.', 'Travel through time to stop the Alpha Gang from capturing dinosaurs.', 'SEGA''s hit prehistoric battle adventure.', 'Based on the popular anime, Dinosaur King features a deep turn-based combat system. Collect over 70 dinosaurs, upgrade their skills, and engage in epic 3D battles across various eras of history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dirt-2-usa-enfres', 'NDS', 'Dirt 2 (USA) (En,Fr,Es)', '2009', 'Racing', 'Codemasters', '1', 'Realistic Racing', 'High-speed rally and off-road racing.', 'Win races across diverse global environments.', 'Intense and realistic portable rally racing.', 'DiRT 2 on NDS offers impressive 3D graphics and tight controls. Compete in world-class rally events, customize your vehicles, and master the art of off-road racing on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('discovery-kids---dolphin-discovery-usa', 'NDS', 'Discovery Kids - Dolphin Discovery (USA)', '2009', 'Educational', '1st Playable Productions', '1', 'Nature Exploration', 'Virtual pet simulation and education.', 'Care for dolphins and learn about marine life.', 'Ocean-themed pet and learning adventure.', 'Discovery Kids: Dolphin Discovery lets you swim with and train dolphins. Perform tricks, manage their health, and learn fascinating facts about these intelligent sea creatures in a fun, interactive way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('discovery-kids---kitten-corner-usa-enfres', 'NDS', 'Discovery Kids - Kitten Corner (USA) (En,Fr,Es)', '2009', 'Educational', '1st Playable Productions', '1', 'Animal Care', 'Virtual pet simulation.', 'Raise, train, and play with various kitten breeds.', 'Adorable feline-focused pet simulation.', 'Kitten Corner allows you to adopt and care for multiple kittens. Use the touch screen to pet and groom them, and play fun mini-games to win accessories for your virtual pets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('discovery-kids---parrot-pals-usa-enfres', 'NDS', 'Discovery Kids - Parrot Pals (USA) (En,Fr,Es)', '2009', 'Educational', '1st Playable Productions', '1', 'Animal Care', 'Virtual pet simulation.', 'Care for and teach tricks to colorful parrots.', 'Unique avian-themed pet simulation.', 'Parrot Pals lets you raise a variety of parrot species. Use the microphone to teach them words and the stylus to play games, creating a personalized bond with your virtual bird.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('discovery-kids---pony-paradise-usa-enfres', 'NDS', 'Discovery Kids - Pony Paradise (USA) (En,Fr,Es)', '2009', 'Educational', '1st Playable Productions', '1', 'Animal Care', 'Virtual pet simulation and horse riding.', 'Manage a pony farm and participate in riding events.', 'Equestrian life simulation for kids.', 'Pony Paradise lets you groom, feed, and ride your very own ponies. Explore the farm, complete daily chores, and customize your ponies with various saddles and accessories in this relaxing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('discovery-kids---puppy-playtime-usa-enfres', 'NDS', 'Discovery Kids - Puppy Playtime (USA) (En,Fr,Es)', '2009', 'Educational', '1st Playable Productions', '1', 'Animal Care', 'Virtual pet simulation.', 'Raise and train puppies to be the best companions.', 'Classic puppy-raising simulation.', 'Puppy Playtime offers a variety of dog breeds to care for. Teach your puppy commands, take them for walks, and participate in dog shows to prove you are the ultimate pet owner.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disgaea-ds-europe-enfr', 'NDS', 'Disgaea DS (Europe) (En,Fr)', '2008', 'Tactical RPG', 'Nippon Ichi Software', '1', 'Strategy Anime', 'Tactical turn-based RPG with grid combat.', 'Lead Laharl to reclaim his throne as the Overlord.', 'Hardcore strategy RPG with infinite depth.', 'Disgaea DS brings the cult classic "Hour of Darkness" to NDS. Features a level cap of 9999, millions of damage points, and the new "Prince of Darkness" mode starring Etna. A must-play for strategy fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disgaea-ds-usa', 'NDS', 'Disgaea DS (USA)', '2008', 'Tactical RPG', 'Nippon Ichi Software', '1', 'Strategy Anime', 'Tactical turn-based RPG with grid combat.', 'Lead Laharl to reclaim his throne as the Overlord.', 'Hardcore strategy RPG with infinite depth.', 'Disgaea DS brings the cult classic "Hour of Darkness" to NDS. Features a level cap of 9999, millions of damage points, and the new "Prince of Darkness" mode starring Etna. A must-play for strategy fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-big-hero-6---battle-in-the-bay-usa', 'NDS', 'Disney Big Hero 6 - Battle in the Bay (USA)', '2014', 'Action', 'WayForward Technologies', '1', 'Animated Action', '2D side-scrolling action-platformer.', 'Battle the robot invasion in San Fransokyo as Hiro and Baymax.', 'High-tech superhero action based on the movie.', 'Disney Big Hero 6: Battle in the Bay continues the story of the film. Control Hiro, Wasabi, Fred, Gogo, and Honey Lemon to defeat enemies and explore levels using their unique high-tech gadgets and combat skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-friends-europe', 'NDS', 'Disney Friends (Europe)', '2009', 'Simulation', 'n-Space', '1', 'Virtual Pet', 'Virtual pet and social simulation.', 'Interact and build friendships with iconic Disney characters.', 'A magical social sim with Stitch, Simba, and more.', 'Disney Friends lets you interact with Stitch, Dory, Simba, and Winnie the Pooh. Use the stylus and microphone to influence their emotions, go on adventures, and discover a virtual world filled with Disney magic.');
