INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-princess---magical-jewels-europe-enfrdeesitnl', 'NDS', 'Disney Princess - Magical Jewels (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Puzzle', 'Disney Interactive', '1', 'Magical Puzzle', '2D puzzle-adventure for children.', 'Help Disney Princesses recover magical jewels and restore peace.', 'Enchanting puzzle journey with Disney''s royals.', 'Disney Princess: Magical Jewels features Ariel, Aurora, Belle, and Snow White. Solve environmental puzzles and play mini-games across themed kingdoms to find the lost jewels and break the evil enchantments.');
