INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-princess---mahou-no-jewel-japan', 'NDS', 'Disney Princess - Mahou no Jewel (Japan)', '2007', 'Puzzle', 'Disney Interactive', '1', 'Magical Puzzle', '2D puzzle-adventure for children.', 'Help Disney Princesses recover magical jewels and restore peace.', 'Enchanting puzzle journey with Disney''s royals.', 'Disney Princess: Magical Jewels features Ariel, Aurora, Belle, and Snow White. Solve environmental puzzles and play mini-games across themed kingdoms to find the lost jewels and break the evil enchantments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diva-girls---diva-ballerina-europe-enfrdeesit', 'NDS', 'Diva Girls - Diva Ballerina (Europe) (En,Fr,De,Es,It)', '2008', 'Rhythm', 'Collision Studios', '1', 'Dance Performance', 'Rhythm and dance simulation.', 'Master ballet routines and win the grand performance.', 'Graceful ballet-themed rhythm game.', 'Diva Girls: Diva Ballerina lets you practice professional ballet steps. Use the stylus to follow the rhythm, customize your dancer''s outfits, and perform on world-famous stages to become a star ballerina.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diva-girls---diva-dancers-europe-enfrdeesit', 'NDS', 'Diva Girls - Diva Dancers (Europe) (En,Fr,De,Es,It)', '2008', 'Rhythm', 'Collision Studios', '1', 'Dance Performance', 'Rhythm and dance simulation.', 'Perform street and pop dance routines to become a superstar.', 'Trendy dance and lifestyle simulation.', 'Diva Girls: Diva Dancers focuses on modern dance styles. Master the choreography, participate in dance-offs, and rise through the ranks of the pop world in this stylish rhythm-based NDS game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diva-girls---divas-on-ice-usa-enfres', 'NDS', 'Diva Girls - Divas on Ice (USA) (En,Fr,Es)', '2009', 'Rhythm', 'Collision Studios', '1', 'Dance Performance', 'Figure skating and sports simulation.', 'Master spins and jumps to win the ice skating championship.', 'Competitive figure skating adventure.', 'Known as Princess on Ice, this game challenges you to perform routines on the ice. Use the touch screen to execute complex maneuvers and impress the judges with your timing and fashion choices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diva-girls---making-the-music-europe-enfrdeesit', 'NDS', 'Diva Girls - Making the Music (Europe) (En,Fr,De,Es,It)', '2008', 'Rhythm', 'Collision Studios', '1', 'Music Performance', 'Music creation and rhythm game.', 'Compose hit songs and perform them for a live audience.', 'Fun music industry and production sim.', 'Diva Girls: Making the Music allows you to experience the life of a pop star. Write lyrics, mix tracks, and perform your creations in various venues as you build your career in the music industry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diva-girls---princess-on-ice-2-europe-enfrdeesit', 'NDS', 'Diva Girls - Princess on Ice 2 (Europe) (En,Fr,De,Es,It)', '2009', 'Rhythm', 'Collision Studios', '1', 'Ice Skating Dance', 'Figure skating and sports simulation.', 'Master spins and jumps to win the ice skating championship.', 'Competitive figure skating adventure.', 'The sequel to Princess on Ice, featuring more complex routines, refined touch controls, and deeper customization for your skaters as they aim for international gold medals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dj-star-europe-enfrdeesit', 'NDS', 'DJ Star (Europe) (En,Fr,De,Es,It)', '2008', 'Rhythm', 'Neko Entertainment', '1', 'DJ Music', 'Rhythm and music simulation.', 'Scratch, mix, and perform as a professional DJ.', 'Interactive turntable and DJ career sim.', 'DJ Star turns your NDS into a professional mixer. Use the stylus to scratch, cross-fade, and master over 40 tracks. Progress from house parties to massive stadium concerts in your quest for DJ fame.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dk---jungle-climber-usa', 'NDS', 'DK - Jungle Climber (USA)', '2007', 'Platformer', 'Paon', '1', 'Jungle Platformer', '2D platforming with swing mechanics.', 'Climb and swing through the jungle to stop King K. Rool.', 'Innovative swing-based Donkey Kong platformer.', 'DK: Jungle Climber uses the L and R buttons to control Donkey Kong''s hands. Swing through vibrant levels, solve puzzles, and collect bananas in this unique follow-up to DK: King of Swing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doctor-who---evacuation-earth-europe', 'NDS', 'Doctor Who - Evacuation Earth (Europe)', '2010', 'Adventure', 'Sumo Digital', '1', 'Sci-Fi Adventure', 'Adventure and puzzle-solving.', 'Help the 11th Doctor and Amy Pond save the Earth from evacuation.', 'Official Doctor Who sci-fi adventure.', 'Doctor Who: Evacuation Earth features an original story where you must help the Doctor solve logic puzzles and navigate high-stakes scenarios to stop a galactic threat from destroying humanity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doctor-who-europe', 'NDS', 'Doctor Who (Europe)', '2007', 'Adventure', 'Saffire', '1', 'Sci-Fi Adventure', 'Adventure and puzzle-solving.', 'Help the 11th Doctor and Amy Pond save the Earth from evacuation.', 'Official Doctor Who sci-fi adventure.', 'Doctor Who: Evacuation Earth features an original story where you must help the Doctor solve logic puzzles and navigate high-stakes scenarios to stop a galactic threat from destroying humanity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dodge-racing---charger-vs-challenger-usa-enfres', 'NDS', 'Dodge Racing - Charger vs Challenger (USA) (En,Fr,Es)', '2008', 'Racing', 'Firebrand Games', '1', 'Arcade Racing', 'Arcade racing with licensed vehicles.', 'Race classic and modern Dodge cars to win championships.', 'Muscle car racing with Charger and Challenger.', 'Dodge Racing puts you behind the wheel of iconic muscle cars. Master high-speed tracks, customize your vehicle''s performance, and prove which Dodge model reigns supreme in this fast-paced racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-europe', 'NDS', 'Dogz (Europe)', '2006', 'Simulation', 'Studio Mythos', '1', 'Virtual Pet', 'Virtual pet simulation.', 'Adopt, raise, and train a variety of puppy breeds.', 'The NDS debut of the classic pet sim.', 'Dogz lets you choose your favorite puppy. Use the touch screen to feed, groom, and play with your pet. Teach them tricks and enter competitions to show off your puppy''s skills and style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-europe-enfrdeesit', 'NDS', 'Dogz (Europe) (En,Fr,De,Es,It)', '2006', 'Simulation', 'Studio Mythos', '1', 'Virtual Pet', 'Virtual pet simulation.', 'Adopt, raise, and train a variety of puppy breeds.', 'The NDS debut of the classic pet sim.', 'Dogz lets you choose your favorite puppy. Use the touch screen to feed, groom, and play with your pet. Teach them tricks and enter competitions to show off your puppy''s skills and style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-usa', 'NDS', 'Dogz (USA)', '2006', 'Simulation', 'Studio Mythos', '1', 'Virtual Pet', 'Virtual pet simulation.', 'Adopt, raise, and train a variety of puppy breeds.', 'The NDS debut of the classic pet sim.', 'Dogz lets you choose your favorite puppy. Use the touch screen to feed, groom, and play with your pet. Teach them tricks and enter competitions to show off your puppy''s skills and style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-2-europe-enfrdeesit', 'NDS', 'Dogz 2 (Europe) (En,Fr,De,Es,It)', '2007', 'Simulation', 'Studio Mythos', '1', 'Virtual Pet', 'Virtual pet and social simulation.', 'Raise puppies and interact with them in a detailed world.', 'Expanded pet care and social adventure.', 'Dogz 2 offers more breeds, more toys, and more activities. Build a stronger bond with your pets through improved touch interactions and explore new environments with your virtual puppies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokapon-journey-usa', 'NDS', 'Dokapon Journey (USA)', '2008', 'Party RPG', 'Sting', '4', 'Board RPG', 'Hybrid board game and RPG.', 'Earn more money and fame than your rivals to save the kingdom.', 'Competitive and chaotic friendship-destroying RPG.', 'Dokapon Journey blends the mechanics of a board game with turn-based RPG combat. Sabotage your friends, complete quests, and become the hero—or the villain—in this quirky and cutthroat adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokapon-journey!---nakayoku-kenka-shite-japan', 'NDS', 'Dokapon Journey! - Nakayoku Kenka Shite (Japan)', '2008', 'Party RPG', 'Sting', '4', 'Board RPG', 'Hybrid board game and RPG.', 'Earn more money and fame than your rivals to save the kingdom.', 'Competitive and chaotic friendship-destroying RPG.', 'Dokapon Journey blends the mechanics of a board game with turn-based RPG combat. Sabotage your friends, complete quests, and become the hero—or the villain—in this quirky and cutthroat adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doki-doki-majo-shinpan-duo-japan', 'NDS', 'Doki Doki Majo Shinpan Duo (Japan)', '2009', 'Visual Novel', 'SN Systems', '1', 'Ecchi Comedy', 'Visual novel and investigation.', 'Identify witches hidden among the students using touch.', 'Cult-classic supernatural investigation game.', 'In this controversial sequel, play as Akuji as he hunts for witches. Use the "Touch Check" system to find the Mark of the Witch in this blend of comedy, fan-service, and supernatural mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doki-doki-majo-shinpan!-japan', 'NDS', 'Doki Doki Majo Shinpan! (Japan)', '2007', 'Visual Novel', 'SN Systems', '1', 'Ecchi Comedy', 'Visual novel and investigation.', 'Identify witches hidden among the students using touch.', 'Cult-classic supernatural investigation game.', 'The original Doki Doki Majo Shinpan introduces the concept of witch hunting in a school setting. Balance school life with your secret mission to expose witches through dialogue and investigative mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doki-majo-plus-japan', 'NDS', 'Doki Majo Plus (Japan)', '2008', 'Visual Novel', 'SN Systems', '1', 'Ecchi Comedy', 'Visual novel and investigation.', 'Identify witches hidden among the students using touch.', 'Cult-classic supernatural investigation game.', 'An enhanced version of the original game, featuring refined graphics, new scenarios, and additional characters, providing the complete experience of the quirky witch-hunting series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokodemo-pilates-japan', 'NDS', 'Dokodemo Pilates (Japan)', '2007', 'Fitness', 'Nintendo', '1', 'Wellness Training', 'Health and fitness simulation.', 'Follow interactive Pilates routines to improve your health.', 'Portable Pilates instructor for NDS.', 'Dokodemo Pilates provides step-by-step guides for various exercises. Track your progress, learn proper techniques, and enjoy a virtual workout session wherever you go with your handheld console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokodemo-raku-raku!---ds-kakeibo-japan', 'NDS', 'Dokodemo Raku Raku! - DS Kakeibo (Japan)', '2007', 'Finance', 'Nintendo', '1', 'Life Management', 'Financial management and digital ledger.', 'Manage your household budget and track your expenses.', 'Practical finance and household ledger tool.', 'DS Kakeibo turns your NDS into a digital budget book. Categorize your spending, view helpful charts of your financial habits, and learn how to save money with this useful Japanese organization tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokodemo-yoga-japan', 'NDS', 'Dokodemo Yoga (Japan)', '2007', 'Fitness', 'Nintendo', '1', 'Wellness Training', 'Health and fitness simulation.', 'Master Yoga poses and relaxation techniques for wellness.', 'Portable Yoga and wellness guide.', 'Dokodemo Yoga offers a variety of routines for beginners and experts. Use the stylus to navigate poses and follow guided breathing exercises to reduce stress and improve flexibility.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokonjou-shougakusei-bon-biita---hadaka-no-choujou-ketsusen!!---biita-vs-dokuro-dei!-japan', 'NDS', 'Dokonjou Shougakusei Bon Biita - Hadaka no Choujou Ketsusen!! - Biita vs Dokuro Dei! (Japan)', '2007', 'Action', 'Bandai Namco Games', '1', 'Anime Comedy', 'Comedic action-adventure with mini-games.', 'Defeat Dokuro Dei in a series of over-the-top challenges.', 'Wacky school-life action based on the manga.', 'Join the eccentric Bon Biita in this high-energy Japanese adventure. Navigate through a variety of bizarre mini-games and action stages to prove you are the ultimate elementary student in this colorful manga adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dolphin-island---underwater-adventures-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Dolphin Island - Underwater Adventures (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2011', 'Simulation', 'Raylight Games', '1', 'Animal Care', 'Marine life simulation and conservation.', 'Manage a tropical island and care for various marine animals.', 'NDSi enhanced ocean life simulation.', 'Dolphin Island: Underwater Adventures lets you become a marine park manager. Train dolphins, heal sick animals, and protect the ecosystem. The NDSi features allow for deeper interaction and photo modes with your aquatic friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dolphin-island-europe-enfrdeesitnl', 'NDS', 'Dolphin Island (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Simulation', 'Raylight Games', '1', 'Animal Care', 'Marine life simulation and conservation.', 'Manage a tropical island and care for various marine animals.', 'Tropical marine park management sim.', 'Rescue and train marine animals on a beautiful island. Learn about biology and conservation while managing your park''s reputation, ensuring your dolphins and whales are healthy and happy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dolphin-trainer-europe-enfrdeesitnlpt', 'NDS', 'Dolphin Trainer (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2010', 'Simulation', 'Raylight Games', '1', 'Animal Training', 'Animal training and performance simulation.', 'Train your dolphin to perform complex tricks and shows.', 'Professional dolphin training simulator.', 'Master the art of animal communication. Use the stylus to guide your dolphin through hoops and jumps, managing their diet and mood to put on the most spectacular shows for the audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('don-bluth-presents---dragons-lair-usa', 'NDS', 'Don Bluth Presents - Dragon''s Lair (USA)', '2007', 'Adventure', 'Digital Leisure', '1', 'Arcade Adventure', 'Interactive cinema and quick-time event (QTE).', 'Navigate the castle of Singe the Dragon to rescue Daphne.', 'The legendary laserdisc arcade classic.', 'Dragon''s Lair brings Don Bluth''s iconic hand-drawn animation to the NDS. Test your reflexes with precision timing as you guide Dirk the Daring through a trap-filled castle in this cinematic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('don-king-boxing-europe-enfrdeesit', 'NDS', 'Don King Boxing (Europe) (En,Fr,De,Es,It)', '2009', 'Sports', '2K Sports', '2', 'Boxing Simulation', '3D boxing simulation and career mode.', 'Rise through the ranks to become the world champion.', 'Realistic and intense portable boxing.', 'Experience the drama of the ring with Don King Boxing. Train your fighter, manage your career stats, and engage in tactical 3D bouts that emphasize timing and power using the dual-screen interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('don-king-boxing-usa-enfrdeesit', 'NDS', 'Don King Boxing (USA) (En,Fr,De,Es,It)', '2009', 'Sports', '2K Sports', '2', 'Boxing Simulation', '3D boxing simulation and career mode.', 'Rise through the ranks to become the world champion.', 'Realistic and intense portable boxing.', 'Experience the drama of the ring with Don King Boxing. Train your fighter, manage your career stats, and engage in tactical 3D bouts that emphasize timing and power using the dual-screen interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dondake-sports-101-japan', 'NDS', 'Dondake Sports 101 (Japan)', '2006', 'Sports', 'Nintendo', '4', 'Party Sports', 'Multi-sport mini-game collection.', 'Compete in 101 different sports challenges.', 'Massive library of quick-fire sports games.', 'Dondake Sports 101 is an arcade-style collection offering everything from track and field to niche sports. Perfect for short play sessions, it challenges your reflexes and stylus speed across dozens of events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong---jungle-climber-europe-enfrdeesit', 'NDS', 'Donkey Kong - Jungle Climber (Europe) (En,Fr,De,Es,It)', '2007', 'Platformer', 'Paon', '1', 'Jungle Platformer', '2D platforming with swing mechanics.', 'Chase King K. Rool through the sky to save the Crystal Bananas.', 'Unique dual-screen climbing platformer.', 'Donkey Kong: Jungle Climber uses the L and R buttons to control DK''s grip. Swing through complex levels, team up with Diddy Kong, and use the touch screen for special abilities in this innovative platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong---jungle-climber-japan', 'NDS', 'Donkey Kong - Jungle Climber (Japan)', '2006', 'Platformer', 'Paon', '1', 'Jungle Platformer', '2D platforming with swing mechanics.', 'Chase King K. Rool through the sky to save the Crystal Bananas.', 'Unique dual-screen climbing platformer.', 'Donkey Kong: Jungle Climber uses the L and R buttons to control DK''s grip. Swing through complex levels, team up with Diddy Kong, and use the touch screen for special abilities in this innovative platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-in-super-mario-64-ds', 'NDS', 'Donkey Kong in Super Mario 64 DS', '2004', 'Platformer', 'Nintendo', '1', '3D Platformer', '3D platforming mod.', 'Explore Peach''s castle and levels as Donkey Kong.', 'Fan-made character swap for the N64 remake.', 'A creative modification that lets you play Super Mario 64 DS as the leader of the DK crew. Experience the classic 3D levels with DK''s unique presence, adding a fresh twist to the iconic Mushroom Kingdom adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-xote-europe-enfrdeesit', 'NDS', 'Donkey Xote (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Revistronic', '1', 'Animated Adventure', 'Action-adventure based on the animated film.', 'Follow the donkey Rucio on his quest to find the Knight of the Moon.', 'Humorous medieval adventure based on the movie.', 'Donkey Xote lets you play through the story of the film. Engage in mini-games, solve environmental puzzles, and experience the satirical world of Don Quixote through the eyes of his faithful (and talkative) companions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doodle-hex-europe-enfrdeesit', 'NDS', 'Doodle Hex (Europe) (En,Fr,De,Es,It)', '2010', 'Puzzle', 'Barnstorm Games', '1', 'Logic Drawing', 'Rhythm-based arena combat and spellcasting.', 'Draw runes on the touch screen to cast spells and defeat rivals.', 'Innovative musical combat and rune drawing.', 'Doodle Hex combines rhythm and strategy. Draw complex runes in time with the music to cast offensive and defensive spells. Duel against quirky characters in a magical tournament to become the top caster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-&-friends---fantastic-flight-europe', 'NDS', 'Dora & Friends'' - Fantastic Flight (Europe)', '2015', 'Adventure', 'High Voltage Software', '1', 'Kids Adventure', 'Educational adventure for young children.', 'Help Dora and her friends on a magical flight to save the day.', 'Flying-themed learning adventure for kids.', 'Join Dora on an aerial journey! Kids solve simple math and logic puzzles using the stylus to guide Dora''s flight, promoting problem-solving and basic educational skills in a fun, safe environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-&-friends---pet-shelter-europe-enfresnl', 'NDS', 'Dora & Friends'' - Pet Shelter (Europe) (En,Fr,Es,Nl)', '2013', 'Simulation', 'High Voltage Software', '1', 'Pet Care', 'Pet care and animal rescue simulation.', 'Rescue, heal, and care for animals until they find homes.', 'Animal rescue and nursing for preschoolers.', 'Dora & Friends: Pet Shelter teaches empathy and responsibility. Feed, groom, and play with various animals while learning about their needs through interactive touch-screen activities designed for young children.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-&-kai-lans-pet-shelter-usa', 'NDS', 'Dora & Kai-Lan''s Pet Shelter (USA)', '2013', 'Simulation', 'High Voltage Software', '1', 'Pet Care', 'Pet care and animal rescue simulation.', 'Rescue, heal, and care for animals until they find homes.', 'Crossover pet rescue with Dora and Kai-Lan.', 'Join Dora and Ni Hao, Kai-Lan in a collaborative effort to save pets. Clean, feed, and nurture animals using the stylus in this educational and heartwarming pet care simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-puppy-usa', 'NDS', 'Dora Puppy (USA)', '2009', 'Simulation', 'High Voltage Software', '1', 'Pet Care', 'Virtual pet simulation.', 'Adopt and train a puppy with Dora the Explorer.', 'Adorable puppy-raising for young fans.', 'Help Dora take care of her new puppy! Learn how to feed, bathe, and teach tricks to your virtual pet. It’s a perfect introductory pet sim for toddlers that encourages routine and care.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-the-explorer---dora-puppy-europe', 'NDS', 'Dora the Explorer - Dora Puppy (Europe)', '2009', 'Simulation', 'High Voltage Software', '1', 'Pet Care', 'Virtual pet simulation.', 'Adopt and train a puppy with Dora the Explorer.', 'Adorable puppy-raising for young fans.', 'Help Dora take care of her new puppy! Learn how to feed, bathe, and teach tricks to your virtual pet. It’s a perfect introductory pet sim for toddlers that encourages routine and care.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-the-explorer---dora-saves-the-mermaids-europe', 'NDS', 'Dora the Explorer - Dora Saves the Mermaids (Europe)', '2009', 'Adventure', 'High Voltage Software', '1', 'Kids Adventure', 'Educational adventure and platforming.', 'Help Dora save the Mermaid Kingdom from an evil octopus.', 'Underwater-themed learning adventure.', 'Dive into the ocean with Dora. Kids use the microphone and stylus to help Dora swim, solve puzzles, and collect items to restore the beauty of the Mermaid Kingdom while learning Spanish and logic.');
