INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doras-big-birthday-adventure-europe-enfrnl', 'NDS', 'Dora''s Big Birthday Adventure (Europe) (En,Fr,Nl)', '2008', 'Adventure', 'High Voltage Software', '1', 'Kids Adventure', 'Educational mini-games and adventure.', 'Help Dora get to her big birthday party on time.', 'Birthday-themed learning celebration.', 'Celebrate Dora''s big day! Navigate through different lands, solve puzzles to clear the path, and play birthday-themed mini-games in this festive educational adventure for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doras-big-birthday-adventure-usa', 'NDS', 'Dora''s Big Birthday Adventure (USA)', '2010', 'Adventure', 'High Voltage Software', '1', 'Kids Adventure', 'Educational mini-games and adventure.', 'Help Dora get to her big birthday party on time.', 'Birthday-themed learning celebration.', 'Celebrate Dora''s big day! Navigate through different lands, solve puzzles to clear the path, and play birthday-themed mini-games in this festive educational adventure for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doras-cooking-club-europe-enfrnl', 'NDS', 'Dora''s Cooking Club (Europe) (En,Fr,Nl)', '2010', 'Simulation', 'High Voltage Software', '1', 'Cooking Kids', 'Cooking simulation and educational math.', 'Prepare recipes for a fiesta while learning basic math.', 'Culinary learning adventure for toddlers.', 'Dora''s Cooking Club combines kitchen fun with early education. Chop, stir, and bake recipes using the stylus while practicing counting, shapes, and measurements in a colorful kitchen setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doras-cooking-club-usa', 'NDS', 'Dora''s Cooking Club (USA)', '2010', 'Simulation', 'High Voltage Software', '1', 'Cooking Kids', 'Cooking simulation and educational math.', 'Prepare recipes for a fiesta while learning basic math.', 'Culinary learning adventure for toddlers.', 'Dora''s Cooking Club combines kitchen fun with early education. Chop, stir, and bake recipes using the stylus while practicing counting, shapes, and measurements in a colorful kitchen setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dorabase---doraemon-super-baseball-gaiden---dramatic-stadium-japan', 'NDS', 'Dorabase - Doraemon Super Baseball Gaiden - Dramatic Stadium (Japan)', '2008', 'Sports', 'Bandai Namco Games', '4', 'Cartoon Baseball', 'Strategic baseball and RPG.', 'Win the space baseball tournament with Doraemon and friends.', 'Futuristic anime baseball with gadgets.', 'Dorabase features a unique mix of baseball and RPG mechanics. Use Doraemon''s secret gadgets to change the outcome of the game and build your dream team to win the dramatic stadium tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dorabase-2---nettou-ultra-stadium-japan', 'NDS', 'Dorabase 2 - Nettou Ultra Stadium (Japan)', '2011', 'Sports', 'Bandai Namco Games', '4', 'Cartoon Baseball', 'Strategic baseball and RPG.', 'Compete in the Ultra Stadium tournament to become champions.', 'Expanded anime baseball sequel.', 'The sequel to the hit baseball game features more teams, refined touch-screen batting and pitching, and even more crazy gadgets. Lead your robotic cat team to victory in this high-energy sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---nobita-no-kyouryuu-2006-ds-japan', 'NDS', 'Doraemon - Nobita no Kyouryuu 2006 DS (Japan)', '2006', 'Adventure', 'Fujiko F. Fujio Productions', '1', 'Anime Adventure', 'Turn-based RPG and monster collection.', 'Befriend and train dinosaurs to save the prehistoric world.', 'Epic prehistoric RPG based on the movie.', 'Follow the plot of the 2006 film. Explore ancient lands, collect various dinosaur species, and engage in tactical battles as Nobita and Doraemon in this deep handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---nobita-no-shin-makai-daibouken-ds-japan', 'NDS', 'Doraemon - Nobita no Shin Makai Daibouken DS (Japan)', '2007', 'Adventure', 'Fujiko F. Fujio Productions', '1', 'Anime Fantasy', 'Turn-based RPG and exploration.', 'Explore a magical world of wizards and stop a demonic threat.', 'Magical fantasy RPG based on the movie.', 'Based on "The New Nobita''s Great Adventure into the Underworld," this game features a card-based battle system and a magical storyline where Doraemon and friends must save the world from demons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---nobita-to-midori-no-kyojinden-ds-japan', 'NDS', 'Doraemon - Nobita to Midori no Kyojinden DS (Japan)', '2008', 'Adventure', 'Fujiko F. Fujio Productions', '1', 'Anime Adventure', '2D side-scrolling platformer.', 'Save the Green Planet and protect the forest.', 'Ecological adventure based on the movie.', 'In this platforming journey, Nobita and a sentient seedling named Kibou must navigate lush environments. Use Doraemon''s gadgets to overcome obstacles and fight to save the environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-sequence---the-q-virus-invasion-europe-enfrdeesit', 'NDS', 'Double Sequence - The Q-Virus Invasion (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Digital Leisure', '1', 'Logic Puzzle', 'Puzzle and color-matching strategy.', 'Stop the viral invasion by aligning sequenced blocks.', 'Space-themed sequence puzzle challenge.', 'Double Sequence: The Q-Virus Invasion is a fast-paced logic game. Players must match colored blocks and patterns to clear the screen and halt an alien virus, featuring multiple difficulty levels and addictive handheld strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-sequence---the-q-virus-invasion-usa-enfrdeesit', 'NDS', 'Double Sequence - The Q-Virus Invasion (USA) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Digital Leisure', '1', 'Logic Puzzle', 'Puzzle and color-matching strategy.', 'Stop the viral invasion by aligning sequenced blocks.', 'Space-themed sequence puzzle challenge.', 'Double Sequence: The Q-Virus Invasion is a fast-paced logic game. Players must match colored blocks and patterns to clear the screen and halt an alien virus, featuring multiple difficulty levels and addictive handheld strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dowajwo!-rhythm-hero-korea', 'NDS', 'Dowajwo! Rhythm Hero (Korea)', '2010', 'Rhythm', 'NEOWIZ', '1', 'Music Rhythm', 'Rhythm-action and comedy adventure.', 'Tap and slide to the beat to help people in need.', 'Korean version of Elite Beat Agents.', 'Dowajwo! Rhythm Hero features the same high-energy gameplay as Osu! Tatakae! Ouendan. Follow the rhythmic prompts on the touch screen to inspire characters and solve their over-the-top problems through the power of dance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-kawashimas-brain-training---how-old-is-your-brain-europe-enfrdeesitnl', 'NDS', 'Dr Kawashima''s Brain Training - How Old Is Your Brain (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Puzzle', 'Nintendo', '1', 'Brain Training', 'Mental exercise and daily brain training.', 'Lower your "Brain Age" through daily logic and math drills.', 'The definitive NDS brain exercise game.', 'Dr Kawashima''s Brain Training offers a series of scientifically designed mini-games. From quick math to Stroop tests, use the stylus and microphone to sharpen your mind and track your cognitive progress daily.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-reiner-knizias-brainbenders-europe-enfrdeesit', 'NDS', 'Dr Reiner Knizia''s Brainbenders (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', '10tacle Studios', '1', 'Logic Puzzle', 'Logic and mathematical puzzle collection.', 'Solve complex board game-style puzzles by Reiner Knizia.', 'High-level logic and strategy brainteasers.', 'Designed by the world-renowned board game creator, Brainbenders features over 100 puzzles that challenge your numerical and spatial reasoning. A perfect title for fans of deep, structured mental challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-jekyll-&-mr-hyde---enigmes-&-objets-caches-france', 'NDS', 'Dr. Jekyll & Mr. Hyde - Enigmes & Objets Caches (France)', '2010', 'Puzzle', 'Microïds', '1', 'Hidden Object', 'Hidden object and mystery adventure.', 'Solve the mystery of the dual personality in Victorian London.', 'Dark atmospheric hidden object quest.', 'Immerse yourself in the classic gothic tale. Search detailed Victorian scenes for clues, solve environmental puzzles, and uncover the truth behind Dr. Jekyll’s experiments in this French-language investigative title.');